(window.GIM_TS=window.GIM_TS||{})["Yevamot.9"]={"from":216,"a":[["\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר ש\u0003לא בעל\u0004 אותה אחרי שגדלה? ואם כן סבור רב שאפילו כשלא בעל נישואיה קיימים! ודוחים: \u0003לא,\u0004 מדובר שכן \u0003בעל.\u0004 ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר כש\u0003בעל — מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003שמואל?\u0004 שהרי אם בא עליה בהיותה גדולה, הרי עשה בה מעשה נישואין גמור בהיותה כבר גדולה! ומשיבים: \u0003קסבר\u0004 \u0005[סבור]\u0006 שמואל: \u0003כל הבועל — על דעת קדושין הראשונים הוא בועל,\u0004 ואינו מתכוון בבעילה זו לעשות קנין קידושין חדש.","ושואלים: אם זה הוא בסיס המחלוקת, \u0003והא פליגי בה חדא זימנא\u0004 \u0005[והרי\u0006 כבר \u0005נחלקו בכך פעם אחת],\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בבעיה הבאה: אשה ש\u0003קדשה\u0004 בעלה \u0003על תנאי, וכנסה סתם\u0004 בלא לחזור ולפרש את התנאי, ולא נתקיים תנאי זה — \u0003רב אמר: צריכה הימנו גט, ושמואל אמר: אינה צריכה הימנו גט.\u0004","ומסבירים: \u0003רב אמר צריכה הימנו גט\u0004 — \u0003כיון דנסבה\u0004 \u0005[שנשא אותה]\u0006 אנו מניחים \u0003כי אחולי אחליה לתנאיה\u0004 \u0005[מחל על תנאו]\u0006 וכנסה כאשתו גמורה, למרות שהתנאי לא התקיים. \u0003ושמואל אמר: אינה צריכה הימנו גט,\u0004 כי \u0003כל הבועל — על דעת קדושין הראשונים הוא בועל,\u0004 והתנאי שהתנה בשעת קידושין עומד בעינו, ומאחר שלא נתקיים — בטלו הנישואין. ואם כן, נמצא שכבר נחלקו רב ושמואל באותה בעיה עצמה!","ומשיבים: \u0003צריכא\u0004 \u0005[צריכים]\u0006 שני הדברים להיאמר, \u0003דאי איתמר\u0004 \u0005[שאילו נאמרה]\u0006 רק ההלכה \u0003ההיא,\u0004 בקידושין על תנאי, הייתי אומר: דווקא \u0003ב\u0004הלכה \u0003ההיא קאמר\u0004 \u0005[אמר]\u0006 \u0003רב\u0004 שצריכה ממנו גט, \u0003משום דאיכא תנאה\u0004 \u0005[שיש תנאי]\u0006 שלא התקיים, \u0003וכיון\u0004 ש\u0003בעל\u0004 אותה, ודאי \u0003אחליה לתנאיה\u0004 \u0005[מחל על תנאו],\u0006 \u0003אבל בהא, אימא מודה ליה\u0004 \u0005[בזו,\u0006 בקידושי קטנה, \u0005אמור\u0006 ש\u0005מודה לו],\u0006 \u0003לשמואל,\u0004 שלא עלה בדעתו לחזור ולבעול לשם קידושין חדשים, ולכן על דעת קידושין הראשונים הוא בועל. ולהיפך: \u0003ואי איתמר בהא\u0004 \u0005[ואם\u0006 היה \u0005נאמר\u0006 רק \u0005בזו]\u0006 הייתי אומר: \u0003בהך קאמר\u0004 \u0005[בזו,\u0006 בנישואי קטנה, \u0005אמר]\u0006 \u0003שמואל\u0004 שאינה צריכה גט מן השני, \u0003אבל בהך\u0004 \u0005[בזו]\u0006 של קידושין על תנאי, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003מודה ליה\u0004 \u0005[לו]\u0006 \u0003לרב,\u0004 על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 המחלוקת להתפרש בשני המקרים.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב כי\u0004 \u0005[\u0006ש\u0005כאשר]\u0006 \u0003בעל\u0004 אותה לאחר שגדלה — \u0003אין\u0004 \u0005[כן]\u0006 חלו נישואין ראשונים, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא בעל — לא\u0004 חלו? \u0003והא ההיא עובדא דהוה\u0004 \u0005[והרי מעשה שהיה]\u0006 \u0003ב\u0004עיר \u0003נרש ואיקדישה\u0004 \u0005[והתקדשה\u0006 אשה\u0005]\u0006 \u0003כשהיא קטנה, וגדלה, ואותביה אבי כורסייא\u0004 \u0005[והושיבה\u0006 הבעל \u0005באפריון,\u0006 בחופה\u0005]\u0006 ועדיין לא בא עליה, \u0003ואתא אחרינא\u0004 \u0005[ובא אליו]\u0006 \u0003וחטפה מיניה\u0004 \u0005[ממנו]\u0006 מן הבעל, \u0003ורב ברונא ורב חננאל תלמידי דרב הוו התם\u0004 \u0005[היו שם]\u0006 \u0003ולא הצריכוה\u0004 לקבל \u0003גיטא מבתרא\u0004 \u0005[גט מן האחרון],\u0006 שראו זאת כאונס בלבד ולא נעשה בה כל קנין, ולא חששו לומר שקידושיה הראשונים בהיותה קטנה לא תפסו!","\u0003אמר רב פפא:\u0004 יש להבדיל, כי \u0003ב\u0004עיר \u0003נרש\u0004 בתחילה \u0003מינסב נסיבי\u0004 \u0005[נושאים]\u0006 אשה ובועלים אותה, \u0003והדר מותבי אבי כורסייא\u0004 \u0005[ואחר כך מושיבים\u0006 אותה \u0005באפריון],\u0006 ואם כן, במקרה זה כבר בא עליה הבעל משגדלה, והנישואין תופסים אפילו לשיטת רב. \u0003רב אשי אמר:\u0004 טעם אחר היה בדבר, שמכיון ש\u0003הוא,\u0004 החוטף, \u0003עשה שלא כהוגן — לפיכך עשו בו שלא כהוגן,\u0004 שביטלו את תוקף מעשיו של החוטף \u0003ואפקעינהו רבנן לקידושי מיניה\u0004 \u0005[והפקיעו חכמים את הקידושין ממנו]\u0006 מן השני.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: תינח דקדיש בכספא\u0004 \u0005[נניח שקידש\u0006 השני \u0005בכסף]\u0006 ואז הפקירו חכמים את הכסף הזה, ובטלו הקידושין, אולם אם \u0003קדיש\u0004 \u0005[קידש]\u0006 \u0003בביאה מאי\u0004 \u0005[מה]\u0006 יכולים חכמים לעשות! ואיך יכולים חכמים לבטל ביאה שנעשתה? ומשיבים: \u0003שויוה רבנן\u0004 \u0005[עשו חכמים]\u0006 את \u0003בעילתו בעילת זנות,\u0004 שאינה יוצרת קשר קידושין. ולענין המחלוקת במשנה, \u0003אמר רב יהודה אמר שמואל: הלכה כר' אליעזר\u0004 ומלמדים את הקטנה למאן. \u0003וכן אמר ר' אלעזר: הלכה כר' אליעזר\u0004 בענין זה.","\u0003מי שהיה נשוי לשתי יתומות קטנות\u0004 הזרות זו לזו, \u0003ומת — ביאתה או חליצתה של אחת מהם פוטרת\u0004 את \u0003צרתה,\u0004 מאחר שתוקף הנישואין של שתיהן שווה, בה במידה שהנישואין תופסים, הייבום פוטר את הצרה. \u0003וכן שתי חרשות\u0004 שהיו נשואות לאחד, ומת — ביאתה או חליצתה של אחת מהן פוטרת את צרתה. אם היתה לאדם אשה אחת \u0003קטנה ו\u0004אשה נוספת \u0003חרשת,\u0004 ומת — \u0003אין ביאת אחת מהן פוטרת צרתה,\u0004 שאף שנישואי שתיהן מדברי סופרים, אין תפיסת הנישואין בהן מאותו סוג, ואין להכריע לאיזו מהן תוקף גדול יותר כדי לדחות את השניה.","היתה אחת מהן \u0003פקחת ו\u0004אחת \u0003חרשת — ביאת\u0004 היבם על \u0003הפקחת פוטרת\u0004 את \u0003החרשת,\u0004 שהרי נישואיה וייבומה הם מן התורה, \u0003ואין ביאת החרשת פוטרת את הפקחת.\u0004 וכן אם היתה אחת \u0003גדולה ו\u0004אחת \u0003קטנה — ביאת הגדולה פוטרת\u0004 את \u0003הקטנה, ואין ביאת הקטנה פוטרת\u0004 את \u0003הגדולה.\u0004","מן האמור במשנה בשתי חרשות נובע, שחליצת חרשת יש לה תוקף. ותוהים: \u0003ו\u0004כי \u0003חרשת בת חליצה היא? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003חרש שנחלץ, וחרשת שחלצה, ו\u0004כן \u0003חולצת מן הקטן — חליצתה פסולה!\u0004","\u0003אמר רב גידל אמר רב:\u0004 במשנה מדובר לא על חליצה בחרשת אלא על \u0003ביאה\u0004 באחת החרשות, שודאי קונה. \u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר כאן ב\u0003חליצה\u0004 — \u0003כאן\u0004 במשנתנו מדובר \u0003בחרשת מעיקרא\u0004 \u0005[מתחילתה]\u0006 שבזמן שנישאה היתה חרשת, ו\u0003כאן\u0004 במשנה הפוסלת חליצת חרשת, מדובר \u0003ב\u0004זו שהיתה \u0003פקחת\u0004 בשעת הנישואין \u0003ואחר כך נתחרשה.\u0004","ומהו ההבדל: \u0003חרשת מעיקרא\u0004 \u0005[מתחילתה],\u0006 \u0003כי היכי דעל\u0004 \u0005[כפי שנכנס]\u0006 תוקף הנישואין הקלושים עם הבעל הראשון — \u0003הכי נפק\u0004 \u0005[כך יצא]\u0006 החוצה על ידי היבם, אפילו בחליצה גרועה, ואולם \u0003פקחת ואחר כך נתחרשה — לא, דמעכבא\u0004 \u0005[שמעכבת]\u0006 \u0003בה קרייה\u0004 \u0005[הקריאה],\u0006 שהרי אינה יכולה לקרוא מה שהיבמה צריכה לקרוא.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי: ו\u0004כי \u0003חרשת מעיקרא\u0004 \u0005[מתחילתה]\u0006 \u0003בת חליצה היא? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 היו \u0003שני אחין, אחד פקח ואחד חרש,\u0004 שהיו \u0003נשואין לשתי\u0004 נשים \u0003נכריות\u0004 (זרות זו לזו), \u0003אחת פקחת ואחת חרשת, מת\u0004 ה\u0003חרש בעל\u0004 ה\u0003חרשת, מה יעשה\u0004 ה\u0003פקח בעל\u0004 ה\u0003פקחת? — כונס\u0004 את היבמה אם רוצה, אבל אין בה אפשרות של חליצה. \u0003ואם רצה\u0004 אחר כך \u0003להוציא\u0004 אותה — \u0003יוציא\u0004 בגט.","\u0003מת\u0004 ה\u0003פקח בעל\u0004 ה\u0003פקחת, מה יעשה\u0004 ה\u0003חרש בעל\u0004 ה\u0003חרשת? — כונס, ואינו מוציא לעולם\u0004 אף לא על ידי גט, משמע שאין אפשרות לחלוץ לחרשת. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר שם \u0003בחרשת מעיקרא\u0004 \u0005[מתחילתה],\u0006 \u0003וקתני\u0004 \u0005[ושנה]\u0006 \u0003כונס — אין\u0004 \u0005[כן],\u0006"],["\u0003חולץ — לא!\u0004 ובודאי מפני שאינה יכולה לקרוא! ודוחים: \u0003לא,\u0004 מדובר שם \u0003בפקחת ואחר כך נתחרשה,\u0004 שאין תוקף בחליצתה כדי להפקיע את זיקת ייבום שמן התורה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקום אחר, ששנינו: \u0003שני אחין פקחין נשואין שתי נכריות\u0004 (זרות זו לזו), \u0003אחת פקחת ואחת חרשת, מת פקח בעל החרשת, מה יעשה\u0004 ה\u0003פקח בעל\u0004 ה\u0003פקחת? — כונס\u0004 את החרשת, \u0003ואם רוצה\u0004 אחר כך \u0003להוציא — יוציא. מת\u0004 ה\u0003פקח בעל\u0004 ה\u0003פקחת, מה יעשה\u0004 ה\u0003פקח בעל\u0004 ה\u0003חרשת? או חולץ או מייבם.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא],\u0006 \u0003מ\u0004כיון ש\u0003הוא פקח מעיקרא\u0004 \u0005[מתחילתו]\u0006 \u0003היא נמי\u0004 \u0005[גם כן]\u0006 \u0003חרשת מעיקרא\u0004 \u0005[מתחילתה],\u0006 שמדובר במקרים דומים זה לזה, \u0003וקתני\u0004 \u0005[ושנה]\u0006 לגבי החרשת \u0003כונס — אין\u0004 \u0005[כן],\u0006 אבל \u0003חולץ — לא\u0004 שנה, משמע שאפילו לחרשת מתחילתה אין תקנה בחליצה! ודוחים: \u0003מידי איריא\u0004 \u0005[וכי שייכים\u0006 הדברים\u0005]\u0006 ומוכרחים להיות דומים? \u0003הא כדאיתא והא כדאיתא\u0004 \u0005[זו כמו שישנה וזו כמו שישנה],\u0006 שמדובר בבעל שהוא פיקח מתחילתו, אבל החרשת לא היתה חרשת מתחילתה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממקור אחר: \u0003שני אחין, אחד פקח ואחד חרש, נשואין שתי אחיות, אחת פקחת ואחת חרשת. מת חרש בעל חרשת, מה יעשה פקח בעל פקחת? — תצא\u0004 החרשת \u0003משום אחות אשה.\u0004","\u0003מת פקח בעל פקחת מה יעשה חרש בעל חרשת? — מוציא את אשתו\u0004 החרשת \u0003בגט, ואשת אחיו אסורה לעולם.\u0004 כי אינו יכול לכונסה מפני שהיתה אחות אשתו במקצת, ואינה נפטרת בחליצה מפני שאין תוקף בחליצת החרש מכדי לדחות לגמרי זיקת ייבום שמן התורה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בפקח ואחר כך נתחרש\u0004 — אולם שכזה \u0003מי מצי מפיק\u0004 \u0005[האם יכול\u0006 הוא \u0005להוציא\u0006 את אשתו\u0005]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003נתחרשה\u0004 אשתו — \u0003יוציא,\u0004 אם \u0003נשתטית — לא יוציא\u0004 שאם אין בה דעת כלל, אין יכולים לגרשה. אם \u0003נתחרש הוא, או נשתטה — לא יוציא עולמית,\u0004 מפני שנישואיו כשהיה פיקח היה להם תוקף, אבל כעת אין לו דעת גמורה לגרשה.","\u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מדובר \u0003בחרש מעיקרא\u0004 \u0005[מתחילה],\u0006 \u0003ומ\u0004אחר ש\u0003הוא חרש מעיקרא\u0004 \u0005[מתחילתו] —\u0006 \u0003היא נמי\u0004 \u0005[גם כן]\u0006 \u0003חרשת מעיקרא\u0004 \u0005[מתחילתה],\u0006 \u0003ומ\u0004אחר שה\u0003אחיות\u0004 שמדובר בהן כאן היו \u0003חרשות מעיקרא\u0004 \u0005[מתחילה]\u0006 כפי שהוכחנו, \u0003נכריות\u0004 ( זרות זו לזו) \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003חרשות מעיקרא\u0004 \u0005[מתחילה]\u0006 היו, \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 ל\u0003גבי\u0004 ה\u0003נכריות\u0004 ש\u0003כונס — אין\u0004 \u0005[כן],\u0006 \u0003חולץ — לא! אישתיק\u0004 \u0005[שתק]\u0006 רבה, ולא מצא תשובה לשאלה.","\u0003כי אתא לקמיה\u0004 \u0005[כאשר בא\u0006 אביי \u0005לפני]\u0006 \u0003רב יוסף\u0004 וסיפר לו את הענין, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא תותביה מהא\u0004 \u0005[מה טעם אתה מקשה לו מזו]\u0006 שהרי \u0003יכול\u0004 הוא \u0003לשנויי\u0004 \u0005[לתרץ]\u0006 \u0003לך: אחיות\u0004 שמדובר בהן היו \u0003חרשות מעיקרא\u0004 \u0005[מתחילה]\u0006 ואילו לענין \u0003נכריות\u0004 מדובר ב\u0003פקחות ואחר כך נתחרשו.\u0004","\u0003אלא איבעי לך לאותביה מהא\u0004 \u0005[היה לך להקשות לו מזו]\u0006 ששנינו: \u0003שני אחין חרשין נשואין שתי אחיות פקחות, או שתי אחיות חרשות, או שתי אחיות אחת פקחת ואחת חרשת. וכן שתי אחיות חרשות נשואות לשני אחין פקחין, או לשני אחין חרשין, או לשני אחין אחד פקח ואחד חרש — הרי אלו פטורות מן החליצה ומן הייבום. ואם היו נכריות\u0004 — \u0003יכנוסו, ואם רצו להוציא — יוציאו.\u0004","ונברר \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה \u0005הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003בפקחים ולבסוף נתחרשו,\u0004 אולם במקרה זה \u0003מי מצי מפקי\u0004 \u0005[האם יכולים\u0006 הם \u0005להוציא]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003נשתטית — לא יוציא, נתחרש הוא או נשתטה — לא יוציא עולמית!\u0004","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר על אלה שהיו \u0003חרשין מעיקרא\u0004 \u0005[מתחילה],\u0006 \u0003ומ\u0004אחר ש\u0003הן חרשין מעיקרא\u0004 \u0005[מתחילה] —\u0006 \u0003אינהו נמי\u0004 \u0005[הן גם כן]\u0006 \u0003חרשות מעיקרא\u0004 \u0005[מתחילה],\u0006 \u0003וקתני\u0004 \u0005[ושנה]\u0006 שם: \u0003אם היו נכריות — יכנוסו.\u0004 ונדייק: \u0003יכנוסו — אין\u0004 \u0005[כן],\u0006 \u0003יחלצו — לא,\u0004 משמע שאין חליצה לחרשת! ואם כן הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רבה.\u0004 ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריו.","שנינו במשנה: \u0003קטנה וחרשת\u0004 שהיו נשואות לאחד — אין ביאתה או חליצתה של אחת מהן פוטרת צרתה. \u0003אמר רב נחמן; אשכחתיה\u0004 \u0005[מצאתי אותו]\u0006 את \u0003רב אדא בר אהבה ו\u0004את \u0003רב חנא חתניה\u0004 \u0005[חתנו],\u0006 \u0003דיתבי וקמקוו אקוותא בשוקא\u0004 \u0005[שיושבים ומקשים קושיות\u0006 זה לזה \u0005בשוק]\u0006 של \u0003פומבדיתא, ואמרי\u0004 \u0005[ו\u0006היו \u0005אומרים]:\u0006 \u0003הא דתנן\u0004 \u0005[זו ששנינו]\u0006 במשנתנו כי \u0003קטנה וחרשת אין ביאת אחת מהן פוטרת\u0004 את \u0003צרתה — הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005] —\u0006 כש\u0003נפלה ליה\u0004 \u0005[לו]\u0006 \u0003מאחיו\u0004 ה\u0003פקח, דלא ידעינן\u0004 \u0005[שאין אנו יודעים]\u0006 בפיקח זה \u0003אי\u0004 \u0005[אם]\u0006 \u0003בקטנה ניחא ליה\u0004 \u0005[נוח לו]\u0006 יותר \u0003אי בחרשת ניחא ליה\u0004 \u0005[או בחרשת נוח לו]\u0006 יותר;","\u0003אי\u0004 \u0005[אם]\u0006 \u0003בקטנה ניחא ליה\u0004 \u0005[נוח לו]\u0006 \u0003דאתיא\u0004 \u0005[שתבוא]\u0006 \u0003לכלל דיעה\u0004 כשתגדל, \u0003אי\u0004 \u0005[או]\u0006 \u0003בחרשת ניחא\u0004 \u0005[נוח\u0006 לו\u0005]\u0006 כיון ש\u0003גדולה היא, ובת ביאה היא\u0004 עכשיו. ולכן לא ברור לנו במי מהן נתכוון לקנין שלם יותר, ומשום כך אין ייבום של אחת פוטר את צרתה. \u0003אבל\u0004 אם \u0003נפלה מאחיו\u0004 ה\u0003חרש — ודאי בחרשת ניחא ליה\u0004 \u0005[נוח לו],\u0006 כיון ש\u0003בת ביאה היא ובת מיניה\u0004 \u0005[מינו]\u0006 \u0003היא,\u0004 ומן הסתם התכוון לקנותה קנין שלם יותר.","\u0003ואמינא להו אנא\u0004 \u0005[ואמרתי להם אני]:\u0006 \u0003אפילו נפלה ליה\u0004 \u0005[לו]\u0006 \u0003מאחיו חרש נמי מספקא ליה\u0004 \u0005[גם כן מסופק לו]\u0006 לפי שעיקר הספק אינו תלוי במחשבתו של הבעל, אלא במהות הקנין בשתי אלה.","ושואלים: \u0003כיצד תקנתן\u0004 של קטנה וחרשת אלה? \u0003אמר רב חסדא אמר רב: כונס\u0004 את \u0003החרשת ומוציאה\u0004 אחר כך \u0003בגט,\u0004 ואינו יכול לקיימה, משום שחליצת הקטנה אחר כך תפסול אותה \u0003וקטנה תמתין עד שתגדיל, ותחלוץ.\u0004","\u0003אמר רב חסדא: שמע מינה\u0004 \u0005[למד מכאן],\u0006 מדבריו אלה של רב, כי \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003רב: חרשת\u0004 הריהי בנישואיה \u0003קנויה ומשויירת,\u0004 כלומר, קניינה הוא קנין בלתי גמור, \u0003קטנה — קנויה ואינה קנויה,\u0004 שהיא ספק קנויה קנין גמור, ספק אינה קנויה כלל. \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר להיפך כי \u0003חרשת קנויה ואינה קנויה, קטנה קנויה ומשויירת,\u0004 אם כן \u0003חרשת אמאי\u0004 \u0005[מדוע]\u0006 \u0003כונס ומוציאה בגט?\u0004"],["\u0003תיתיב גביה\u0004 \u0005[תשב אצלו]\u0006 \u0003ממה נפשך\u0004 \u0005(רצונך)\u0006 בכל אופן שתרצה לדון: \u0003אי\u0004 \u0005[אם]\u0006 \u0003קנויה היא\u0004 קנין גמור — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003קנויה היא,\u0004 גם לו, \u0003ואי לאו\u0004 \u0005[ואם לא]\u0006 \u0003קנויה היא,\u0004 שאין בה קנין כלל — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003נכרית\u0004 (זרה) \u0003בעלמא\u0004 \u0005[הרי זרה סתם]\u0006 \u0003היא.\u0004 שאם נישואיה לאח שמת לא היו נישואים — אין מקום לאסור אותה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 לפי שיקול זה, \u0003קטנה אמאי\u0004 \u0005[מדוע]\u0006 \u0003תמתין עד שתגדיל, ותחלוץ?\u0004 ישאנה ואז \u0003תיתיב גביה\u0004 \u0005[תשב אצלו],\u0006 ונאמר: \u0003אי\u0004 \u0005[אם]\u0006 \u0003קנויה היא — הא\u0004 \u0005[הרי]\u0006 \u0003קנויה היא, אי לאו\u0004 \u0005[\u0006ו\u0005אם לא]\u0006 \u0003קנויה היא\u0004 כלל — \u0003נוכריתא בעלמא\u0004 \u0005[זרה סתם]\u0006 \u0003היא!\u0004 אולם, \u0003אם כן, חרשת במה תיפוק\u0004 \u0005[תצא],\u0006 שהלא אינו יכול לפוטרה בחליצה, וגם לא בביאה, שמא הקטנה קנויה לו ופוסלת עליו את החרשת, ורב הרי רצה למצוא דרך לתקנת שתיהן.","\u0003אמר רב ששת: הכי נמי מיסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 \u0003כדקא מתרץ\u0004 \u0005[כפי שמיישב,\u0006 מסביר\u0005]\u0006 \u0003רב חסדא אליבא\u0004 \u0005[על פי שיטת]\u0006","\u0003רב, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שני אחין נשואין שתי אחיות יתומות\u0004 שהשיאון קרוביהן בנישואין מדברי סופרים, אחת \u0003קטנה ו\u0004אחת \u0003חרשת,\u0004 אם \u0003מת בעלה של קטנה\u0004 ונפלה לייבום לפני בעל החרשת — \u0003חרשת יוצאה בגט\u0004 משום זיקת אחותה הקטנה, \u0003וקטנה תמתין עד שתגדיל, ותחלוץ.\u0004","אם \u0003מת בעלה של חרשת — קטנה יוצאה בגט,\u0004 משום זיקת אחותה החרשת, \u0003וחרשת אסורה לעולם.\u0004 שהרי לכונסה אינו יכול, שמא היא נחשבת כאחות גרושתו, ולחלוץ לה אינו יכול, שהרי אינה בת חליצה. \u0003ואם\u0004 עבר ו\u0003בא על החרשת — נותן לה גט\u0004 אחר כך, \u0003והותרה.\u0004","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\u0003חרשת קנויה ומשויירת,\u0004 ואילו \u0003קטנה קנויה ואינה קנויה — משום הכי\u0004 \u0005[כך]\u0006 מובן \u0003דכי\u0004 \u0005[שכאשר]\u0006 \u0003בא על החרשת נותן לה גט והותרה, דאמרת\u0004 \u0005[שאומר אתה]\u0006 במקרה כזה \u0003ממה נפשך: אי\u0004 \u0005[אם]\u0006 \u0003קטנה קנויה היא\u0004 קנין גמור — \u0003הא נפקא\u0004 \u0005[הרי יוצאת]\u0006 החרשת \u0003משום אחות אשה, אי לאו\u0004 \u0005[אם\u0006 הקטנה \u0005לא]\u0006 \u0003קנויה\u0004 כלל, אם כן \u0003שפיר\u0004 \u0005[יפה,\u0006 כהוגן\u0005]\u0006 \u0003מיבם.\u0004","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003חרשת קנויה ואינה קנויה,\u0004 ואילו \u0003קטנה קנויה ומשויירת,\u0004 אם כן, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003בא על חרשת, אמאי\u0004 \u0005[מדוע]\u0006 \u0003נותן\u0004 לה \u0003גט והותרה?\u0004 הרי \u0003הויא ליה\u0004 \u0005[נהייתה זאת]\u0006 \u0003ביאה פסולה,\u0004 שהרי אחותה הקטנה קנויה במקצת, ודוחה את החרשת מייבום, ואם בא עליה בכל זאת — הרי זו ביאה פסולה, \u0003וביאה פסולה לא פטרה\u0004 \u0005[אינה פוטרת אותה],\u0006 ועדיין זקוקה היא לחליצה, וזו החרשת אינה חולצת.","ודוחים: מכאן אין ראיה, אפשר לומר כי \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא] —\u0006 כשיטת \u0003ר' נחמיה היא,\u0004 ש\u0003אמר: ביאה פסולה,\u0004 גם היא \u0003פוטרת מחליצה.\u0004","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 כדעת \u0003ר' נחמיה, אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של ברייתא זו: \u0003מי שהיה נשוי שתי יתומות, קטנה וחרשת, ומת. בא יבם על הקטנה, וחזר ובא על החרשת. או שבא אחיו על החרשת — נאסרו שתיהן עליו. כיצד תקנתן? חרשת יוצאת בגט, וקטנה תמתין עד שתגדיל, ו\u0004אז \u0003תחלוץ.\u0004","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שטעם הדבר הוא כי \u0003חרשת קנויה ומשויירת,\u0004 שלא היה קניינה שלם מתחילה, ואילו \u0003קטנה\u0004 ספק \u0003קנויה, ו\u0004ספק \u0003אינה קנויה, ו\u0004כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא\u0004 בענין ביאה פסולה — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003תמתין\u0004 קטנה \u0003עד שתגדיל, ותחלוץ,\u0004 ולא תישאר אצלו ממה נפשך, שאפילו אינה קנויה תיחשב כזרה, ומדוע — \u0003דדלמא קדים ובעיל\u0004 \u0005[שמא יקדים ויבעל]\u0006 את ה\u0003חרשת ברישא\u0004 \u0005[בתחילה],\u0006 \u0003והויא ליה\u0004 \u0005[ונהייתה]\u0006 \u0003ביאה\u0004 של ה\u0003קטנה ביאה פסולה,\u0004 שהואיל וכבר בעל את צרתה, אף שביאה זו אינה מועילה כדי לקנותה קנין גמור, בכל זאת היא פוסלת את קניינה של הצרה.","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהיא כדעת \u0003ר' נחמיה, הא\u0004 \u0005[הרי]\u0006 \u0003אמר ביאה פסולה פטרה!\u0004","\u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי ברייתא זו כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003אמר רב אשי: מרישא נמי\u0004 \u0005[מתחילתה\u0006 של הברייתא \u0005גם כן]\u0006 \u0003שמע מינה דרבנן\u0004 \u0005[\u0006אפשר \u0005ללמוד ממנה ש\u0006דעת \u0005חכמים]\u0006 \u0003היא, דקתני\u0004 \u0005[ששנה\u0006 שם\u0005]:\u0006 \u0003אם בא על החרשת — נותן לה גט, והותרה, ולא קתני\u0004 \u0005[שנה]\u0006 \u0003אם בא על הקטנה נותן לה גט והותרה,\u0004 ובוודאי משום שקנין החרשת (אף שאינו מושלם) דוחה את הקטנה וביאתה נחשבת לביאה פסולה וזקוקה גם לחליצה.","את ההוכחה הזו דוחים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום הא\u0004 \u0005[זה]\u0006 — \u0003לא איריא\u0004 \u0005[שייך],\u0006 אין זו ראיה, שכן ניתן לומר כי \u0003חרשת דלית\u0004 \u0005[שאין]\u0006 \u0003לה תקנתא דהיתירא\u0004 \u0005[תקנה של היתר],\u0006 מכיון שאין דרך של היתר לפטור אותה בחליצה — \u0003קתני תקנתא דאיסורא\u0004 \u0005[שנה\u0006 בה \u0005תקנה של איסור],\u0006 שאם בכל זאת בא עליה, אזי יש לה תקנה בגט, ואילו \u0003קטנה דאית\u0004 \u0005[שיש]\u0006 \u0003לה תקנתא דהיתירא\u0004 \u0005[תקנה של היתר],\u0006 שתגדל ותחלוץ — \u0003לא תני תקנתא דאיסורא\u0004 \u0005[שנה\u0006 בה \u0005תקנה של איסור],\u0006 ושמא אילו בא עליה, היה יכול להתירה בגט בלבד.","\u0003מי שהיה נשוי לשתי יתומות קטנות,\u0004 שהשיאון קרוביהן בנישואין שמדברי סופרים, \u0003ומת, ובא יבם על הראשונה\u0004 (אחת מהן) \u0003וחזר ובא על השניה, או שבא אחיו,\u0004 שגם הוא יבם, \u0003על השניה —\u0004"],["\u0003לא פסל את הראשונה\u0004 בביאתה של השניה, \u0003וכן\u0004 אם היו \u0003שתי חרשות\u0004 — אין ביאת השניה על ידי היבם פוסלת את הראשונה, כיון שביאת שתיהן שווה. ולכן: אם היתה הראשונה קנויה לבעלה — קנויה היא גם ליבם, ואם לאו, שאינה אשת אחיו — הרי נעשתה כאשתו, ואין ביאת השניה פוסלתה, ואף שאסור היה לו מהספק לבוא עליה.","אם היו \u0003קטנה וחרשת; בא יבם על הקטנה, וחזר ובא על החרשת, או שבא אחיו על החרשת\u0004 — הרי זה \u0003פסל את הקטנה,\u0004 כפי שהסברנו, גזירה משום זה שבא תחילה על החרשת.","\u0003בא יבם על החרשת, וחזר ובא על הקטנה, או שבא אחיו על הקטנה — פסל את החרשת,\u0004 שכן נישואיהם אינם נישואין גמורים. וביאת היבם איננה נחשבת לביאה הקונה ופוטרת, ולכן הביאה השניה פוסלת את הראשונה.","היתה אחת \u0003פקחת ו\u0004אחת \u0003חרשת\u0004 ו\u0003בא יבם על הפקחת, וחזר ובא על החרשת, או שבא אחיו על החרשת — לא פסל את הפקחת,\u0004 הואיל וקניינה לבעלה הוא קניין גמור, וביאת היבם עליה קנתה אותה לו קניין גמור ונפטרה צרתה, וביאתו על החרשת היתה בעילת זנות.","\u0003בא יבם על החרשת וחזר ובא על הפקחת, או שבא אחיו על הפקחת\u0004 — הרי זה \u0003פסל את החרשת,\u0004 הואיל ואין קניינה קניין שלם, וביאת צרתה הפיקחת דוחה אותה ופוסלתה.","היו לאח המת שתי נשים, אחת \u0003גדולה ו\u0004אחת \u0003קטנה,\u0004 שנישואיה מדברי סופרים בלבד, ו\u0003בא יבם על הגדולה, וחזר ובא\u0004 אחר כך \u0003על הקטנה, או שבא אחיו על הקטנה — לא פסל את הגדולה,\u0004 שהרי ביאת הגדולה בנישואיה ביאה גמורה היתה ופטרה את צרתה. אם \u0003בא יבם על הקטנה וחזר ובא על הגדולה. או שבא אחיו על הגדולה — פסל את הקטנה. ר' אלעזר אומר: מלמדין הקטנה שתמאן בו\u0004 ותעקור נישואיה מעיקרם, ותהא אף הקטנה מותרת לכל אדם.","\u0003אמר רב יהודה אמר שמואל: הלכה כר' אלעזר,\u0004 שמלמדים את הקטנה שתמאן בו. \u0003וכן אמר\u0004 האמורא \u0003ר' אלעזר\u0004 בן פדת: \u0003הלכה כר' אלעזר\u0004 בן שמוע, התנא במשנתנו.","ואומרת הגמרא: \u0003וצריכא\u0004 \u0005[והוצרכה]\u0006 הלכה זו להיאמר גם במקרה זה וגם במקרה הראשון — בשתי אחיות נשואות ואחת מהן קטנה ונפלה הגדולה לייבום לפני בעל הקטנה. \u0003דאי איתמר בהא קמייתא\u0004 \u0005[שאילו\u0006 היה \u0005נאמר\u0006 פסק הלכה זה רק \u0005ב\u0006מקרה \u0005זה\u0006 ה\u0005ראשון],\u0006 הייתי אומר: \u0003בהך קאמר\u0004 \u0005[בזו אומר]\u0006 \u0003שמואל הלכה כר' אליעזר — משום\u0004 ש\u0003לא קיים מצות ייבום\u0004 בגדולה, וכדי שיוכל לקיים בה מצות ייבום, מלמדים את הקטנה למאן בו, \u0003אבל בהא\u0004 \u0005[בזו]\u0006 \u0003דאיקיים\u0004 \u0005[שהתקיימה]\u0006 \u0003מצות ייבום\u0004 בגדולה — \u0003אימא תרוייהו לפקו\u0004 \u0005[אמור\u0006 ש\u0005שתיהן תצאנה]\u0006 \u0003בגט.\u0004","\u0003ו\u0004להיפך, \u0003אי אשמעינן בהא\u0004 \u0005[אילו היה משמיע לנו\u0006 רק \u0005בזו],\u0006 הייתי אומר: \u0003משום\u0004 שה\u0003גדולה\u0004 מכל מקום \u0003רמיא קמיה\u0004 \u0005[מוטלת לפניו]\u0006 לייבום, ומשום כך הייתי אומר מוטב שיידחו נישואיה של הקטנה על ידי מיאון. \u0003אבל אידך\u0004 \u0005[האחרת]—\u0006 \u0003לא,\u0004 שכל זמן שלא מיאנה הרי היא אחות אשתו, ואין בה חובת ייבום כלל. על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמר פסק הלכה זה בשני המקרים.","\u0003יבם קטן, שבא על יבמה\u0004 שגם היא \u0003קטנה — יגדלו זה עם זה\u0004 יחד, כזוג נשוי. ואינו יכול לגרשה, שהרי קטן הוא. אם \u0003בא על יבמה גדולה — תגדלנו,\u0004 תמתין לו עד שיגדל, ואינו יכול לפוטרה קודם לכן.","\u0003היבמה ש\u0004כנסה היבם לשם ייבום, ו\u0003אמרה בתוך שלשים יום\u0004 לכניסתה \u0003\"לא נבעלתי\" — כופין אותו שיחלוץ לה.\u0004 ואם אמרה זאת \u0003לאחר שלשים יום,\u0004 והוא אומר שבא עליה — \u0003מבקשין הימנו שיחלוץ לה,\u0004 לפי שיש מקום להאמין לו שבא עליה. \u0003ובזמן שהוא מודה\u0004 שלא בא עליה — \u0003אפילו לאחר שנים עשר חדש כופין אותו שיחלוץ לה\u0004.","אשה \u0003הנודרת הנאה מיבמה,\u0004 שנדרה עוד \u0003בחיי בעלה\u0004 שלא תיהנה ממנו כל הנאה — \u0003כופין אותו שיחלוץ לה,\u0004 שהרי אסור לה להיבעל לו, וממילא אין לה תקנה אלא בחליצה. אם נדרה ממנו הנאה \u0003לאחר מיתת בעלה —\u0004 רק \u0003מבקשין הימנו שיחלוץ לה. ואם נתכוונה לכך,\u0004 שרצתה לפטור עצמה לעתיד, לאחר מות בעלה, מחובת הייבום — \u0003אפילו\u0004 נדרה \u0003בחיי בעלה,\u0004 רק \u0003מבקשין הימנו שיחלוץ לה.\u0004","ומציעים: \u0003לימא מתניתין\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005משנתנו]\u0006 ש\u0003לא כ\u0004דעת \u0003ר' מאיר. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003קטן וקטנה — לא חולצין ולא מתייבמין,\u0004 אלו \u0003דברי ר' מאיר.\u0004 וטעמו: שמא יימצא הקטן סריס, או הקטנה תימצא איילונית, ואז אין מצוות ייבום חלה עליהם, אבל יש בכך איסור ערות אשת אח. ואילו כאן נראה, שמניחים לקטן ולקטנה לחיות זה עם זו!","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כשיטת \u0003ר' מאיר\u0004 היא, שכן \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' מאיר\u0004 את דינו לאיסור, הרי זה במקרה של \u0003גדולה לקטן, וקטנה לגדול, דחד מינייהו\u0004 \u0005[ש\u0006לגבי \u0005אחד מהם]\u0006 \u0003ביאה דאיסורא\u0004 \u0005[של איסור]\u0006 \u0003הוא,\u0004 שהרי יש כאן ספק איסור ערוה, ואם כי הקטן אינו חייב, מכל מקום השותף המבוגר חייב על איסור ביאת ערוה גם עם שותף קטן. \u0003אבל קטן הבא על הקטנה דתרוייהו כי הדדי נינהו\u0004 \u0005[ששניהם זה כמו זה הם],\u0006 ושניהם עדיין אינם חייבים במצוות, בזה \u0003לא אמר.\u0004","ומקשים: \u0003והא קתני\u0004 \u0005[והרי שנה]\u0006 במשנתנו: \u0003בא\u0004 הקטן \u0003על יבמה גדולה — תגדלנו,\u0004 ומשמע גם במקרה שאחד מהם גדול! \u0003אמר ר' חנינא חוזאה: בא — שאני\u0004 \u0005[שונה],\u0006 שאם כבר בא עליה, אף שלכתחילה אינו מייבם — מוטב שתגדלנו. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003תגדלנו קאמר\u0004 \u0005[אמר],\u0006 משמע שיחיו יחד כל הזמן חיי נישואין אף ש\u0003כל ביאה וביאה דאיסורא\u0004 \u0005[של\u0006 חשש \u0005איסור]\u0006 \u0003הוא\u0004 לדעת ר' מאיר! \u0003אלא מחוורתא\u0004 \u0005[מחוור,\u0006 ברור\u0005]\u0006 כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' מאיר\u0004 היא.","לעצם הענין שואלים, ובאמת מדוע יוכל הקטן לייבם? \u0003קרי\u0004 \u0005[קרא]\u0006 \u0003כאן\u0004 עליו את הכתוב \u0003\"להקים לאחיו שם\"\u0004 (דברים כה, ז), \u0003והאי לאו בר הכי הוא\u0004 \u0005[וזה\u0006 הקטן \u0005אינו\u0006 מסוגל ל\u0005כך],\u0006 שהרי אינו יכול להוליד! \u0003אמר אביי, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"יבמה יבא עליה\"\u0004 (שם ה) — לרבות \u0003כל דהו\u0004 \u0005[שהוא],\u0006 אפילו זה שאינו מוליד.","\u0003רבא אמר: בלאו הכי נמי לא מצית אמרת\u0004 \u0005[גם בלא\u0006 נימוק \u0005זה אינך יכול לומר]\u0006 שיש חשש איסור בדבר זה, שכן \u0003מי איכא מידי דהשתא אסירא ליה ולבתר שעתא שריא\u0004 \u0005[האם יש דבר,\u0006 מקרה בייבום, \u0005שעכשיו\u0006 היא \u0005אסורה לו ולאחר זמן\u0006 תהיה \u0005מותרת]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב יהודה אמר רב: כל יבמה שאין אני קורא בשעת נפילה\u0004 לייבום \u0003\"יבמה יבא עליה\"\u0004 (שם), וכגון שיש סיבה הלכתית שאסור לו לייבם — \u0003הרי היא\u0004 נעשית לאחיו \u0003כאשת אח שיש לו בנים, ואסורה\u0004 לעולם.","ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור כך גם כן],\u0006 שתהיה אסורה לעולם אם נפלה לפני יבם קטן! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כי ישבו אחים יחדו\"\u0004 (שם ה), משמע שדין זה חל בכל האחים החיים יחדיו באותו זמן, \u0003אפילו\u0004 היה האח \u0003בן יום אחד.\u0004","שנינו במשנה ש\u0003יבמה שאמרה בתוך שלשים יום\u0004 \"לא נבעלתי\" — כופים אותו שיחלוץ, ואם אמרה לאחר שלושים — מבקשים הימנו שיחלוץ. ושואלים: \u0003מאן\u0004 \u0005[מי\u0006 הוא\u0005]\u0006 ה\u0003תנא\u0004 הסבור ש\u0003עד תלתין יומין\u0004 \u0005[שלושים יום]\u0006 \u0003מוקים איניש אנפשיה\u0004 \u0005[מעמיד אדם את עצמו\u0006 ומתאפק\u0005]\u0006 ואינו בא על אשה שהוא חי איתה?","\u0003אמר ר' יוחנן:\u0004 דעת \u0003ר' מאיר היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003טענת בתולים,\u0004 שיכול אדם לבוא לבית דין ולטעון שכנס אשה בחזקת שהיא בתולה, ובעלה, ומצא שאיננה בתולה — \u0003כל שלשים יום\u0004 מן החופה, במשך כל תקופה זו, יכול לטעון זאת, כיון שעד אז יכול להיות שלא בעל והוא בא וטען טענה זו מיד לאחר בעילה ראשונה, אלו \u0003דברי ר' מאיר.\u0004","\u0003ר' יוסי אומר:\u0004 אם \u0003נסתרה,\u0004 כלומר, אם היו במקום צנוע הראוי לביאה — יכול לטעון טענת בתולים רק \u0003לאלתר\u0004 (מיד), אבל אם \u0003לא נסתרה\u0004 ולא היו יחד — יכול לטעון כן \u0003אף לאחר כמה שנים.\u0004 משמע, שר' מאיר הוא הסבור כי עד שלושים יום אפשר לומר שאדם לא בא על אשתו.","\u0003רבה אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כדעת \u0003ר' יוסי.\u0004 אלא, \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יוסי התם\u0004 \u0005[שם]\u0006 \u0003אלא בארוסתו דגיס\u0004 \u0005[שגס\u0006 לבו, רגיל\u0005]\u0006 \u0003בה,\u0004 ולכן אם יתייחד עימה בודאי יבוא עליה. \u0003אבל אשת אחיו,\u0004 היבמה שהיתה אשת אחיו —"],["\u0003מיבזז בזיז מינה\u0004 \u0005[מתבייש ממנה],\u0006 ולכן ייתכן שעבר זמן מסויים עד שבא עליה.","ושואלים לגופה של ההלכה: \u0003עד שכופין אותו לחלוץ — ניכפנו לייבם! אמר רב:\u0004 מדובר שם \u0003בשגיטה יוצא מתחת ידה,\u0004 כלומר, שהיבם כבר נתן לה גט, ומאחר שנתן לה גט שוב אינו יכול לייבמה, אלא שהיא טוענת שלא נבעלה, ואין הגט מועיל להתירה לכל, ולכן היא צריכה גם חליצה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003יבמה שאמרה בתוך שלשים יום \"לא נבעלתי\"\u0004 — \u0003בין שהוא אומר \"בעלתי\", בין שהוא אומר \"לא בעלתי\", כופין אותו שיחלוץ לה. לאחר שלשים יום — מבקשין הימנו\u0004 (ממנו) \u0003שיחלוץ לה.\u0004","אם \u0003היא אומרת\u0004 לאחר שלושים יום \u0003\"נבעלתי\" והוא אומר \"לא בעלתי\" — הרי זה יוציא בגט.\u0004 שחזקה שבא עליה. אם \u0003הוא אומר \"בעלתי\", והיא אומרת \"לא נבעלתי\"\u0004 — \u0003אף על פי שחזר\u0004 בו \u0003ואמר: \"לא בעלתי\", צריך גט וחליצה.\u0004 ומתוך ששנה כאן \"צריך גט\", משמע שבכל הענין מדובר כשלא היה לה גט!","\u0003אמר ר' אמי:\u0004 הכוונה היא ש\u0003צריכה חליצה עם גיטה,\u0004 כלומר, צריכה חליצה בנוסף לגט שכבר קיבלה. \u0003רב אשי אמר: התם\u0004 \u0005[שם],\u0006 כשקבע שהמקרה הוא בגט היוצא מתחת ידה, מדובר ב\u0003גט\u0004 שנתנו לה \u0003לזיקתו,\u0004 שנתנו לה קודם שכנסה — כדי לבטל את זיקת הייבום, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר ב\u0003גט\u0004 שנותן \u0003לביאתו,\u0004 שלאחר שבא עליה הריהי כאשתו ומותרת לכול על ידי גט זה.","מסופר: מעשה ב\u0003הנהו\u0004 \u0005[אותם]\u0006 יבם ויבמה, שהיו \u0003שניהם מודים\u0004 שלא בא עליה, \u0003דאתו לקמיה\u0004 \u0005[שבאו לפני]\u0006 \u0003רבא, אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא\u0004 לחכמים שלפניו: \u0003חלוצו לה\u0004 (עשו לה חליצה) \u0003ושרו לה תיגרא\u0004 \u0005[ופתרו את עניינה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שרביא לרבא: והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003צריכה גט וחליצה! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי תניא\u0004 \u0005[אם שנויה]\u0006 — \u0003תניא\u0004 \u0005[שנויה],\u0006 וחוזרני בי מפני הברייתא.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003הון, בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן, מדרב נחמן\u0004 אביו: \u0003צרתה מהו?\u0004 אם כנס היבם את אשת אחיו נפטרה בזה הצרה, ואם לאחר זמן אמרה היבמה שלא בעל אותה, האם יש צורך באיזה מעשה כדי לפטור את הצרה מזיקת הייבום?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וכי מפני שאנו כופין\u0004 או לפעמים \u0003מבקשים\u0004 את הבעל לחלוץ כדי לצאת מידי ספק ולהתיר את האשה, \u0003תיאסר\u0004 ה\u0003צרה?\u0004 כי בעצם אנו מניחים שנבעלה, אבל כיון שאומרת שלא נבעלה, נמצא שהיא אוסרת עצמה לאחרים (כי לפי דבריה עדיין זיקת ייבום עליה) — ולכן אומרים שיחלוץ לה, אבל אין סומכים על דבריה עד כדי שנבוא לאסור את הצרה.","שנינו במשנה ש\u0003הנודרת הנאה\u0004 מן היבם לפני מות בעלה — מחייבים אותו לחלוץ לה. \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה במסכת נדרים, \u0003בראשונה היו אומרים: שלש נשים יוצאות\u0004 מבעליהן בעל כורחם, \u0003ו\u0004בכל זאת \u0003נוטלות כתובה.\u0004","והן: \u0003האומרת \"טמאה אני לך\",\u0004 כאשר אשת כהן אומרת לבעלה שנאנסה — הוא חייב לגרשה, שכן הוא אסור בה, וכיון שהיא אנוסה — זכאית היא ליטול כתובתה. וכן האומרת \u0003\"השמים ביני לבינך\",\u0004 כלומר, אין עדים בדבר, אלא השמים יעידו שאין אתה יכול לבוא עלי כראוי, וכיון שאין זו אשמתה — נוטלת כתובתה. וכן אם נדרה נדר \u0003\"נטולה אני מן היהודים\",\u0004 כלומר, שלא תיהנה בתשמיש מכל אדם בישראל, משום שהדבר קשה לה.","\u0003חזרו\u0004 אחר כך \u0003לומר,\u0004 כדי \u0003שלא תהא אשה נותנת עיניה באחר,\u0004 שרוצה להינשא לו, \u0003ומקלקלת על בעלה\u0004 — ומכריחה אותו לגרשה ולשלם לה את כתובתה על סמך טענת שקר. \u0003אלא\u0004 כך אמרו: \u0003האומרת \"טמאה אני לך\"\u0004 — אין די בטענה בלבד, אלא \u0003תביא ראיה לדבריה.\u0004 שאכן נאנסה. אם אמרה \u0003\"השמים ביני לבינך\" — יעשו דרך בקשה,\u0004 כלומר, ינסו לפייס ביניהם ולתקן את הדבר.","אם אמרה \u0003\"נטולה אני מן היהודים\" — יפר חלקו,\u0004 כלומר, יפר את הנדר במידה שהדבר נוגע לו, שהרי זהו נדר בדברים שבינו לבינה, ורשאי הבעל להפר אותו \u0003ומשמשתו, ותהא נטולה\u0004 אסורה בתשמיש) \u0003מן\u0004 כל שאר \u0003היהודים.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם],\u0006 ללומדים, שאלה זו: לפי המשנה האחרונה, אם אמרה \u0003\"נטולה אני מן היהודים\"\u0004 והפר לה הבעל את חלקו, \u0003ל\u0004ענין ה\u0003יבם מהו\u0004 הדין? האם חל נדר זה לגביו או לא? וצדדי השאלה: \u0003מי מסקה אדעתה דמיית\u0004 \u0005[האם מעלה\u0006 היא \u0005על דעתה שימות]\u0006 \u0003בעלה ונפלה קמי\u0004 \u0005[ותיפול לפני]\u0006 ה\u0003יבם,\u0004 וכדי לצאת ממנו היא נדרה, \u0003או\u0004 ש\u0003לא\u0004 העלתה על דעתה שתיפול לפניו ולא נתכוונה לידור ממנו, שהרי בזמן שנדרה היא אסורה עליו.","\u0003רב אמר: יבם אינו כבעל,\u0004 שלא נדרה ממנו כלל ויכול הוא לייבם אותה, \u0003ושמואל אמר: יבם הרי הוא כבעל\u0004 לענין זה, שהנדר חל גם עליו ומחייבים אותו לחלוץ. \u0003אמר אביי: כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רב מסתברא\u0004 \u0005[מסתבר]\u0006 לומר, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנודרת הנאה מיבמה בחיי בעלה — כופין אותו שיחלוץ. ואם איתא דמסקה אדעתה\u0004 \u0005[ואם יש\u0006 מקום לומר שחוששים \u0005ש\u0006היא \u0005מעלה על דעתה]\u0006 להיפטר ממנו —"],["\u0003מבקשין מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו\u0006 לומר\u0005]\u0006 ולא כופים, שהרי נתכוונה להפקיע את עצמה ממצות ייבום. ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003באשה שיש לה בנים\u0004 מבעלה בשעה שנדרה, \u0003דכולי האי לא מסקה אדעתה\u0004 \u0005[שכל זה אינה מעלה על דעתה]\u0006 שימותו הבנים ואחר כך ימות בעלה ותפול לפני היבם.","ושואלים: \u0003אבל\u0004 אם \u0003אין לה בנים, מאי\u0004 \u0005[מה]\u0006 יהיה הדין — ש\u0003מבקשין\u0004 ולא כופים? אם כן, \u0003אדתני\u0004 \u0005[עד ש\u0006הוא \u0005שונה]\u0006 דין שונה ורחוק יותר \u0003אם נתכוונה לכך אפילו בחיי בעלה מבקשין ממנו שיחלוץ לה, ליפלוג וליתני בדידה\u0004 \u0005[שיחלק וישנה בה עצמה]\u0006 חלוקה זו: \u0003במה דברים אמורים — בשיש לה בנים, אבל אין לה בנים — מבקשין!\u0004","\u0003אלא שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם \u0003יש לה בנים, ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם \u0003אין לה בנים — כופין אותו, כ\u0004דעת \u0003רב,\u0004 שאין אומרים שהאשה התכוונה לכך אלא אם כן אמרה זאת במפורש, ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 סיוע לשיטת רב.","","\u0003חרש שנשא פקחת ופקח שנשא חרשת, אם רצה\u0004 כל אחד מהם \u0003להוציא\u0004 (לגרש את אשתו) — \u0003יוציא\u0004 בגט, \u0003ואם רצה לקיים\u0004 אותה כאשתו — \u0003יקיים.\u0004 מפני שהחרש, \u0003כשם שהוא כונס ברמיזה\u0004 — שנישואיו אינם על ידי דיבור מפורש, אלא נסמכים על רמז — \u0003כך הוא מוציא ברמיזה.\u0004","וכן \u0003פקח שנשא פקחת ונתחרשה, אם רצה — יוציא, ואם רצה — יקיים,\u0004 לפי שאין צורך בדעתה בגירושין. אם \u0003נשתטית\u0004 (השתגעה) — \u0003לא יוציא,\u0004 שאין הגט מועיל בה. \u0003נתחרש הוא או נשתטה\u0004 אחרי הנישואין ולא החלים — \u0003אינו מוציאה עולמית,\u0004 שהרי אין בו דעת לתת גט. \u0003אמר ר' יוחנן בן נורי: מפני מה\u0004 אתם אומרים ש\u0003האשה שנתחרשה יוצאה, והאיש שנתחרש אינו מוציא?\u0004 שכן אם אין תוקף לגיטו של מי שהיה פיקח ונתחרש — מן הדין שלא יהא לו תוקף גם כשנתחרשה היא! \u0003אמרו לו: אינו דומה האיש המגרש לאשה המתגרשת,\u0004 ומדוע? — \u0003שהאשה יוצאה\u0004 בין \u0003לרצונה ו\u0004בין \u0003שלא לרצונה,\u0004 וכיון שלענין זה איננו זקוקים לרצון האשה, הרי גם אם אין בה דעת יכול לגרשה, \u0003ו\u0004אילו \u0003האיש אינו מוציא אלא לרצונו,\u0004 ומי שנתחרש, שאין בו דעת — אין רצונו נחשב. \u0003העיד ר' יוחנן בן גודגדא על החרשת שהשיאה אביה\u0004 כשהיא קטנה, שנישואיה היו מתחילתם נישואין גמורים (שכן האב משיא את בתו מדין תורה) — \u0003שהיא יוצאה בגט,\u0004 גם כשגדלה ושוב אינה ברשות אביה ואף שאין בה דעת. \u0003אמרו לו: אף זו כיוצא בה,\u0004 כלומר, גם פיקחת שנתחרשה, דינה כקטנה שאין בה דעת ויוצאת בגט. \u0003שני אחין חרשין נשואין לשתי אחיות חרשות, או לשתי אחיות פקחות, או לשתי אחיות אחת חרשת ואחת פקחת, או שתי אחיות חרשות נשואין\u0004 (נשואות) \u0003לשני אחין פקחין, או לשני אחין חרשין, או לשני אחין אחד חרש ואחד פקח — הרי אלו פטורין מן החליצה ומן הייבום,\u0004 משום שכל אחת מהן היא ערוה ליבם, כיון שנישואיהן של האחיות היו שווים ובאים נישואי אשתו ומפקיעים את זיקת אחותה. \u0003ואם היו נכריות\u0004 (זרות זו לזו) — \u0003יכנוסו\u0004 (יתייבמו); \u0003ואם רצו\u0004 אחר כך \u0003להוציא — יוציאו.\u0004","","","","ואולם, אם היו \u0003שני אחין, אחד חרש ואחד פקח, נשואין לשתי אחיות פקחות,\u0004 אם \u0003מת\u0004 ה\u0003חרש בעל הפקחת, מה יעשה פקח בעל הפקחת?\u0004 — \u0003תצא\u0004 אשת אחיו בלא ייבום וחליצה, \u0003משום אחות אשה.\u0004","\u0003מת פקח בעל הפקחת, מה יעשה חרש בעל הפקחת? — מוציא\u0004 את \u0003אשתו בגט,\u0004 שהרי אחות אשתו נפלה לפניו לייבום, ותוקף נישואיה וייבומה גדול יותר מאשר נישואיו שלו, שאינם אלא מדברי סופרים, \u0003ו\u0004אילו \u0003אשת אחיו אסורה לעולם,\u0004 שהרי אינו יכול לכונסה משום שהיא אחות גרושתו מדברי סופרים, ואף אינו יכול לפוטרה בחליצה הואיל וחרש הוא.","היו \u0003שני אחין פקחין נשואין לשתי אחיות, אחת\u0004 מהן \u0003חרשת ואחת פקחת,\u0004 אם \u0003מת פקח בעל חרשת, מה יעשה פקח בעל פקחת? — תצא\u0004 החרשת \u0003משום אחות אשה.\u0004 ואם \u0003מת פקח בעל פקחת, מה יעשה פקח בעל החרשת?\u0004 — \u0003מוציא את אשתו בגט,\u0004 משום שהפיקחת נפלה לפניו בזיקת ייבום, ותוקף זיקתה גדול יותר מאשר נישואיו עם אשתו החרשת, \u0003ואת אשת אחיו\u0004 הפיקחת יוציא \u0003בחליצה,\u0004 שהרי בן דעת הוא ויכול לחלוץ לה.","היו \u0003שני אחין, אחד חרש ואחד פקח, נשואין לשתי אחיות, אחת חרשת ואחת פקחת,\u0004 אם \u0003מת חרש בעל חרשת, מה יעשה פקח בעל פקחת? תצא\u0004 החרשת \u0003משום אחות אשה.\u0004","\u0003מת פקח בעל פקחת, מה יעשה חרש בעל חרשת? — מוציא את אשתו בגט\u0004 — כשם שכנסה כך מוציאה, \u0003ואשת אחיו אסורה לעולם,\u0004 שאין לה תקנה כי היא אסורה בייבום משום אחות גרושתו מדברי סופרים, ואינו יכול לחלוץ לה, שהרי חרש הוא.","היו \u0003שני אחין, אחד חרש ואחד פקח, נשואין לשתי נכריות פקחות\u0004 אם \u0003מת חרש בעל פקחת, מה יעשה פקח בעל פקחת? — או חולץ או מייבם.\u0004 ואם \u0003מת פקח בעל פקחת, מה יעשה חרש בעל פקחת?\u0004 — לחלוץ אינו יכול מפני שהוא חרש, אלא \u0003כונס\u0004 את היבמה, \u0003ואינו מוציא לעולם,\u0004 שהרי זיקתה וביאתה יוצרים נישואין תקפים שאינם ניתנים להתרה על ידי גט של חרש.","היו \u0003שני אחין פקחין נשואין לשתי נכריות, אחת פקחת ואחת חרשת,\u0004 אם \u0003מת פקח בעל חרשת, מה יעשה פקח בעל פקחת?\u0004 אינה יכולה לחלוץ, שאין חרשת חולצת, אלא \u0003כונס\u0004 את החרשת. \u0003ואם רצה להוציא — יוציא\u0004 אחר כך בגט. \u0003מת פקח בעל פקחת, מה יעשה פקח בעל חרשת? — או חולץ או מייבם.\u0004","היו \u0003שני אחין, אחד חרש ואחד פקח, נשואים לשתי נכריות, אחת חרשת ואחת פקחת,\u0004 אם \u0003מת חרש בעל חרשת, מה יעשה פקח בעל פקחת? — כונס,\u0004 אם רוצה, את החרשת, \u0003ואם רצה\u0004 אחר כך \u0003להוציא — יוציא. מת פקח בעל פקחת, מה יעשה חרש בעל חרשת? — כונס\u0004 את יבמתו \u0003ואינו מוציא לעולם,\u0004 שהרי אינו יכול לגרשה.","\u0003אמר רמי בר חמא: מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003חרש וחרשת דתקינו להו רבנן\u0004 \u0005[שתיקנו להם חכמים]\u0006 על כל פנים \u0003נשואין\u0004 מדבריהם, שהרי שנינו במשנה שצריכות לחלוץ, \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003שוטה ושוטה\u0004 ש\u0003לא תקינו להו רבנן\u0004 \u0005[תיקנו להם חכמים]\u0006 \u0003נשואין\u0004 כלל, אפילו מדבריהם? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שוטה וקטן שנשאו נשים ומתו — נשותיהן פטורות מן החליצה ומן היבום,\u0004 שאין נישואי שוטה וקטן כלום!","והוא מסביר: בנישואי \u0003חרש וחרשת, דקיימא תקנתא דרבנן\u0004 \u0005[שמתקיימת תקנת חכמים],\u0006 שנישואין אלה יכולים להתקיים, ולכן \u0003תקינו להו רבנן\u0004 \u0005[תיקנו להם חכמים]\u0006 \u0003נשואין,\u0004 ואילו נישואי \u0003שוטה ושוטה דלא קיימא תקנתא דרבנן\u0004 \u0005[שאין מתקיימת תקנת חכמים]\u0006 בענין זה, לפי שאין אדם יכול לחיות עם בן זוג שוטה, כפי שאומר הפתגם: \u0003אין אדם דר עם נחש בכפיפה\u0004 (בסל) \u0003אחת,\u0004 ולכן \u0003לא תקינו רבנן\u0004 \u0005[תיקנו\u0006 להם \u0005חכמים]\u0006 \u0003נשואין.\u0004","ושואלים: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003קטן\u0004 ש\u0003לא תקינו רבנן\u0004 \u0005[תיקנו\u0006 לו \u0005חכמים]\u0006 \u0003נשואין, וחרש\u0004 ש\u0003תקינו ליה רבנן\u0004 \u0005[\u0006ש\u0005תיקנו לו חכמים]\u0006 \u0003נשואין?\u0004 ומסבירים: \u0003חרש,\u0004 ש\u0003לא אתי\u0004 \u0005[יבוא]\u0006 בעתיד \u0003לכלל נשואין\u0004 מן התורה — \u0003תקינו רבנן\u0004 \u0005[תיקנו\u0006 לו \u0005חכמים]\u0006 \u0003נשואין,\u0004 על כל פנים מדבריהם, ואילו \u0003קטן, דאתי\u0004 \u0005[שבא]\u0006 \u0003לכלל נשואין\u0004 מן התורה, לכשיגדל — \u0003לא תקינו רבנן\u0004 \u0005[תיקנו\u0006 לו \u0005חכמים]\u0006 \u0003נשואין.\u0004","ומקשים: \u0003והרי קטנה, דאתיא\u0004 \u0005[שבאה]\u0006 לבסוף \u0003לכלל נשואין\u0004 מן התורה, \u0003ו\u0004בכל זאת \u0003תקינו רבנן\u0004 \u0005[תיקנו\u0006 לה \u0005חכמים]\u0006 \u0003נשואין,\u0004 שיכולים אימה ואחיה להשיא אותה ונישואין אלה אינם אלא מדברי סופרים! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 עשו תקנה זו מפני טעם אחר — \u0003שלא ינהגו בה מנהג הפקר,\u0004 שאם תינשא — ישגיח עליה בעלה, ואם לא — יש חשש שינהגו ביתומה זו מנהג הפקר. ושואלים: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003קטנה דממאנה\u0004 \u0005[שממאנת]\u0006 ויכולה לעקור את נישואיה על ידי מיאון, \u0003ומאי שנא חרשת\u0004 \u0005[ו\u0006ב\u0005מה שונה חרשת]\u0006 \u0003דלא ממאנה\u0004 \u0005[שאינה ממאנת]\u0006 ולא תיקנו בה דין מיאון? הרי לכאורה, כיון שגם נישואין אלה אינם אלא מדברי סופרים, היו צריכים לתקן שתוכל גם היא למאן! ומשיבים: ש\u0003אם כן,\u0004 שהיו מתקנים מיאון גם בחרשת,",""],["\u0003מימנעי ולא נסבי לה\u0004 \u0005[יימנעו ולא ישאו אותה]\u0006 כלל, כיון שתוכל למאן לעולם, מה שאין כן בקטנה, שיש גבול של זמן למיאונה.","ועוד שואלים: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003קטנה דאכלה\u0004 \u0005[שאוכלת]\u0006 \u0003בתרומה\u0004 כשנישאת לכהן, \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003חרשת דלא אכלה\u0004 \u0005[שאינה אוכלת]\u0006 \u0003בתרומה,\u0004 אף על פי שנישואי שתיהן הם רק מדברי סופרים? \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003העיד ר' יוחנן בן גודגדא על החרשת שהשיאה אביה שיוצאה בגט, ועל קטנה בת ישראל שנשאת לכהן שאוכלת בתרומה, ו\u0004משמע \u0003אילו\u0004 היא \u0003חרשת לא אכלה\u0004 \u0005[אינה אוכלת]\u0006 בתרומה!","ומשיבים: הטעם בחרשת הוא מפני \u0003גזירה, שמא יאכיל\u0004 בתרומה גם כהן \u0003חרש\u0004 שנשא \u0003חרשת.\u0004 ושואלים: איזה איסור יש בדבר? \u0003וליכול\u0004 \u0005[ושיאכיל]!\u0006 הלוא \u0003קטן אוכל נבלות הוא,\u0004 שכן החרש שאין בו דעת דינו כקטן, וקטן האוכל נבילות אין חייבים להפרישו מהן. ואם תאכל חרשת זו בתרומה שלא כדין, אין אנו חייבים למנוע את הדבר.","אלא הטעם הוא: \u0003גזירה שמא יאכיל חרש בפקחת,\u0004 שהיא בת דעת, וכיון שמן התורה אין נישואיה לחרש תופסים — אסור לה לאכול. ושואלים: \u0003וחרש בפקחת נמי ליכול\u0004 \u0005[גם כן שתאכל]\u0006 \u0003בתרומה דרבנן\u0004 \u0005[שמדברי סופרים],\u0006 שיש דברים שמן התורה אין מפרישים מהם תרומה, ורק מתקנת חכמים מפרישים. וזו כשם שנישואיה הם מדברי סופרים — כך תאכל בתרומה שמדברי סופרים! ומשיבים: \u0003גזירה דלמא אתי לאוכלה\u0004 \u0005[שמא יבוא להאכילה]\u0006 אף \u0003בתרומה דאורייתא\u0004 \u0005[שמן התורה].\u0006","ועוד שואלים: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003קטנה דאית\u0004 \u0005[שיש]\u0006 \u0003לה כתובה, ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003חרשת דלית\u0004 \u0005[שאין]\u0006 \u0003לה כתובה?\u0004 ומשיבים: ש\u0003אם כן,\u0004 שיצטרכו לתת לה כתובה — \u0003מימנעי\u0004 \u0005[יימנעו]\u0006 \u0003ולא נסבי לה\u0004 \u0005[ישאו אותה]\u0006 כלל.","ושואלים: \u0003וקטנה מנלן דאית\u0004 \u0005[מניין לנו שיש]\u0006 \u0003לה כתובה?\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 קטנה \u0003הממאנת\u0004 בבעלה, ויצאה ממנו, \u0003ו\u0004כן \u0003השנייה\u0004 שאסורה משום ערוה שמדברי סופרים, \u0003ו\u0004ה\u0003איילונית\u0004 שהתברר כי איננה מסוגלת ללדת כלל — \u0003אין להן כתובה. אבל\u0004 כל ה\u0003יוצאה בגט, וקטנה\u0004 בכלל זה — \u0003יש לה כתובה.\u0004","ושואלים: \u0003וחרשת מנלן דלית\u0004 \u0005[מניין לנו שאין]\u0006 \u0003לה כתובה?\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חרש ושוטה שנשאו פקחות, אף על פי שנתפקח החרש\u0004 אחר כך, \u0003ונשתפה\u0004 (חזר לשפיותו) \u0003השוטה — אין להם\u0004 לנשותיהם \u0003עליהם כלום,\u0004 שאינן יכולות לתבוע מהם דבר גם אם כתבו להן כתובה. ואם \u0003רצו לקיימן\u0004 לאחר שנעשו בני דעת — \u0003יש להם\u0004 מאז \u0003כתובה,\u0004 כדרך כל בני דעת הנושאים נשים.","\u0003ופקח שנשא חרשת או שוטה,\u0004 אם רצה וכתב לה כתובה, \u0003אפילו כתב לה מאה מנה — כתובתה קיימת, מפני שרצה לזוק בנכסיו,\u0004 כלומר, כיון שעשה כן מרצונו, בלי שחייבוהו חכמים, הרי זה כאדם שרוצה להזיק עצמו ולהוציא מנכסיו בכל דרך, שהרשות בידו לעשות כן. ונלמד מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003רצה\u0004 לכתוב לה כתובה, \u0003הא\u0004 \u0005[הרי]\u0006 כש\u0003לא רצה — אין לה\u0004 כתובה. והטעם: ש\u0003אם כן,\u0004 שהיו מחייבים לתת לחרשת כתובה, \u0003מימנעי\u0004 \u0005[\u0006היו \u0005נמנעים]\u0006 \u0003ולא נסבי לה\u0004 \u0005[\u0006היו \u0005נושאים אותה].\u0006","שואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 כאשר \u0003פקחת\u0004 נישאת \u0003לחרש, ליתקן\u0004 \u0005[שיתקנו]\u0006 \u0003לה\u0004 חכמים \u0003כתובה,\u0004 ש\u0003אם כן,\u0004 שאין להן כתובה, \u0003מימנעי\u0004 \u0005[יימנעו\u0006 הפקחות\u0005]\u0006 \u0003ולא מינסבי\u0004 \u0005[יינשאו]\u0006 לחרשים כלל! ומשיבים: \u0003יותר משהאיש רוצה לישא,\u0004 ה\u0003אשה רוצה להנשא,\u0004 וכיון שכך, אם האשה רוצה מאוד להינשא — היא לא תקפיד גם אם אין לה כתובה.","מסופר: \u0003ההוא חרש דהוה בשבבותיה\u0004 \u0005[חרש אחד שהיה בשכנותו]\u0006 של \u0003רב מלכיו, אנסביה איתתא\u0004 \u0005[השיאו\u0006 רב מלכיו \u0005אשה]\u0006 \u0003וכתב לה ארבע מאה זוזי מנכסיה\u0004 \u0005[ארבע מאות זוז מנכסיו\u0006 של החרש\u0005]\u0006 לכתובתה. \u0003אמר רבא: מאן חכים\u0004 \u0005[מי חכם]\u0006 \u0003כרב מלכיו, דגברא רבה\u0004 \u0005[שאדם גדול]\u0006 \u0003הוא,\u0004 שמצא דרך לעשות דבר שאין האיש מחוייב בו על פי הדין. \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 כך: \u0003אילו רצה\u0004 אותו חרש \u0003שפחה לשמשו — מי\u0004 \u0005[האם]\u0006 \u0003לא זבנינן ליה\u0004 \u0005[היינו קונים לו]?\u0006 \u0003כל שכן הכא, דאיכא תרתי\u0004 \u0005[כאן, שיש שתיים],\u0006 שהיא גם מסייעת לו כשפחה וגם משמשת לו אשה.","\u0003אמר רב חייא בר אשי אמר שמואל: אשת חרש\u0004 שבא עליה אדם אחר בשוגג — \u0003אין חייבין עליה אשם תלוי.\u0004 כי הבא על אשת איש בשוגג מביא חטאת, ואם היה זה רק ספק אשת איש מביא אשם תלוי, אולם נישואי חרש אינם אפילו בגדר ספק נישואין.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[\u0006האם \u0005לומר\u0006 שאפשר \u0005לסייע לו]\u0006 לשמואל ממה ששנינו: \u0003חמשה לא יתרומו, ואם תרמו — אין תרומתן תרומה\u0004 כלל. \u0003ואלו הן: חרש, שוטה, וקטן, והתורם את\u0004 התבואה \u0003שאינו שלו, וגוי שתרם\u0004 את \u0003של ישראל אפילו ברשות ישראל — אין תרומתו תרומה.\u0004 ומכאן שאין מעשה החרש נחשב כלל, ואפילו לא כספק.","ודוחים: מכאן אין ראיה, כי יתכן שלענין תרומה סבור \u0003הוא\u0004 שמואל, ו\u0003אמר כר' אלעזר. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יצחק אומר משום ר' אלעזר: תרומת חרש לא תצא לחולין, מפני שהוא ספק.\u0004 שאין הוא סבור שמעשיו לא נחשבים כלל. ושואלים: \u0003אי סבירא\u0004 \u0005[אם סבור]\u0006 שמואל \u0003כר' אלעזר,\u0004 שהחרש הוא ספק בן דעת, אם כן \u0003אשם תלוי נמי ליחייב\u0004 \u0005[גם כן שיתחייב]\u0006 הבא על אשתו!","ומשיבים: \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003חתיכה משתי חתיכות,\u0004 כלומר, לדעת שמואל אין מביאים אשם תלוי בכל מקרה של ספק חיוב חטאת, אלא רק בספק כזה, שברור לנו כי חתיכה אחת היתה ודאי אסורה (כגון חלב) ואחת מותרת — אלא שלא ידע בוודאות איזו מהן אכל. אבל כשהספק הוא בגוף אחד, שאין ברור אם הוא אסור או מותר — במקרה כזה אין מביאים לדעתו אשם תלוי. ואף כאן הספק באשת חרש הוא ספק בעצם האיסור כיצד דנים את נישואיו.","ותוהים: \u0003ומי בעי\u0004 \u0005[והאם מצריך]\u0006 \u0003ר' אלעזר\u0004 כדי לחייב אשם תלוי שתהא זו \u0003חתיכה משתי חתיכות? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אלעזר אומר: כוי\u0004 (בעל חיים שהוא ספק חיה ספק בהמה) — \u0003חייבין על\u0004 אכילת \u0003חלבו אשם תלוי.\u0004 שחלב חיה מותר באכילה, וחלב בהמה אסור וחייב עליו חטאת, והכוי, כיון שהוא ספק — מביא על חלבו אשם תלוי. ומכאן שר' אלעזר סבור, שמביאים אשם תלוי גם על ספק הקיים בחתיכה אחת!","ומשיבים: \u0003שמואל סבר כר' אלעזר בחדא\u0004 \u0005[ב\u0006דבר \u0005אחד]\u0006 בדין החרש, \u0003ופליג עליה בחדא\u0004 \u0005[וחלק עליו ב\u0006דבר \u0005אחד] —\u0006 בדין אשם תלוי.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 גירסה אחרת. \u0003אמר רב חייא בר אשי אמר שמואל: אשת חרש חייבין עליה אשם תלוי,\u0004 משום הספק. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך: \u0003חמשה לא יתרומו\u0004 וכו', ומשמע מכאן שמעשה חרש אינו כלום! ומשיבים: \u0003סבר לה\u0004 \u0005[סבור\u0006 שמואל\u0005]\u0006 \u0003כר' אלעזר\u0004 שאף תרומת חרש ספק היא, וכן כל מעשיו.","\u0003בעא\u0004 \u0005[שאל]\u0006 \u0003רב אשי\u0004 שאלה זו: \u0003מאי טעמא\u0004 \u0005[מה הטעם],\u0006 מה עיקר שיטתו של \u0003ר' אלעזר?\u0004 האם \u0003מיפשט פשיטא ליה דחרש דעתא קלישתא הוא\u0004 \u0005[פשוט לו שחרש הוא\u0006 בעל \u0005דעה קלושה],\u0006 \u0003ומיהו מספקא ליה\u0004 \u0005[ומכל מקום מסופק לו]\u0006 \u0003אי דעתא צילותא\u0004 \u0005[אם דעה צלולה\u0006 היא\u0005],\u0006 שאותה דעה קלושה, אף שאינה כדעת שאר בני אדם, ואינו מבין הכל — מכל מקום בדברים מסויימים שהוא מחליט לעשות, יש לו דעה צלולה, והוא יודע במה שהוא עושה,"],["\u0003אי לאו דעתא צילותא\u0004 \u0005[או\u0006 ש\u0005אין\u0006 זו \u0005דעה צלולה]\u0006 ואין הוא מגיע להבנה ברורה ושלימה, \u0003ו\u0004מכל מקום, לדעתו \u0003לעולם חדא דעתא\u0004 \u0005[דעה אחת]\u0006 \u0003הוא,\u0004 כלומר, החרש עומד כל ימיו בדרגה אחת של דעת. \u0003או דלמא פשיטא ליה דדעתיה קלישתא ולאו דעתא צילותא\u0004 \u0005[שמא פשוט לו שדעתו קלושה ולא דעה צלולה]\u0006 \u0003היא, והכא היינו טעמא\u0004 \u0005[וכאן זהו הטעם]\u0006 של הספק: \u0003כיון\u0004 של \u0003עתים\u0004 הוא \u0003חלים\u0004 \u0005[בריא]\u0006 ודעתו צלולה \u0003ועתים שוטה\u0004 ואין דעתו צלולה, שאינו כל ימיו באותה דרגת הבנה, וזו משתנה מפעם לפעם, יש לפיכך להסתפק במעמדו.","ומסבירים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]?\u0006 מה ההבדל אם מגדירים את דעת החרש בדרך זו או אחרת? — לענין \u0003להוציא אשתו בגט. אי אמרת חדא דעתא הוא\u0004 \u0005[אם אומר אתה\u0006 שדעת חרש \u0005דעה אחת היא] —\u0006 אם כן \u0003כקדושין כך גירושין,\u0004 וכיון שבקידושין היתה לו דעה קלושה, אף בגירושין היתה לו דעה כזאת, ויכול לגרשה.","\u0003ו\u0004אולם \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003עתים חלים\u0004 \u0005[בריא]\u0006 \u0003ועתים שוטה\u0004 — אם כן \u0003קדושי מצי מקדש\u0004 \u0005[לקדש יכול\u0006 הוא\u0005],\u0006 כי אנו מחמירים וחוששים שמא בריא וצלול היה באותה שעה, אבל \u0003גרושי לא מצי מגרש\u0004 \u0005[לגרש אינו יכול],\u0006 שאין להתיר את אשתו, מפני החשש שמא בשעה זו שוטה היה. ואם כן \u0003מאי\u0004 \u0005[מה]\u0006 הפתרון לשאלה? והואיל שלספק זה לא נמצא פתרון נשארה השאלה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה, כי מי ש\u0003נשתטית\u0004 אשתו — אינו מוציא אותה. \u0003אמר ר' יצחק: דבר תורה שוטה מתגרשת, מידי דהוה\u0004 \u0005[כמו ש\u0006הדבר \u0005הוא]\u0006 אצל ה\u0003פקחת,\u0004 שמתגרשת \u0003בעל כרחה.\u0004 וכיון שאין צורך בדעת האשה בגירושין, הרי חסרון דעתה של השוטה אינו גורם מעכב בגירושיה. \u0003ו\u0004אולם, \u0003מה טעם אמרו\u0004 חכמים \u0003אינה מגורשת? שלא ינהגו בה\u0004 אנשים \u0003מנהג הפקר,\u0004 שכיון שאין בה דעת, ואין לה בעל שישמור אותה — יש לחשוש שינהגו בה מנהג הפקר.","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 היה \u0005הדבר בדיוק]?\u0006 מה טיבה של שוטה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיא כזו ש\u0003יודעת לשמור\u0004 את \u0003גיטה,\u0004 שמבינה מהו ענין הגט, \u0003ויודעת\u0004 גם \u0003לשמור\u0004 את \u0003עצמה — מי נהגי\u0004 \u0005[האם נוהגים]\u0006 \u0003בה מנהג הפקר?\u0004 הרי יודעת היא לשמור את עצמה! \u0003אלא\u0004 צריך לומר, שמדובר באשה ש\u0003אין יודעת לשמור לא\u0004 את \u0003גיטה ולא\u0004 את \u0003עצמה.\u0004","ואולם, האם אפשר לומר במקרה כזה כי \u0003דבר תורה שוטה מתגרשת? והא\u0004 \u0005[והרי]\u0006 \u0003אמר דבי\u0004 \u0005[\u0006החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי,\u0004 נאמר: \u0003\"\u0004וכתב לה ספר כריתות \u0003ונתן בידה\"\u0004 (דברים כד, ג), כלומר, \u0003מי שיש לה יד,\u0004 דהיינו, שהיא אישיות בעלת דעת \u0003לגרש עצמה,\u0004 לקבל את גיטה, \u0003יצתה\u0004 (יצאה) \u0003זו,\u0004 שוטה גמורה, \u0003שאין לה יד לגרש עצמה.\u0004","\u0003ותנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 באופן שונה במקצת, נאמר שם: \u0003\"ושלחה מביתו\",\u0004 כלומר, שיכול לגרש את \u0003מי שמשלחה\u0004 מביתו \u0003ואינה חוזרת, יצתה זו,\u0004 השוטה, \u0003שמשלחה וחוזרת,\u0004 שאינה מבינה מהו ענין הגירושין.","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 ההלכה של ר' יצחק אלא באשה ש\u0003יודעת לשמור גיטה ואינה יודעת לשמור עצמה,\u0004 שעל פי \u0003דבר תורה שוטה\u0004 כזו \u0003מתגרשת, דהא\u0004 \u0005[שהרי]\u0006 \u0003יודעת לשמור גיטה, ואמור רבנן\u0004 \u0005[ואמרו חכמים]\u0006 ש\u0003לא ליפקא\u0004 \u0005[יוציא,\u0006 יגרש\u0005],\u0006 כדי \u0003שלא ינהגו בה מנהג הפקר,\u0004 שהרי אינה יודעת לשמור עצמה.","\u0003אמר אביי: דיקא נמי\u0004 \u0005[מדוייק גם כן],\u0006 שכך צריך להבין את המשנה, \u0003דקתני גבי דידה\u0004 \u0005[ששנה לגביה]\u0006 \u0003\"נשתטית לא יוציא\", וגבי דידיה\u0004 \u0005[ולגביו]\u0006 שנה אם נשתטה הוא \u0003\"לא יוציא עולמית\",\u0004 ויש להבין, \u0003מאי שנא הכא דקתני\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 הענין \u0005כאן ששנה]\u0006 \u0003\"עולמית\" ומאי שנא התם\u0004 \u0005[ו\u0006ב\u0005מה שונה\u0006 הענין \u0005שם]\u0006 ש\u0003לא קתני\u0004 \u0005[שנה]\u0006 \u0003\"עולמית\"? אלא\u0004 האם לא \u0003שמע מינה\u0004 \u0005[תלמד מכאן],\u0006 כי \u0003הא\u0004 \u0005[זו]\u0006 שאין שוטה יכול לגרש — \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 כשהיא שוטה — \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 שמפני גזירת חכמים לא יגרשנה, ולכן לא הוסיף \"עולמית\".","שנינו במשנה, ש\u0003אמר ר' יוחנן בן נורי:\u0004 מפני מה אשה שנתחרשה יוצאה והאיש שנתחרש אינו מוציא? ועל כך \u0003איבעיא להו\u0004 \u0005[נשאל להם\u0006 ללומדים\u0005]\u0006 מה כוונת הדברים? האם \u0003ר' יוחנן בן נורי,\u0004 לגבי \u0003איש\u0004 שהוא חרש, \u0003פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 שאינו יכול לגרש, \u0003ו\u0004לגבי \u0003אשה קמיבעיא ליה\u0004 \u0005[מסופק לו]\u0006 האם אפשר לגרשה כשהיא חרשת. \u0003או דלמא\u0004 \u0005[שמא],\u0006 \u0003אשה\u0004 חרשת \u0003פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 שאפשר לגרש אותה, \u0003ו\u0004לענין \u0003איש\u0004 חרש \u0003קמיבעיא ליה\u0004 \u0005[נסתפק לו]\u0006 מדוע אינו יכול לגרש.","ומביאים הוכחה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003מדקאמרו ליה\u0004 \u0005[מ\u0006מה \u0005שאמרו לו]\u0006 לר' יוחנן בן נורי כהסבר להבדל: \u0003אינו דומה האיש המגרש לאשה המתגרשת — שהאשה יוצאת לרצונה ושלא לרצונה, והאיש אינו מוציא אלא לרצונו — שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי בענין \u0003איש קמיבעיא ליה\u0004 \u0005[נסתפק לו]\u0006 ולא לגבי האשה. שאם היה מסופק לו בענין האשה, אם כן היה להם לנקוט בלשון \"אינה דומה האשה לאיש וכו'\". ודוחים: \u0003אדרבה\u0004 (להיפך), \u0003מדקאמרו ליה\u0004 \u0005[מ\u0006מה \u0005שאמרו לו]\u0006 חכמים בהמשך המשנה \u0003\"אף זו כיוצא בה\", שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי בענין \u0003אשה קמיבעיא ליה\u0004 \u0005[נסתפק לו].\u0006","\u0003אלא\u0004 כך צריך לפרש: \u0003ר' יוחנן בן נורי לדבריהם\u0004 של חכמים \u0003קאמר להו\u0004 \u0005[אמר להם],\u0006 ולפי שיטתם. וכך צריך להבין את שאלתו: \u0003לדידי, כי היכי\u0004 \u0005[לשיטתי, כמו]\u0006 שה\u0003איש לא מצי מגרש\u0004 \u0005[אינו יכול לגרש]\u0006 — \u0003אשה\u0004 חרשת \u0003נמי לא מיגרשא\u0004 \u0005[גם כן אינה מתגרשת],\u0006 \u0003אלא לדידכו\u0004 \u0005[לשיטתכם],\u0006 \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003אשה ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003איש! אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אינו דומה האיש המגרש לאשה המתגרשת.\u0004","שנינו במשנה: \u0003העיד ר' יוחנן\u0004 בן גודגדא על קטנה חרשת שהשיאה אביה, ונישואיה תופסים מן התורה, ובכל זאת יוצאת בגט כשבגרה אף שאינה בת דעת. \u0003אמר רבא: מ\u0004תוך \u0003עדותו\u0004 זו \u0003של ר' יוחנן בן גודגדא\u0004 נלמד שאם \u0003אמר לעדים: \"ראו גט זה שאני נותן\u0004 לאשתי \u0003\"\u0004, \u0003ו\u0004בפועל \u0003אמר לה\u0004 בלשון זה: \u0003\"כנסי\u0004 (קחי) \u0003שטר חוב זה\" — הרי זו מגורשת,\u0004 אף שבשעת נתינת הגט לא ידעה האשה שהוא גט.","וכך הוא למד: \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אמר ר' יוחנן בן גודגדא\u0004 כי \u0003לא בעינן\u0004 \u0005[צריכים אנו]\u0006 את \u0003דעתה,\u0004 ואין צורך שהאשה תבין שהיא מקבלת גט — \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003לא בעינן\u0004 \u0005[צריכים אנו]\u0006 את \u0003דעתה,\u0004 ואפילו היא חושבת שזה שטר חוב — מגורשת. ושואלים: הרי לכאורה \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שאין צורך בדעת האשה, ומה איפוא חידש רבא?","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003מ\u0004כיון ש\u0003אמר לה \"כנסי שטר חוב זה\"\u0004 — שמא \u0003בטולי בטליה\u0004 \u0005[ביטל אותו\u0006 את הגט\u0005],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין אנו רואים בזה נוסח של ביטול. שכן \u0003אי איתא דבטליה\u0004 \u0005[אם אכן ביטלו] —\u0006 \u0003לעדים הוה קאמר להו\u0004 \u0005[היה אומר להם],\u0006 \u0003ומ\u0004כיון ש\u0003לא אמר לעדים — לא בטליה\u0004 \u0005[ביטלו]\u0006 \u0003ולא מידי\u0004 \u0005[כלום].\u0006 \u0003והאי דקאמר הכי\u0004 \u0005[וזה שאמר כך]\u0006 \"כנסי שטר חוב\" — \u0003מחמת כיסופא\u0004 \u0005[בושה]\u0006 \u0003הוא דקאמר להו\u0004 \u0005[שאמר להם,\u0006 לה, כך\u0005],\u0006 שבאמת התכוון לגרשה, ואמר לה באופן כזה שלא תדע בשעת מעשה מה הוא עושה.","מסופר: \u0003רב יצחק בר ביסנא אירכסו ליה מפתחי דבי מדרשא\u0004 \u0005[אבדו לו מפתחות של בית המדרש]\u0006 \u0003ברשות הרבים בשבתא\u0004 \u0005[בשבת],\u0006 ואי אפשר היה לפתוח את בית הכנסת, כי לא יכלו להביא את המפתח מכיון שאסור לטלטל ברשות הרבים, \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' פדת\u0004 לשאול מה לעשות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' פדת: \u0003זיל\u0004 \u0005[לך]\u0006"],["\u0003דבר טלי וטליא\u0004 \u0005[הובל ילדים וילדות]\u0006 \u0003וליטיילו התם\u0004 \u0005[ושיטיילו שם]\u0006 במקום שאבדו המפתחות, \u0003דאי משכחי להו, מייתי להו\u0004 \u0005[שאם ימצאו אותם,\u0006 את המפתחות, \u0005יביאו אותם\u0006 מדעתם\u0005],\u0006 ואתה אל תאמר להם דבר. ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 ש\u0005סבור\u0006 הוא\u0005]:\u0006 \u0003קטן\u0004 ה\u0003אוכל נבלות\u0004 (או עובר עבירה אחרת) — \u0003אין בית דין מצווין להפרישו\u0004 לפי שאינו חייב במצוות. ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[\u0006האם \u0005לומר\u0006 שאפשר \u0005לסייע לו]\u0006 ממה ששנינו: \u0003לא יאמר אדם לתינוק\u0004 בשבת \u0003\"הבא לי מפתח\",\u0004 או \u0003\"הבא לי חותם\"\u0004 מרשות הרבים, \u0003אלא מניחו\u0004 לתינוק להיות \u0003תולש,\u0004 וכן \u0003מניחו\u0004 לתינוק להיות \u0003זורק\u0004 ברשות הרבים. מכאן שאין מקפידים על תינוק כשעובר עבירה, ובלבד שלא יאמרו לו במפורש לעשות כן.","\u0003אמר אביי\u0004 לדחות: מכאן אין ראיה, כי אפשר לפרש \u0003\"תולש\"\u0004 — שתולש \u0003בעציץ שאינו נקוב,\u0004 שאיסור תלישה ממנו הוא רק מדברי סופרים, וכן \u0003\"זורק\"\u0004 — כוונתו לא ברשות הרבים, אלא \u0003בכרמלית\u0004 (רשות ממוצעת, מעין רשות הרבים מדברי סופרים), שאיסור טלטול בה הוא רק \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 ושמא רק באיסור מן התורה מפרישים אותו.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003גוי שבא לכבות\u0004 דליקה בשבת — \u0003אין אומרים לו \"כבה\", ו\u0004גם אין אומרים לו \u0003\"אל תכבה\", מפני שאין שביתתו עליהם,\u0004 ואין ישראל חייבים לדאוג שישבות בשבת. ואילו \u0003קטן הבא לכבות\u0004 — \u0003אומרים לו \"אל תכבה\",\u0004 משום \u0003ששביתתו\u0004 מוטלת \u0003עליהם.\u0004 הרי שמפרישים את הקטן מאיסור תורה!","\u0003אמר ר' יוחנן:\u0004 כאן מדובר \u0003ב\u0004קטן ה\u0003עושה על דעת אביו,\u0004 שגם אם לא אמר לו במפורש, מבין התינוק שזה רצון אביו, ועושה זאת למענו. ושואלים: \u0003דכוותיה\u0004 \u0005[כיוצא בו]\u0006 \u0003גבי גוי\u0004 צריך איפוא לומר שהוא \u0003עושה על דעת ישראל,\u0004 אולם במקרה זה \u0003מי שרי\u0004 \u0005[האם מותר]\u0006 שיעשה מלאכה עבור ישראל ולדעת ישראל? ומשיבים: \u0003גוי אדעתא דנפשיה עביד\u0004 \u0005[על דעת עצמו\u0006 הוא \u0005עושה],\u0006 שכיון שהוא מבוגר, הריהו עושה מתוך החלטתו שלו, ולא בהוראת אחרים.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקור אחר, ששנינו: \u0003בן\u0004 של \u0003חבר\u0004 (אדם הנזהר בהפרשת תרומות ומעשרות) \u0003שרגיל לילך אצל אבי אמו\u0004 שהוא \u0003עם הארץ — אין חוששין שמא יאכילנו\u0004 סבו זה \u0003דברים שאינם מתוקנים\u0004 (אינם מעושרים). \u0003מצא\u0004 האב \u0003בידו\u0004 של התינוק \u0003פירות\u0004 ואינו יודע מהיכן הם — \u0003אין זקוק לו,\u0004 כלומר, אינו מצווה להפריש מהם מעשרות. משמע שלא מונעים מהקטן לאכול איסור! \u0003אמר ר' יוחנן: בדמאי הקילו.\u0004 כיון שאיסור דמאי שהוא רק שמא איננו מעשר, ורוב עמי הארץ מעשרים, ואולי הוא מהרוב המעשרים, לכן לא החמירו כאן חכמים.","ומדייקים: \u0003אלא טעמא\u0004 \u0005[הטעם]\u0006 שהקילו דווקא משום ש\u0003דמאי\u0004 הוא, \u0003הא\u0004 \u0005[הרי]\u0006 אם היה זה טבל \u0003ודאי — בעא לעשורי\u0004 \u0005[\u0006היה האב \u0005צריך לעשר]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן\u0004 עצמו, שצריך להרחיק קטן רק \u0003בעושה על דעת אביו! אלא\u0004 יש לומר כי \u0003ר' יוחנן ספוקי מספקא ליה\u0004 \u0005[מסופק\u0006 היה \u0005אצלו]\u0006 דין זה, ולכן \u0003קאי הכא\u0004 \u0005[\u0006כשהוא \u0005עומד כאן] —\u0006 \u0003מדחי\u0004 \u0005[דוחה\u0006 אותו לצד אחר\u0005],\u0006 \u0003קאי הכא\u0004 \u0005[\u0006כשהוא \u0005עומד כאן] —\u0006 \u0003מדחי\u0004 \u0005[דוחה\u0006 אותו לצד אחר\u0005],\u0006 שאין לו הכרעה מוחלטת בדבר, אלא שבוחן הוא את הראיות לכאן ולכאן.","ומציעים עוד \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003בן\u0004 של \u0003חבר כהן שרגיל לילך אצל אבי אמו\u0004 שהוא \u0003כהן עם הארץ — אין חוששין שמא יאכילנו\u0004 הסב \u0003תרומה טמאה, מצא\u0004 האב \u0003בידו\u0004 של הקטן \u0003פירות — אין זקוק לו\u0004 לקחת אותם ממנו. הרי שאפילו במקום שיש חשש תרומה טמאה, שהוא מן התורה, אין זקוק לו! ודוחים: משם אין ראיה, כי מדובר שם \u0003בתרומה דרבנן\u0004 \u0005[שמדברי סופרים],\u0006 ואין בכך ספק איסור מן התורה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקום אחר: \u0003יונק תינוק והולך\u0004 (וממשיך) \u0003מגויה ומבהמה טמאה, ואין חוששין\u0004 לומר שהוא \u0003ב\u0004גדר \u0003יונק שקץ,\u0004 כלומר, כיונק מדבר טמא, משוקץ. אבל \u0003לא יאכילנו\u0004 את התינוק \u0003נבלות וטרפות שקצים ורמשים. ומכולן,\u0004 אפילו מן הטמאים \u0003יונק מהם ואפילו בשבת. ובגדול אסור\u0004 לינוק בשבת אפילו מבהמה טהורה. \u0003אבא שאול אומר: נוהגין היינו שיונקים\u0004 (ולא חולבים) \u0003מבהמה טהורה ביום טוב.\u0004","\u0003קתני מיהא\u0004 \u0005[שנה על כל פנים]\u0006 ש\u0003אין חוששין ב\u0004תינוק ה\u0003יונק\u0004 מן ה\u0003שקץ,\u0004 משמע שאין חוששים לתינוק אם הוא אוכל דבר איסור! ודוחים: \u0003התם\u0004 \u0005[שם]\u0006 ההיתר הוא \u0003משום סכנה\u0004 שבדבר, שהתינוק זקוק לכך ומוכרח לאכול. ואומרים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדובר בחשש סכנה — \u0003גדול נמי\u0004 \u0005[גם כן]\u0006 יהא מותר לו, שהרי פיקוח נפש דוחה איסורים אלה!","ומשיבים: \u0003גדול בעי אומדנא\u0004 \u0005[צריך אומדן],\u0006 שיבדקוהו רופאים או מומחים אחרים ויקבעו שהוא באמת חולה עד כדי סכנה. ומקשים: \u0003קטן נמי ליבעי אומדנא\u0004 \u0005[גם כן שיצטרך אומדן]\u0006 אם מסוכן הוא! \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 אין צורך באומדן מיוחד, כי \u0003סתם תינוק מסוכן אצל חלב,\u0004 שמן הסתם נחוץ לו החלב מאוד, ואם לא ישתה יסתכן.","אגב הדיון מביאים מה ששנינו באותה ברייתא, \u0003אבא שאול אומר: נוהגין היינו שיונקים מבהמה טהורה ביום טוב.\u0004 ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה \u0005הדבר]?\u0006 \u0003אי דאיכא\u0004 \u0005[אם\u0006 בדבר \u0005שיש\u0006 בו\u0005]\u0006 \u0003סכנה,\u0004 אם כן \u0003אפילו בשבת נמי\u0004 \u0005[גם כן]\u0006 יהא מותר, \u0003ואי דליכא\u0004 \u0005[ואם\u0006 בדבר \u0005שאין\u0006 בו\u0005]\u0006 \u0003סכנה — אפילו ביום טוב אסור!\u0004 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דאיכא צערא\u0004 \u0005[שיש צער]\u0006 כלומר, היו צמאים וסבלו מכך, אבל לא היתה סכנה בדבר.","\u0003וקסבר\u0004 \u0005[וסבור הוא]\u0006 שיניקה מבהמה \u0003מפרק כלאחר יד הוא.\u0004 שאיסור חליבה הוא תולדה ממלאכת המפרק (\"דש\"), שמוציא אוכל מתוך דבר שאינו ראוי לאכילה, ואם עושה זאת שלא כדרכו (בחליבה), אלא כלאחר יד, בדרך שינוי (ביניקה), אינו אסור אלא מפני גזירת חכמים. ולכן, באיסור \u0003שבת\u0004 שהוא מעיקרו \u0003איסור\u0004 שהעובר עליו חייב \u0003סקילה — גזרו רבנן\u0004 \u0005[חכמים]\u0006 אפילו כשעושה זאת כלאחר יד, ואולם ב\u0003יום טוב\u0004 שאיסור המלאכה בו הוא רק \u0003איסור לאו\u0004 \u0005[לא\u0006 תעשה\u0005] —\u0006 \u0003לא גזרו ביה רבנן\u0004 \u0005[בו חכמים]\u0006 כשיש צער. על כל פנים לא מצאנו ראיה לענין תינוק אוכל נבילות.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: נאמר בשרצים ובבעלי חיים טמאים: \u0003\"לא תאכלום כי שקץ הם\"\u0004 (שם יא, מב), ופירשו כאילו היה כתוב \u0003\"לא תאכילום\"\u0004 — בא הכתוב \u0003להזהיר\u0004 את \u0003הגדולים על הקטנים,\u0004 שלא רק שהם אסורים באכילה אלא שאף אסור לגדולים להאכילם לאחרים. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 ללמדנו \u0003דאמרי להו\u0004 \u0005[שאומרים להם]\u0006 הגדולים לקטנים: \u0003\"לא תאכלו\",\u0004 להפרישם מעבירה! ודוחים: \u0003לא,\u0004 הכוונה היא ש\u0003לא ליספו ליה\u0004 \u0005[יאכילו לו],\u0006 לקטן, \u0003בידים\u0004 דבר טמא, אבל אין הוכחה מכאן שצריך להפרישו כשהוא אוכל בעצמו.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו במקום אחר, נאמר: \u0003\"כל נפש מכם לא תאכל דם\"\u0004 (שם יז, יב), הרי זה בא \u0003להזהיר הגדולים על הקטנים.\u0004 ומנסים לומר: \u0003מאי לאו דאמרי להו\u0004 \u0005[האם לא\u0006 מדובר \u0005ש\u0006הגדולים \u0005אומרים להם\u0006 לקטנים\u0005]\u0006 \u0003\"לא תאכלו\u0004 דם \u0003\"\u0004! ודוחים: \u0003לא,\u0004 אף כאן הכוונה ש\u0003לא ליספו להו\u0004 \u0005[יאכילו אותם]\u0006 \u0003בידים.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו במקום אחר, נאמר: \u0003\"אמור\u0004 אל הכהנים בני אהרן \u0003ואמרת\u0004 אליהם לנפש לא יטמא בעמיו\u0003\"\u0004 (ויקרא כא, א) — הכפילות הזו \"אמור\" \"ואמרת\" באה \u0003להזהיר גדולים על הקטנים. מאי לאו דאמר להו\u0004 \u0005[האם לא\u0006 מדובר \u0005ש\u0006הגדול \u0005אומר להם]\u0006 לקטנים: \u0003\"לא תיטמו\"\u0004 \u0005[\"אל תיטמאו\"]!\u0006 ודוחים: \u0003לא,\u0004 אפשר לפרש ש\u0003לא ליטמו להו\u0004 \u0005[יטמאו אותם]\u0006 \u0003בידים.\u0004","ומעירים: \u0003וצריכי\u0004 \u0005[וצריכים]\u0006 להיאמר שלושה כתובים אלו, למרות שלכאורה כולם אומרים דבר אחד: להזהיר גדולים על הקטנים שלא יאכילו אותם דברים אסורים. \u0003דאי אשמעינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 רק את דין ה\u0003שקצים\u0004,"],["\u0003משום\u0004 ש\u0003איסורן במשהו,\u0004 שהשרץ, אם הוא בריה שלימה — אסור, ולוקים עליו אפילו הוא קטן מאוד (תוספות), \u0003אבל דם,\u0004 ש\u0003עד דאיכא\u0004 \u0005[שיש]\u0006 \u0003רביעית\u0004 אין בו איסור תורה, וכיון שאיסורו קל, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יזהירו עליו את הקטנים. \u0003ואי אשמעינן\u0004 \u0005[ואילו היה משמיע לנו]\u0006 רק \u0003דם\u0004 היינו אומרים: החמירו בו \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 באכילתו עונש \u0003כרת, אבל שרצים\u0004 שאין באכילתם עונש כרת \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא.\u0004","\u0003ואי אשמעינן הני תרתי\u0004 \u0005[ואילו היה משמיע לנו\u0006 רק \u0005את שני אלה],\u0006 היינו אומרים שהזהיר דווקא באלה \u0003משום\u0004 ש\u0003איסורן שוה בכל,\u0004 שהרי איסורים אלה חלים על כל אדם מישראל, \u0003אבל טומאה\u0004 שהיא מצוה לכהנים בלבד \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא. ואי אשמעינן\u0004 \u0005[ואילו היה משמיע לנו]\u0006 דין \u0003טומאה\u0004 בלבד, היינו אומרים: דיני \u0003כהנים שאני\u0004 \u0005[שונים]\u0006 וחמורים הם יותר, \u0003משום\u0004 ש\u0003ריבה בהן\u0004 הכתוב \u0003מצות יתרות\u0004 על אלה שחייבים בהם כל ישראל, \u0003אבל הני\u0004 \u0005[אלה],\u0006 שרצים ודם, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 הוזהרו בהם גדולים על הקטנים, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו כולם.","ומציעים עוד לפתור את בעיית קטן אוכל נבילות, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003שני אחין, אחד פקח ואחד חרש, נשואים שתי אחיות פקחות, מת\u0004 ה\u0003חרש\u0004 שהיה \u0003בעל פקחת\u0004, \u0003מה יעשה פקח בעל פקחת? — תצא\u0004 זו אשת החרש \u0003משום אחות אשה,\u0004 שהרי היא אחות אשתו.","\u0003מת פקח בעל פקחת\u0004, \u0003מה יעשה חרש בעל פקחת? — מוציא את אשתו בגט.\u0004 שהרי זיקת הייבום חלה עליו מן התורה ואילו נישואיו אינם אלא מדברי סופרים, וכיון שחלה עליו זיקת אחות אשתו, צריך לגרש את אשתו, \u0003ו\u0004אילו \u0003אשת אחיו אסורה לעולם\u0004 שאינו יכול לא לייבמה ולא לחלוץ לה.","ונברר: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מוציא את אשתו בגט? תיתיב גביה\u0004 \u0005[\u0006תמשיך ו\u0005תשב אצלו],\u0006 שהרי החרש בגדר \u0003קטן אוכל נבלות הוא,\u0004 שאינו בר־דעת ודינו לענין זה כקטן, ואם יבוא עליה, לא תיחשב זאת עבירה! ומשיבים: אילו היה הדבר תלוי רק בו, היה באמת כך, אבל כאן צריך להוציא אותה \u0003משום איסורא דידה\u0004 \u0005[האיסור שלה],\u0006 שהרי היא פיקחת, וכשם שהוא אסור בה, כך אסורה היא בו.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקום אחר, ששנינו: \u0003שני אחין פקחין נשואין שתי אחיות, אחת פקחת ואחת חרשת, מת פקח בעל חרשת\u0004, \u0003מה יעשה פקח בעל פקחת? — תצא\u0004 אותה חרשת \u0003משום אחות אשה. מת פקח בעל פקחת\u0004, \u0003מה יעשה פקח בעל חרשת? — מוציא את אשתו בגט,\u0004 שהרי זיקתה של אחות אשתו היא מן התורה, ואילו אשתו איננה נשואה לו אלא מדברי סופרים ולכן צריך לגרשה. \u0003ו\u0004יוציא את \u0003אשת אחיו בחליצה\u0004 (שהרי הוא פיקח ויכול לחלוץ לה).","ונברר: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 \u0003מוציא את אשתו בגט? תיתיב גביה\u0004 \u0005[תשב אצלו],\u0006 שהרי היא בגדר \u0003קטן אוכל נבלות הוא,\u0004 שאינה בת־דעת ולא חל עליה איסור! ומשיבים: האיסור הוא לא בגללה אלא \u0003משום איסורא דידיה\u0004 \u0005[האיסור שלו],\u0006 שהרי הוא פיקח ואסור בה.","\u0003אמר רבא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003שני אחין, אחד חרש ואחד פקח\u0004 שהיו \u0003נשואין לשתי אחיות, אחת פקחת ואחת חרשת. מת חרש בעל חרשת\u0004, \u0003מה יעשה פקח בעל פקחת? — תצא\u0004 החרשת \u0003משום אחות אשתו.\u0004 אם \u0003מת פקח בעל פקחת, מה יעשה חרש בעל חרשת? — מוציא את אשתו בגט, ואשת אחיו אסורה לעולם,\u0004 שהרי אינו יכול לא לייבם ולא לחלוץ.","\u0003והא הכא דלאו איסורא דידה איכא ולאו איסורא דידיה איכא\u0004 \u0005[והרי כאן שלא איסור שלה יש ולא איסור שלו יש]\u0006 שהרי שניהם חרשים ואינם נאסרים, \u0003וקתני\u0004 \u0005[ו\u0006מכל מקום \u0005שנה]:\u0006 \u0003מוציא את אשתו בגט! אמר רב שמעיה:\u0004 אפשר לומר שמקור האיסור הוא ב\u0003גזירה\u0004 שגזרו חכמים \u0003משום התרת יבמה לשוק.\u0004 שמצד עצמו היה יכול להשאיר את אשתו, אלא שיש לחשוש שיאמרו שהיא ממש אשתו לכל דבר, והיבמה הפיקחת מותרת לשוק משום אחות אשתו, משום כך אמרו שיוציא את אשתו בגט. ואם כן לא מצאנו ראיה גמורה לפתור את הבעיה בענין קטן אוכל נבילות.","","\u0003האשה שהלכה היא ובעלה למדינת הים\u0004 וכשהלכו לשם היה \u0003שלום בינו לבינה,\u0004 שלא היה ריב ביניהם, \u0003ו\u0004גם היה \u0003שלום בעולם,\u0004 שלא ידענו שיש מלחמה בעולם. \u0003ובאה\u0004 האשה לבדה למקום שממנו יצאו, \u0003ואמרה: \"מת בעלי\"\u0004 — הרי זה \u0003תנשא\u0004 על סמך עדות עצמה. וכיוצא בו, אם אמרה \u0003\"מת בעלי\"\u0004 ולא היו לו בנים, ולבעלה יש אח — \u0003תתייבם\u0004 על סמך עדותה. ואם היה \u0003שלום בינו לבינה\u0004 כשיצאו, אבל היתה \u0003מלחמה בעולם,\u0004 או שהיתה \u0003קטטה בינו לבינה ושלום בעולם, ובאתה\u0004 האשה \u0003ואמרה \"מת בעלי\" — אינה נאמנת,\u0004 שאנחנו חוששים שמא טעתה, או מטעה היא את החכמים. \u0003ר' יהודה אומר: לעולם אינה נאמנת\u0004 כשמעידה שמת בעלה, \u0003אלא אם כן באתה בוכה, ובגדיה קרועין,\u0004 שאז ניכר שאמת הדבר. \u0003אמרו לו:\u0004 אין לחלק בכך, אלא \u0003אחת זו\u0004 הבוכיה \u0003ואחת זו\u0004 שאינה בוכיה \u0003תנשא\u0004 בעדות עצמה.","","\u0003תנא\u0004 \u0005[שנה\u0006 במשנה\u0005]:\u0006 \u0003\"שלום בינו לבינה\" משום דקבעי למיתני\u0004 \u0005[שרצה לשנות]\u0006 בסוף: \u0003\"קטטה בינו לבינה\",\u0004 וכן \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003\"שלום בעולם\" משום דקבעי למיתני\u0004 \u0005[שרצה לשנות]\u0006 אחר כך: \u0003\"מלחמה בעולם\",\u0004 ולכן הדגיש את הדברים בצורה זו.","\u0003אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שכשהיתה \u0003מלחמה\u0004 אין סומכים על עדותה — \u0003משום דאמרה בדדמי\u0004 \u0005[שאומרת\u0006 מה \u0005שנידמה\u0006 לה\u0005],\u0006 שהיא אומרת בליבה: \u0003סלקא דעתא\u0004 \u0005[יעלה על הדעת]\u0006 ש\u0003בכל הני דאיקטול\u0004 \u0005[אלה שנהרגו],\u0006 \u0003הוא,\u0004 בעלי בלבד, \u0003פליט\u0004 \u0005[נמלט]?\u0006 \u0003אם תימצא לומר\u0004 בכל זאת, \u0003כיון\u0004 ש\u0003שלום בינו לבינה נטרא\u0004 \u0005[שומרת,\u0006 מחכה\u0005]\u0006 \u0003עד דחזיא\u0004 \u0005[שרואה]\u0006 ממש שמת, בכל זאת \u0003זימנין דמחו ליה בגירא\u0004 \u0005[פעמים שמכים אותו בחץ]\u0006 \u0003או ברומחא\u0004 \u0005[ברומח]\u0006 \u0003וסברא\u0004 \u0005[\u0006והיא \u0005סבורה]\u0006 ש\u0003ודאי מת\u0004 מחמת המכה, \u0003ו\u0004באמת אין זו הוכחה, שכן \u0003איכא דעבד סמתרי\u0004 \u0005[יש\u0006 מקרים \u0005שעושה\u0006 מישהו \u0005תרופה\u0006 לנפגע\u0005]\u0006 \u0003וחיה\u0004 (מתרפא) על אף המכה.","\u0003סבר רבא למימר\u0004 \u0005[לומר]\u0006 ש\u0003רעבון\u0004 (רעב) \u0003אינו כמלחמה, דלא אמרה בדדמי\u0004 \u0005[שאינה אומרת ב\u0006מה \u0005שנדמה\u0006 לה\u0005].\u0006 \u0003הדר\u0004 \u0005[חזר]\u0006 בו אחר כך ו\u0003אמר רבא: רעבון הרי הוא כמלחמה.\u0004 ומה טעם חזר בו — \u0003דההיא דאתת לקמיה\u0004 \u0005[ש\u0006אשה \u0005אחת באה לפני]\u0006 \u0003רבא, אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003\"בעלי מת ברעב\".\u0004 ורצה רבא לחוקרה, \u0003אמר לה: שפיר עבדת דשיזבת נפשיך\u0004 \u0005[\u0006וכי \u0005יפה עשית שהצלת את עצמך\u0006 וברחת\u0005]\u0006 והשארת אותו שימות? \u0003סלקא דעתך דבההוא פורתא דנפפיתא דשבקת ליה הוה חיי\u0004 \u0005[\u0006וכי \u0005עולה על דעתך שבאותו מעט קמח מנופה שהשארת לו\u0006 יכול \u0005היה לחיות]?\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003מר נמי ידע דכי האי גוונא\u0004 \u0005[אדוני גם כן יודע שבמקרה כזה]\u0006 \u0003לא חיי\u0004 \u0005[\u0006יכול היה \u0005לחיות]\u0006 והבין רבא מתוך הדברים הללו שבאמת לא ראתה שמת בעלה, שראתה אותו כשהוא חלוש מחמת הרעב, והיא העידה בוודאות שמת. \u0003הדר\u0004 \u0005[חזר]\u0006 בו שוב ו\u0003אמר רבא:\u0004 כשיש \u0003רעבון\u0004 בעולם הרי זה \u0003גריעא\u0004 \u0005[גרוע]\u0006 \u0003ממלחמה\u0004 לענין זה. ש\u0003אילו\u0004 בעת \u0003מלחמה, כי אמרה\u0004 \u0005[כאשר אומרת]:\u0006 \u0003\"מת בעלי במלחמה\" הוא דלא מהימנא\u0004 \u0005[שאיננה נאמנת],\u0006 אבל גם בעת מלחמה, \u0003הא\u0004 \u0005[הרי]\u0006 אם אמרה \u0003\"מת על מטתו\"\u0004 מסיבה אחרת — \u0003מהימנא\u0004 \u0005[נאמנת],\u0006 שהרי כאן אינה טועה. \u0003ואילו גבי רעבון\u0004 אינה נאמנת \u0003עד\u0004 ש\u0003אמרה \"מת וקברתיו\",\u0004 שאז ברור שמעידה על מותו, ולא במה שנדמה לה.","","וכן \u0003מפולת הרי הוא כמלחמה, דאמרה בדדמי\u0004 \u0005[שאומרת ב\u0006מה \u0005שנדמה\u0006 לה\u0005]\u0006 ואינה מדקדקת לבדוק שמא ניצל. וכן \u0003שילוח נחשים ועקרבים\u0004 שהתנפלו עליהם — \u0003הרי הן כמלחמה, דאמרה בדדמי\u0004 \u0005[שאומרת ב\u0006מה \u0005שנדמה\u0006 לה\u0005].\u0006","אם היה \u0003דבר\u0004 (או מגיפה דומה) — \u0003אמרי לה\u0004 \u0005[יש אומרים]\u0006 \u0003הרי הוא כמלחמה, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אינו כמלחמה.\u0004 ומסבירים: \u0003אמרי לה\u0004 \u0005[יש אומרים]\u0006 ש\u0003הרי הוא כמלחמה,\u0004 ומדוע \u0003— דאמרי בדדמי\u0004 \u0005[שאומרת ב\u0006מה \u0005שנדמה\u0006 לה\u0005],\u0006 משום שחושבת שאם כולם מתו במגיפה, לא ייתכן שבעלה נשאר חי. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אינו כמלחמה,\u0004 ומדוע — \u0003דסמכי אדאמרי אינשי\u0004 \u0005[שסומכים על מה שאומרים אנשים\u0006 בפתגם מקובל\u0005]:\u0006 \u0003שב שנין הוה מותנא\u0004 \u0005[שבע שנים היה דבר]\u0006 \u0003ואינש\u0004 \u0005[ואדם]\u0006 \u0003בלא שני\u0004 \u0005[שנותיו]\u0006 \u0003לא אזיל\u0004 \u0005[הלך,\u0006 מת\u0005],\u0006 שבדבר שהוא בידי שמים, יודעים אנשים שפעמים אין אדם נפגע כלל במגיפה, ואם מעידה האשה שמת, ודאי ראתה בבירור שמת.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003החזיקה היא מלחמה בעולם מהו?\u0004 כלומר, אם לא ידענו שהיתה מלחמה באותו מקום, אלא שבאה האשה ורק מפיה נודע לנו שהיתה מלחמה, והוסיפה ואמרה שמת בעלה במלחמה זו — \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 במקרה זה \u0003מה לה לשקר,\u0004 שכיון שהיא עצמה סיפרה שהיתה מלחמה ושמת בעלה אין מקום לחשוד בה שמשקרת,"],["\u0003דאי בעיא אמרה\u0004 \u0005[שאם\u0006 היתה \u0005רוצה\u0006 לשקר \u0005היתה אומרת]:\u0006 \u0003\"שלום\u0004 היה \u0003בעולם\",\u0004 והיו מקבלים את עדותה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דאיחזקה\u0004 \u0005[ש\u0006כבר \u0005החזיקה]\u0006 מלחמה ואנו סומכים עליה בכך — לענין בעלה \u0003אמרה בדדמי\u0004 \u0005[\u0006היא \u0005אומרת ב\u0006מה \u0005שנדמה\u0006 לה\u0005],\u0006 \u0003ולא אתי\u0004 \u0005[בא]\u0006 הנימוק של \u0003\"מה לי לשקר\" ומרע,\u0004 מקלקל \u0003חזקתיה\u0004 \u0005[\u0006את \u0005החזקה]\u0006 של מלחמה.","ומנסים להביא ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ראיה ממה ששנינו, באה אשה ואמרה: \u0003\"עישינו עלינו\u0004 את ה\u0003בית\u0004 לאחר שהציתוהו\u0003\",\u0004 או ש\u0003\"עישינו\u0004 (עישנו) \u0003עלינו מערה\",\u0004 וכתוצאה מכך \u0003\"הוא,\u0004 בעלי, \u0003מת ואני נצלתי\" — אינה נאמנת.\u0004 והרי היא עצמה מספרת את המעשה כולו, ובכל זאת אין מאמינים לה! ומשיבים: משם אין ראיה, כי \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003דאמר\u0004 \u0005[שאומרים]\u0006 \u0003לה\u0004 שאי אפשר לסמוך על עדותה, \u0003כי היכי דלדידך איתרחיש ניסא לדידיה נמי איתרחיש ניסא\u0004 \u0005[שכמו שלך אירע נס\u0006 וניצלת, אולי \u0005גם לו,\u0006 לבעלך, \u0005אירע נס]\u0006 ואולי אף הוא עדיין חי.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מברייתא אחרת, באה אשה ואמרה: \u0003\"נפלו\u0004 (התנפלו) \u0003עלינו גוים\",\u0004 או \u0003\"נפלו עלינו ליסטים\"\u0004 להורגנו, \u0003\"הוא מת, ו\u0004אני \u0003נצלתי\" — נאמנת.\u0004 משמע, שאנו סומכים על עדותה מהנימוק של \"מה לי לשקר\"! ודוחים: אין זו ראיה, כי \u0003התם\u0004 \u0005[שם]\u0006 מסתברת עדותה, ו\u0003כ\u0004פי שאמר \u0003רב אידי.\u0004 ש\u0003אמר רב אידי: אשה כלי זיינה עליה,\u0004 כלומר, אשה בדרך כלל איננה נהרגת על ידי ליסטים, כי עצם היותה אשה מגינה עליה, ולכל היותר היו אונסים אותה ולא הורגים, ולכן יש מקום להניח שאמת היה הדבר.","מסופר: \u0003ההוא גברא דבשילהי הלוליה איתלי נורא בי גנני\u0004 \u0005[אדם אחד שבסוף\u0006 (גמר) \u0005חתונתו נתפסה,\u0006 פרצה, \u0005אש\u0006 ב\u0005בית החופה\u0006 בו מצויים החתן והכלה\u0005],\u0006 \u0003אמרה להו דביתהו\u0004 \u0005[אמרה להם אשתו]\u0006 וצעקה: \u0003\"חזו גבראי, חזו גבראי\u0004 \u0005[ראו\u0006 את \u0005בעלי, ראו\u0006 את \u0005בעלי]\u0006 \u0003\", אתו, חזו גברא חרוכא דשדי, ופסתא דידא דשדיא\u0004 \u0005[באו, ראו איש חרוך\u0006 שלא היה ניכר מי הוא \u0005ש\u0006היה \u0005מוטל, ופיסת היד שמוטלת].\u0006","\u0003סבר רב חייא בר אבין למימר\u0004 \u0005[לומר]:\u0006 \u0003היינו\u0004 הוא המקרה של \u0003\"עישינו עלינו בית\", \"עישינו עלינו מערה\",\u0004 ואין לסמוך עליה שמת. \u0003אמר רבא: מי דמי\u0004 \u0005[האם דומה\u0006 הדבר\u0005]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 הרי \u0003לא קאמרה\u0004 \u0005[אמרה]\u0006 \u0003\"חזו גבראי חזו גבראי\u0004 \u0005[ראו\u0006 את \u0005בעלי, ראו\u0006 את \u0005בעלי]\u0006 \u0003\". ועוד, גברא חרוכא דשדי ופסתא דידא דשדיא\u0004 \u0005[ועוד\u0006 הבדל יש: כאן הרי \u0005איש חרוך שמוטל, ופיסת יד שמוטלת],\u0006 ויש איפוא סיוע לדבריה,","\u0003ורב חייא בר אבין\u0004 מדוע לא קיבל את העדות — לדעתו, \u0003גברא חרוכא דשדיא\u0004 \u0005[גבר חרוך שמוטל]\u0006 איננה ראיה, כי \u0003אימא איניש אחרינא אתא לאצולי, ואכילתיה נורא\u0004 \u0005[\u0006יש לחשוש \u0005ולומר\u0006 שמא \u0005אדם אחר בא להציל ושרפתו האש],\u0006 \u0003ופסתא דידא דשדיא\u0004 \u0005[ופיסת היד שמוטלת]\u0006 שם — שמא \u0003נורא איתליא ואתיליד ביה מומא ומחמת כיסופא אזל וערק לעלמא\u0004 \u0005[האש נתפסה\u0006 בו \u0005ונולד בו מום\u0006 שנקטעה ידו \u0005ומחמת הבושה הלך וברח לעולם]\u0006 ועדיין חי הוא, ולכן לא רצה לסמוך על העדות.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005],\u0006 שאלה זו: \u0003עד אחד\u0004 המעיד על מות אדם \u0003במלחמה מהו\u0004? וצדדי השאלה: \u0003טעמא\u0004 \u0005[הטעם]\u0006 ש\u0003עד אחד מהימן\u0004 \u0005[נאמן]\u0006 בעדות אשה — \u0003משום דמילתא דעבידא לאיגלויי\u0004 \u0005[שדבר העשוי להתגלות]\u0006 אם חי \u0003הוא,\u0004 ובדבר שכזה \u0003לא משקר\u0004 אדם, \u0003הכא נמי לא\u0004 \u0005[כאן גם כן אינו]\u0006 \u0003משקר, או דלמא\u0004 \u0005[שמא]\u0006 \u0003טעמא\u0004 \u0005[הטעם]\u0006 שמתירים על פי \u0003עד אחד — משום דהיא גופא דייקא ומינסבא\u0004 \u0005[שהיא עצמה מדייקת,\u0006 בודקת את העדות היטב \u0005ו\u0006רק אז \u0005נישאת],\u0006 \u0003והכא\u0004 \u0005[וכאן],\u0006 \u0003כיון דזימנין דסניא ליה\u0004 \u0005[שלפעמים ש\u0006היא \u0005שונאת אותו],\u0006 \u0003לא דייקא ומינסבא\u0004 \u0005[אינה מדייקת\u0006 בדברים \u0005ונישאת],\u0006 תוך הנחה שודאי מת במלחמה.","\u0003אמר רמי בר חמא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה, ממה ששנינו, \u0003אמר ר' עקיבא: כשירדתי לנהרדעא\u0004 שבבבל \u0003לעבר\u0004 את \u0003השנה, מצאתי\u0004 שם את החכם \u0003נחמיה איש בית דלי, ואמר לי: שמעתי שאין\u0004 חכמים \u0003משיאין את האשה בארץ ישראל על פי\u0004 עדות \u0003עד אחד, אלא\u0004 רק \u0003ר' יהודה בן בבא,\u0004 ושאר החכמים מפקפקים לסמוך על דעתו. \u0003ונמתי\u0004 (ואמרתי) \u0003לו:\u0004 אכן \u0003כן הדברים. אמר לי: אמור להם משמי: אתם יודעים\u0004 ש\u0003המדינה הזו משובשת בגייסות? כך מקובלני מרבן גמליאל הזקן שמשיאין האשה על פי עד אחד.\u0004","ונברר את הברייתא הזו לענייננו: לצורך \u0003מאי\u0004 \u0005[מה]\u0006 אמר \u0003מדינה\u0004 זו \u0003משובשת בגייסות? לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 כוונתו לומר: \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003מדינה זו משובשת\u0004 ויש בה מלחמה, \u0003כך מקובלני שמשיאין על פי עד אחד. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003עד אחד מהימן\u0004 \u0005[נאמן]\u0006 בעדות אשה במלחמה.","\u0003אמר רבא: אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 שאמר \u0003\"מדינה זו\"? — \"כל מקום שיש גייסות\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 \u0003אלא אמר רבא: הכי קאמר\u0004 \u0005[כך אמר]\u0006 נחמיה איש בית דלי: \u0003אתם יודעים שמדינה זו משובשת בגייסות, ולא אפשר ליה למשבק אינשי ביתי ומייתי קמי רבנן\u0004 \u0005[ואי אפשר לו,\u0006 לי, \u0005לעזוב\u0006 את \u0005אנשי ביתי ולבוא לפני חכמים]\u0006 מפני הסכנה, ולכן איני יכול לבוא ולהעיד בעצמי לפני החכמים ש\u0003כך מקובלני מרבן גמליאל שמשיאין האשה על פי עד אחד.\u0004 ואם כן, אין פתרון לבעייתנו.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקום אחר, \u0003מעשה בשני תלמידי חכמים שהיו באין עם אבא יוסי בן סימאי בספינה, וטבעה\u0004 אותה ספינה, \u0003והשיא רבי\u0004 את \u0003נשותיהן על פי נשים\u0004 שהעידו על כך. \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מים כמלחמה דמו\u0004 \u0005[נחשבים]\u0006 לענין זה, שיש מקום להשערות ולטעות, \u0003ונשים, אפילו\u0004 הן \u0003מאה — כעד אחד דמו\u0004 \u0005[\u0006הן \u0005נחשבות]\u0006 לענין עדותן על מות הבעל, \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003השיא,\u0004 משמע שסומכים על עד אחד אפילו במלחמה!","את ההוכחה הזאת דוחים: \u0003ותסברא\u0004 \u0005[ו\u0006כי \u0005סבור אתה]\u0006 שיש מכאן ראיה? אם כפי שאתה מפרש הנשים העידו רק שטבעה הספינה, הלא \u0003מים שאין להם סוף נינהו\u0004 \u0005[הם],\u0006 שהספינה שטבעה בים, טבעה במקום שאי אפשר היה לראות את החוף, \u0003ו\u0004כלל הוא כי מי שטבע ב\u0003מים שאין להם סוף — אשתו אסורה,\u0004 שאין הוכחה שאכן טבע, ולא יצא בצד אחר. \u0003אלא\u0004 חייבים לומר, \u0003היכי דמי\u0004 \u0005[כיצד\u0006 היה \u0005בדיוק הדבר],\u0006 \u0003דאמרי\u0004 \u0005[שאמרו]\u0006 אותן הנשים: \u0003אסקינהו קמן\u0004 \u0005[העלו\u0006 את הטבועים \u0005לפנינו]\u0006"],["\u0003וחזינהו לאלתר\u0004 \u0005[וראינו אותם מיד]\u0006 כשהעלום, \u0003וקאמרי סימנין\u0004 \u0005[ואמרו\u0006 הנשים \u0005סימנים]\u0006 שהיו באנשים אלה, \u0003דלאו עלייהו סמכינן\u0004 \u0005[ש\u0006באופן כזה \u0005לא עליהן אנו סומכים],\u0006 \u0003אלא\u0004 על ה\u0003סימנים.\u0004","מסופר: \u0003ההוא גברא דאפקיד שומשמי גבי חבריה\u0004 \u0005[אדם אחד שהפקיד שומשומים אצל חבירו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לאחר זמן: \u0003הב ליה שומשמי\u0004 \u0005[תן לו,\u0006 לי, את ה\u0005שומשומים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שקילתינהו\u0004 \u0005[לקחת אותם].\u0006 אמר לו המפקיד: \u0003והא כן וכן הויין\u0004 \u0005[והרי כך וכך\u0006 בכמות \u0005היו],\u0006 \u0003ובחביתא רמיין\u0004 \u0005[ובחבית\u0006 הם \u0005מונחים]\u0006 וצא ובדוק, וראה שכך הוא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 השומר: \u0003דידך\u0004 \u0005[\u0006את השומשומים \u0005שלך] —\u0006 \u0003שקלתינהו\u0004 \u0005[לקחת אותם],\u0006 \u0003והני\u0004 \u0005[ואלה]\u0006 הנמצאים בחבית אצלי — \u0003אחריני נינהו\u0004 \u0005[אחרים הם].\u0006 ובא הדבר לפני חכמים, לשאול מה הדין.","\u0003סבר רב חסדא למימר\u0004 \u0005[לומר]:\u0006 \u0003היינו\u0004 \u0005[זה הוא]\u0006 מקרה הדומה למקרה למעלה ב\u0003שני תלמידי חכמים\u0004 שטבעו, ואמרו עליהם סימנים, \u0003ולא אמרינן\u0004 \u0005[ואין אנו אומרים]:\u0006 \u0003הנך אזלו לעלמא, והני אחריני נינהו\u0004 \u0005[אלה הלכו\u0006 להם \u0005לעולם, ואלה\u0006 שצפו ועלו \u0005אחרים הם],\u0006 וגם כאן, אפשר לסמוך על הסימנים שנתן המפקיד, ואין לומר ששומשומים אלה אחרים הם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מי דמי\u0004 \u0005[האם דומה]\u0006 הדבר? \u0003התם קאמרי\u0004 \u0005[שם אומרים\u0006 \u0005הם]\u0006 \u0003סימנים\u0004 על האנשים, \u0003הכא שומשמי מאי סימנא אית להו\u0004 \u0005[כאן,\u0006 ל\u0005שומשומים\u0006 עצמם \u0005מה,\u0006 איזה, \u0005סימן יש להם\u0006 בגופם\u0005]?\u0006 \u0003ודקאמר \"כן וכן הויין\"\u0004 \u0005[ו\u0006מה \u0005שאמר \"כך וכך היו\"\u0006 בכמות\u0005]\u0006 — \u0003אימר חושבנא איתרמי\u0004 \u0005[אמור\u0006 ש\u0005חשבון הזדמן]\u0006 ובמקרה הזדמן שהיתה כמות כזו גם בפעם שניה, ואין הוכחה שבאמת אותם שומשומים שלו הם.","בהמשך לאותו דיון, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר קשישא\u0004 \u0005[הזקן]\u0006 \u0003בר\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא לרב אשי: ומי חיישינן\u0004 \u0005[והאם חוששים אנו]\u0006 בדברים האלה \u0003שמא פינן\u0004 (פינה אותם ממקומם)? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003מצא כלי וכתוב עליו קו\"ף\u0004 — יש לומר שכל הנמצא בכלי, כגון כסף, היה מיועד לצורך \u0003קרבן,\u0004 היה רשום עליו \u0003מ\"ם\u0004 — הרי הוא \u0003מעשר, דל\"ת\u0004 — הוא \u0003דמוע,\u0004 תערובת של תרומה בחולין, \u0003טי\"ת\u0004 — הרי הוא \u0003טבל, תי\"ו — תרומה. שבשעת הסכנה\u0004 שגזרו גזירות שמד על ישראל \u0003היו כותבין תי\"ו תחת\u0004 (במקום) \u0003תרומה,\u0004 ולא כתבו במפורש, ואין חוששים שמא פינו את התרומה מהכלי למקום אחר!","כנגד טענה זו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: ולא חיישינן\u0004 \u0005[ו\u0006האם \u0005אין אנו חוששים]\u0006 \u0003שמא פינן? — אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של אותה משנה, \u0003ר' יוסי אומר: אפילו מצא חבית וכתוב עליה\u0004 במפורש \u0003תרומה — הרי אלו חולין, שאני אומר: אשתקד\u0004 (בשנה שעברה) \u0003הוה\u0004 \u0005[היה]\u0006 \u0003מלא תרומה, ופינה\u0004 את התרומה והכניס דבר שאיננו תרומה, הרי מכאן ראיה שאנו כן חוששים!","\u0003אלא\u0004 כך יש לומר: \u0003דכולי עלמא חיישינן\u0004 \u0005[לדעת הכל חוששים אנו]\u0006 \u0003שמא פינן, והכא בהא קמיפלגי\u0004 \u0005[וכאן,\u0006 באותם כלים, \u0005בזה הם חלוקים]:\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 חכמים\u0005]\u0006 \u0003סבר: אם איתא\u0004 \u0005[יש],\u0006 אם אמנם, \u0003דפינהו\u0004 \u0005[שפינה\u0006 את התרומה\u0005] —\u0006 \u0003מיכפר הוה כפר\u0004 \u0005[היה מוחק\u0006 את הכתובת\u0005].\u0006 \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יוסי\u0005],\u0006 סבור: \u0003אימר אישתלויי אישתלי\u0004 \u0005[אמור ששכח]\u0006 לעשות כך. \u0003אי נמי, לפנחיא שבקיה\u0004 \u0005[או גם כן\u0006 טעם אחר — \u0005להצלה הניח\u0006 את הכתובת\u0005]\u0006 שלא יבואו בני אדם לקחת את מה שיש בכלי, כי יחשבו שתרומה היא.","אגב השאלות הללו בדיני התרת אשה מספרים: \u0003יצחק ריש גלותא\u0004 \u0005[ראש הגולה],\u0006 \u0003בר אחתיה\u0004 \u0005[בן אחותו]\u0006 של \u0003רב ביבי, הוה קאזיל\u0004 \u0005[היה הולך]\u0006 \u0003מקרטבא לאספמיא\u0004 \u0005[לספרד],\u0006 \u0003ושכיב\u0004 \u0005[ומת]\u0006 בדרך. \u0003שלחו מהתם\u0004 \u0005[משם,\u0006 מספרד\u0005]\u0006 הודעה זו: \u0003יצחק ריש גלותא\u0004 \u0005[ראש הגולה],\u0006 \u0003בר אחתיה\u0004 \u0005[בן אחותו]\u0006 של \u0003רב ביבי, הוה קאזיל\u0004 \u0005[היה הולך]\u0006 \u0003מקרטבא לאספמיא\u0004 \u0005[לספרד]\u0006 \u0003ושכיב\u0004 \u0005[ומת].\u0006 והתעוררה השאלה: \u0003מי חיישינן לתרי\u0004 \u0005[האם חוששים אנחנו לשני]\u0006 \u0003יצחק, או לא?\u0004 כלומר, שמא יש עוד אדם אחר בשם זה, ואין בזהות שמותיהם משום סימנים מובהקים. \u0003אביי אמר: חיישינן\u0004 \u0005[חוששים אנו].\u0006 \u0003רבא אמר: לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006","\u0003אמר אביי: מנא אמינא לה\u0004 \u0005[מניין אומר אני אותה]\u0006 סברה שחוששים לכך, \u0003דההוא גיטא דאשתכח\u0004 \u0005[שגט אחד נמצא]\u0006 \u0003ב\u0004עיר \u0003נהרדעא וכתיב\u0004 \u0005[ו\u0006היה \u0005כתוב\u0006 בו\u0005]:\u0006 \u0003בצד קלוניא מתא\u0004 \u0005[העיר]\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003אנדרולינאי\u0004 איש \u0003נהרדעא פטרית ותרכית ית\u0004 \u0005[פטרתי ושלחתי\u0006 וגרשתי \u0005את]\u0006 \u0003פלונית אנתתי\u0004 \u0005[אשתי],\u0006 ואשת אנדרולינאי ביקשה שיתירו לה להינשא על פי גט זה, ולא ידעו אם הוא האיש שנתן את הגט, או שמא יש אדם אחר בשם זה. \u0003ושלחה,\u0004 את השאלה הזו, \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל לקמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יהודה נשיאה\u0004 \u0005[הנשיא]\u0006 לארץ ישראל לדעת מה ההלכה. \u0003ושלח ליה\u0004 \u0005[לו]:\u0006 \u0003תיבדק נהרדעא כולה\u0004 אם יש אדם נוסף בשם זה. משמע שחוששים שמא יש אדם נוסף בשם זה, וכן צריך לעשות במעשה של אותו יצחק.","\u0003ורבא אמר:\u0004 אין להביא מכאן ראיה, שכן \u0003אם איתא\u0004 \u0005[יש\u0006 מקום\u0005]\u0006 לחשוש שזה שכתב את הגט, אחר הוא, וחוששים לאדם נוסף באותו שם — \u0003יבדק כל העולם מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר, שמא יש בעולם אדם אחר שנקרא באותו שם?! \u0003אלא\u0004 באמת לא היה מקום לחשוש כלל, ומדוע שלח לו שתיבדק נהרדעא — \u0003משום כבודו דאבוה\u0004 \u0005[של אביו]\u0006 של \u0003שמואל הוא\u0004 ש\u0003שלח הכי\u0004 \u0005[כך],\u0006 שלא רצה לכתוב במפורש ששאל דבר שאינו צריך, ולכן כתב באופן הנשמע כאילו הוא מסכים במקצת לחשש זה.","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מניין אומר אני אותה,\u0006 את דעתי\u0005]\u0006 שאין חוששים לשניים ששמותיהם שווים — \u0003דהנהו תרי שטרי דנפקי\u0004 \u0005[שאותם שני שטרות שיצאו]\u0006 \u0003ב\u0004עיר \u0003מחוזא וכתיב בהו\u0004 \u0005[ו\u0006היו \u0005כתובים בהם]\u0006 השמות: \u0003חבי בר ננאי וננאי בר חבי. ואגבי בהו\u0004 \u0005[והגבה בהם]\u0006 \u0003רבא בר אבוה זוזי\u0004 \u0005[זוזים,\u0006 כספים\u0005]\u0006 ולא חשש שמא של אחרים הם. \u0003והא\u0004 \u0005[והרי]\u0006 השמות \u0003חבי בר ננאי וננאי בר חבי ב\u0004עיר \u0003מחוזא שכיחי טובא\u0004 \u0005[מצויים הרבה],\u0006 ובוודאי יש אנשים אחרים בעלי שם זה, ובכל זאת אין אנו חוששים לכך. ושואלים: \u0003ואביי,\u0004 מה משיב הוא על הוכחה זו?"],["\u0003למאי ניחוש\u0004 \u0005[למה נחשוש]\u0006 \u0003לה\u0004 במקרה של שטר? \u0003אי\u0004 \u0005[אם]\u0006 נחשוש \u0003לנפילה,\u0004 שמא נפל השטר מיד בעליו וזה מצאו — \u0003מזהר זהיר ביה\u0004 \u0005[זהיר\u0006 הוא \u0005בו]\u0006 שלא לאבדו, שיודע שיש בעיר אחרים ששמם כשמו. ו\u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 נחשוש \u0003לפקדון,\u0004 שמא מסרו לו — \u0003כיון דשמיה כשמיה\u0004 \u0005[ששמו כשמו\u0006 של המחזיק בפיקדון \u0003לא מפקיד גביה\u0004 \u0005[יפקיד אצלו\u0006 שטר\u0005]\u0006 בלי להבטיח את עצמו.","\u0003מאי אמרת\u0004 \u0005[מה\u0006 יכול \u0005אתה לומר],\u0006 שיש לחשוש \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003מסר ליה\u0004 \u0005[לו]\u0006 לזה, ששמו כשמו, את השטר, שנתנו או מכרו לו שיגבנו לעצמו, אולם אז יפה עושה המחזיק שגובה בשטר, כי \u0003אותיות\u0004 (שטרות) \u0003נקנות במסירה\u0004 בלבד, ואין צורך בקנין נוסף, והשטר הוא באמת בבעלותו של זה שהוציא אותו, למרות שלא נכתב עבורו מתחילה. ואם כן מכאן אין להביא ראיה.","מסופר: \u0003ההוא גיטא דאשתכח\u0004 \u0005[גט אחד שנמצא]\u0006 \u0003ב\u0004עיר \u0003סורא וכתיב ביה הכי\u0004 \u0005[ו\u0006היה \u0005כתוב בו כך]:\u0006 \u0003\"בסורא מתא\u0004 \u0005[העיר]\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003ענן בר חייא\u0004 איש \u0003נהרדעא פטרית ותרכית\u0004 \u0005[פטרתי ושלחתי]\u0006 וגירשתי את \u0003פלונית אנתתי\u0004 \u0005[אשתי]\u0006 \u0003\", ובדקו רבנן\u0004 \u0005[חכמים]\u0006 \u0003מסורא ועד נהרדעא\u0004 כמעט בכל בבל, \u0003ולא הוה\u0004 \u0005[היה]\u0006 \u0003ענן בר חייא אחרינא\u0004 \u0005[אחר],\u0006 \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מענן בר חייא מחגרא דהוה\u0004 \u0005[שהיה]\u0006 \u0003בנהרדעא, ואתו סהדי ואמור דההוא יומא כי איכתב ההוא גיטא\u0004 \u0005[ובאו עדים ואמרו ש\u0006ב\u0005אותו יום כאשר נכתב אותו גט]\u0006 \u0003ענן בר חייא מחגרא גבן הוה\u0004 \u0005[אצלנו היה]\u0006 בנהרדעא ולא בסורא.","\u0003אמר אביי: אף לדידי דאמינא חיישינן\u0004 \u0005[לשיטתי שאני אומר\u0006 שבדרך כלל \u0005חוששים אנו\u0006 לאיש אחר\u0005]\u0006 — \u0003הכא לא חיישינן\u0004 \u0005[כאן אין אנו חוששים],\u0006 \u0003דהא קאמרי סהדי\u0004 \u0005[שהרי אומרים עדים]\u0006 ש\u0003בנהרדעא הוה\u0004 \u0005[היה],\u0006 \u0003מאי בעא\u0004 \u0005[\u0006ו\u0005מה\u0006 הוא \u0005מבקש,\u0006 עושה\u0005]\u0006 \u0003בסורא,\u0004 ואם כן אין לחשוש כלל שהאיש האחר הוא שכתב את הגט.","\u0003אמר רבא: אף לדידי דלא חיישינן\u0004 \u0005[לשיטתי שאין אנו חוששים]\u0006 — \u0003הכא\u0004 \u0005[כאן]\u0006 שנודע שיש עוד אחד באותו שם, \u0003חיישינן\u0004 \u0005[אנו חוששים]\u0006 \u0003דלמא בגמלא פרחא אזל\u0004 \u0005[שמא בגמל פורח,\u0006 מהיר מאוד, \u0005הלך]\u0006 והגיע מנהרדעא לסורא באותו יום. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003בקפיצה\u0004 (קפיצת הדרך), בדרך נס, הגיע. \u0003אי נמי מילי\u0004 \u0005[או גם כן\u0006 ש\u0005דברים,\u0006 שליחות\u0005]\u0006 \u0003מסר\u0004 וכתבו את השטר במקום שהוא לא היה בו.","\u0003כדאמר להו\u0004 \u0005[כ\u0006מו \u0005שאמר להם]\u0006 \u0003רב לספרי\u0004 \u0005[לסופרי\u0006 בית הדין\u0005],\u0006 \u0003וכן אמר להו\u0004 \u0005[להם]\u0006 \u0003רב הונא לספרי\u0004 \u0005[לסופרים]:\u0006 \u0003כי איתנכו\u0004 \u0005[כאשר אתם נמצאים]\u0006 \u0003ב\u0004מקום ששמו \u0003שילי כתובו\u0004 \u0005[כתבו]\u0006 שהשטר נכתב \u0003בשילי,\u0004 ו\u0003אף על גב דמימסרן מילי\u0004 \u0005[\u0006ו\u0005אף על פי שנמסרו\u0006 לכם \u0005הדברים]\u0006 \u0003בהיני. ו\u0004כן \u0003כי איתנכו\u0004 \u0005[כאשר אתם נמצאים]\u0006 \u0003ב\u0004מקום ששמו \u0003היני כתובו\u0004 \u0005[כתבו]\u0006 שהשטר נכתב \u0003בהיני, אף על גב דמימסרן מילי\u0004 \u0005[אף על פי שנמסרו הדברים]\u0006 \u0003בשילי.\u0004","אף שאלה ראשונה ששאלנו לא נפתרה, ושואלים: \u0003מאי הוה עלייהו דשומשמי\u0004 \u0005[מה היה עליהם על השומשומים],\u0006 האם אנחנו אומרים שהם שייכים למפקיד או שאומרים שאולי הכניס שומר הפקדון שומשומים אחרים באותה חבית ואת השומשומים האחרים החזיר למפקיד? \u0003רב יימר אמר: לא חיישינן\u0004 \u0005[אין אנו חוששים]\u0006 שמא אחרים הם. \u0003רבינא אמר: חיישינן\u0004 \u0005[חוששים אנו]\u0006 שמא אחרים הם. ומסכמים, \u0003והלכתא\u0004 \u0005[והלכה]:\u0006 \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 שהוציא אותם, ואין אנו סומכים על הסימנים שנתן התובע.","שנינו במשנה שאם מעידה על מות בעלה לאחר שהיתה \u0003קטטה בינו לבינה\u0004 — אין סומכים על עדותה. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 זה \u0005בדיוק]\u0006 מצב של \u0003קטטה בינו לבינה? אמר רב יהודה אמר שמואל: ב\u0004מקרה ששמעו אנשים ש\u0003אומרת לבעלה \"גרשיני\".\u0004 ותוהים: וכי זו ראיה? \u0003כולהו נמי אמרו הכי\u0004 \u0005[\u0006כל הנשים \u0005כולן\u0006 כשכועסות \u0005גם כן אומרות כך],\u0006 ואין זו ראיה שהיתה קטטה כזו שאין אחריה השלמה. \u0003אלא\u0004 יש לומר שמצב של קטטה הוא \u0003באומרת לבעלה \"גירשתני\",\u0004 שטוענת שהיא גרושה.","ושואלים: אם אמרה \"גרשתני\" — \u0003וליהמנה\u0004 \u0005[ושנאמין לה]\u0006 \u0003מ\u0004כח דברי \u0003רב המנונא.\u0004 ש\u0003אמר רב המנונא: אשה שאמרה לבעלה \"גירשתני\" — נאמנת,\u0004 ומדוע? — \u0003חזקה אין אשה מעיזה פניה בפני בעלה\u0004 לשקר בדבר שהוא יודע שאינו כך, ואם כן, מדוע אין אנו סומכים עליה לומר שהיא גרושה, ואין צריכים עוד לעדות שמת!","ומשיבים: \u0003באומרת \"גירשתני בפני פלוני ופלוני\"\u0004 והם היו העדים, \u0003ושאילנא\u0004 \u0005[ושאלנו]\u0006 אנשים אלה \u0003ואמרו: \"לא היו דברים מעולם\",\u0004 שכן ברור איפוא שהיתה קטטה גדולה ביניהם, אבל אין לסמוך עליה שבאמת היא גרושה.","ולבירור הטעם, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שבמקרה של \u0003קטטה\u0004 ביניהם אין אנחנו סומכים על עדותה? — \u0003רב חנינא אמר: משום דמשקרא\u0004 \u0005[ש\u0006היא \u0005משקרת]\u0006 ביודעים, שכיון שהתקוטטו היא עשויה להעיד בשקר שמת בעלה. \u0003רב שימי בר אשי אמר: משום דאמרה בדדמי\u0004 \u0005[שאומרת ב\u0006מה \u0005שנדמה\u0006 לה\u0005],\u0006 שכאשר שלום ביניהם, היא מדקדקת היטב לברר אם מת, וכאשר יש קטטה, איננה חוששת לדקדק כל כך, ושמחה שנפטרה ממנו. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 הלכה למעשה, אם זהו הטעם או זה?"],["\u0003איכא בינייהו דארגיל\u0004 \u0005[יש ביניהם\u0006 הבדל כ\u0005שהתחיל]\u0006 \u0003הוא\u0004 ב\u0003קטטה,\u0004 שאין לחשוש שהיא משקרת ביודעים כיון שאינה שונאת אותו, אבל יכול להיות שמפני הקטטה שביניהם אינה מקפידה, וכשייראה לה שמת — תעיד על כך.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005],\u0006 שאלה זו: היה \u0003עד אחד\u0004 מעיד שמת הבעל \u0003ב\u0004מקרה שהיתה ביניהם \u0003קטטה, מהו\u0004 הדין? וצדדי השאלה: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 ש\u0003עד אחד מהימן\u0004 \u0005[נאמן]\u0006 בעדות אשה, האם \u0003משום דמילתא דעבידא לאיגלויי לא\u0004 \u0005[ש\u0006ב\u0005דבר שעשוי להתגלות אינו]\u0006 \u0003משקר,\u0004 ואם כן \u0003הכא נמי לא משקר\u0004 \u0005[כאן גם כן אינו משקר],\u0006 \u0003או דלמא טעמא\u0004 \u0005[שמא הטעם]\u0006 ש\u0003עד אחד מהימן\u0004 \u0005[נאמן]\u0006 \u0003משום\u0004 ש\u0003היא,\u0004 האשה, \u0003דייקא ומינסבא\u0004 \u0005[מדייקת ו\u0006אחר כך \u0005נישאת],\u0006 \u0003והכא\u0004 \u0005[וכאן],\u0006 \u0003כיון דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003קטטה\u0004 איתה, \u0003לא דייקא ומינסבא\u0004 \u0005[איננה מדייקת ונישאת]\u0006 בכל מקרה? שאלה זו לא נפתרה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה ש\u0003ר' יהודה אומר\u0004 ש\u0003לעולם אינה\u0004 נאמנת ולא תינשא אלא אם כן באה בוכה ובגדיה קרועים, וחכמים אומרים שתינשא בכל מקרה. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמרו לו לר' יהודה: לדבריך,\u0004 לשיטתך, \u0003פקחת\u0004 שיודעת להערים, תבוא קרועת בגדים ובוכה — \u0003תנשא, שוטה\u0004 שאיננה יודעת — \u0003לא תנשא?!\u0004 וכי זו ראיה לאמינות העדות! \u0003אלא, אחת זו ואחת זו תנשא.\u0004","מסופר: \u0003ההיא דאתיא לבי דינא\u0004 \u0005[\u0006אשה \u0005אחת שבאה לבית דינו]\u0006 של \u0003ר' יהודה, אמרי\u0004 \u0005[אמרו]\u0006 \u0003לה\u0004 היושבים שם: \u0003ספדי\u0004 את \u0003בעלך, קרעי מאניך\u0004 \u0005[\u0006את \u0005בגדייך],\u0006 \u0003סתרי מזייך\u0004 \u0005[\u0006את \u0005שערך]\u0006 והיראי כאבילה ויאמינו לך. ותוהים: וכי \u0003אלפוה שיקרא\u0004 \u0005[לימדו אותה שקר]?\u0006 ומשיבים: \u0003אינהו כרבנן סבירא להו\u0004 \u0005[הם סבורים היו כחכמים]\u0006 שמותרת להינשא בכל מקרה, אבל הם חששו שתיאסר, כיון שר' יהודה אינו מתיר בכל מקרה, ולכך \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003תעביד הכי כי היכי דלישריה\u0004 \u0005[\u0006ש\u0005תעשה כך כדי שיתיר אותה]\u0006 גם ר' יהודה, ולא תבוא לידי סיבוך הענין.","\u0003בית הלל אומרים: לא שמענו\u0004 שמקבלים עדות של אשה על מות בעלה \u0003אלא בבאה מן הקציר, ובאותה מדינה\u0004 שמת שם היא גם מעידה, \u0003וכמעשה שהיה,\u0004 שהתירו במקרה כזה, כפי שיבואר.","\u0003אמרו להם בית שמאי: אחת הבאה מן הקציר, ואחת הבאה מן הזיתים, ואחת הבאה מן הבציר, ואחת הבאה ממדינה למדינה. לא דברו חכמים בקציר\u0004 למרות שהמעשה היה בקציר \u0003אלא בהווה\u0004 בדבר הרגיל, אבל אין זו הוכחה שנאמנת דווקא בקציר. ומעירים: \u0003חזרו בית הלל להורות כבית שמאי\u0004 בענין זה, כי חזרו בהם מדבריהם.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמרו להם בית שמאי לבית הלל: לדבריכם,\u0004 שיש לנהוג רק כמעשה שהיה, אם כן \u0003אין לי אלא קציר חטים\u0004 כאותו מעשה שהיה — \u0003קציר שעורים מנין? ואין לי אלא קוצר,\u0004 אבל אם היה \u0003בוצר\u0004 ענבים, או \u0003מוסק\u0004 זיתים, או \u0003גודר\u0004 תמרים, או \u0003עודר\u0004 תאנים \u0003מנין?\u0004","\u0003אלא מעשה שהיה — בקציר\u0004 היה, \u0003והוא הדין לכולהו\u0004 \u0005[לכולם]\u0006 לכל המקרים האחרים, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לגבי הבאה ממדינה אחרת וכיוצא באלה יש לומר \u0003מעשה שהיה — באותה מדינה\u0004 היה, \u0003והוא הדין לכולהו\u0004 \u0005[לכולם].\u0006","\u0003ובית הלל\u0004 מה טעמם — \u0003באותה מדינה דשכיחי אינשי\u0004 \u0005[שמצויים אנשים]\u0006 הבאים ממקום למקום — \u0003מירתת\u0004 \u0005[\u0006היא \u0005מפחדת\u0006 לשקר\u0005]\u0006 שמא יכחישוה, ואולם \u0003ממדינה למדינה אחרת, דלא שכיחי אינשי\u0004 \u0005[שאין אנשים מצויים]\u0006 לבוא משם — \u0003לא מירתת\u0004 \u0005[אינה מפחדת]\u0006 ושמא תשקר ותאמר שמת. \u0003ובית שמאי\u0004 סבורים: \u0003הכא נמי שכיחי שיירתא\u0004 \u0005[כאן גם כן מצויות שיירות]\u0006 ובסופו של דבר יוודע אם חי הוא.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 אותו \u0003מעשה שהיה?\u0004 — ש\u0003אמר רב יהודה אמר שמואל: שילפי\u0004 (סוף זמן) \u0003קציר חטין היו, והלכו עשרה בני אדם לקצור חטין,\u0004 ו\u0003נשכו נחש לאחד מהן ומת, ובאת אשתו והודיעה לבית דין\u0004 שמת בעלה. \u0003ושלחו ומצאו כדבריה. באותה שעה אמרו, האשה שאמרה: \"מת בעלי\" — תנשא\u0004 על סמך עדות זו, \u0003\"מת בעלי\"\u0004 בלא בנים ויש לו אח — \u0003תתייבם\u0004 על סמך עדותה, וזהו המעשה שדיברו בו.","ושואלים לעצם המחלוקת: \u0003נימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי \u0003ר' חנניא בן עקיבא ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים עליו בנושא אחר, \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003בית שמאי ובית הלל קמיפלגי\u0004 \u0005[\u0006הם \u0005חלוקים]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא ישא אדם מי חטאת\u0004 (מים של אפר פרה אדומה המטהרים את האדם הטמא טומאת־מת), \u0003ו\u0004כן \u0003אפר חטאת\u0004 (אפר פרה אדומה) \u0003ויעבירם בירדן ובספינה,\u0004","\u0003ולא יעמוד בצד זה\u0004 של הנהר \u0003ויזרק\u0004 אותם \u0003לצד\u0004 ה\u0003אחר, ולא ישיטם\u0004 בעוברו \u0003על פני המים, ולא ירכיבם לא\u0004 כשהוא \u0003על גבי בהמה ולא\u0004 כשהוא \u0003על גבי חברו\u0004 העוברים במים, שזה דומה לספינה העוברת על פני המים, \u0003אלא אם כן היו רגליו\u0004 של הרוכב \u0003נוגעות בקרקע. אבל מעבירם על הגשר\u0004 שעל הנהר. ומעירים: \u0003אחד ירדן ואחד שאר נהרות\u0004 יש בהם איסור זה, ואילו \u0003ר' חנניא בן עקיבא אומר: לא אמרו\u0004 איסור זה \u0003אלא\u0004 ב\u0003ירדן, ובספינה, וכמעשה שהיה\u0004 שנמצאה טומאה בספינה שבירדן.","ואם כן \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי \u0003רבנן דאמרי\u0004 \u0005[חכמים שאמרו]\u0006 בענין זה, סבורים \u0003כבית שמאי,\u0004 שכשעיקר הדין נוצר משום מעשה שהיה ניישם אותו על כל הדומה לו. \u0003ור' חנניא בן עקיבא\u0004 ש\u0003אמר כבית הלל\u0004 שאין עושים אלא כמעשה שהיה בדיוק.","ודוחים: \u0003אמרי לך רבנן\u0004 \u0005[\u0006יכולים \u0005חכמים לומר לך]:\u0006 \u0003אנן דאמרינן\u0004 \u0005[אנו שאומרים אנו]\u0006 בענין זה, יכולים אנו לסבור \u0003אף כ\u0004שיטת \u0003בית הלל,\u0004 אלא שיש לחלק; \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי\u0004 \u0005[אמרו]\u0006 \u0003בית הלל התם\u0004 \u0005[שם]\u0006 שאין מאמינים לה ממדינה למדינה, \u0003אלא משום דמירתת\u0004 \u0005[ש\u0006היא \u0005מפחדת],\u0006 ואם כן, \u0003במקום קרוב — מירתת\u0004 \u0005[מפחדת]\u0006 להעיד שקר שקל לדעת אם משקרת, \u0003במקום רחוק — לא מירתת\u0004 \u0005[אינה מפחדת].\u0006 אבל \u0003הכא\u0004 \u0005[כאן],\u0006 בענין אפר חטאת, \u0003מה לי\u0004 דווקא נהר ה\u0003ירדן מה לי שאר נהרות.\u0004","ואילו \u0003ר' חנניא בן עקיבא אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]:\u0006 \u0003אנא דאמרי\u0004 \u0005[אני שאומר]\u0006 שיטתי בענין זה, \u0003אף ל\u0004שיטת \u0003בית שמאי\u0004 אני אומר, ומדוע? — \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי\u0004 \u0005[אמרו]\u0006 \u0003בית שמאי התם\u0004 \u0005[שם]\u0006 \u0003אלא משום דאיהי דייקא ומינסבא\u0004 \u0005[שהיא\u0006 עצמה \u0005מדייקת\u0006 היטב בעדות \u0005ו\u0006אחר כך \u0005נישאת],\u0006 ומאחר שעל כך סומכים, אם כן, \u0003מה לי מקום קרוב מה לי מקום רחוק,\u0004 ואין הבדל בדבר, ואולם \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003משום מעשה שהיה\u0004 גזרו ולא מטעם שבדבר זה עצמו. ולכן \u0003בירדן ובספינה דהוה\u0004 \u0005[שהיה]\u0006 בהם ה\u0003מעשה\u0004 — \u0003גזור רבנן\u0004 \u0005[גזרו חכמים],\u0006 \u0003בשאר נהרות\u0004 ש\u0003לא הוה\u0004 \u0005[היה]\u0006 בהם \u0003מעשה\u0004 — \u0003לא גזור רבנן\u0004 \u0005[גזרו חכמים].\u0006","ומסבירים: \u0003מאי\u0004 \u0005[מה]\u0006 אותו \u0003מעשה שהיה,\u0004 שאליו מתייחסים החולקים? — ש\u0003אמר רב יהודה אמר רב: מעשה באדם שהיה מעביר מי חטאת ואפר חטאת בירדן ובספינה, ונמצא כזית מן המת תחוב בקרקעית של ספינה,\u0004 וניטמאו מי החטאת ואפר החטאת. \u0003באותה שעה אמרו: לא ישא אדם מי חטאת ואפר חטאת ויעבירם בירדן ובספינה.\u0004 ונחלקו חכמים מאוחרים יותר, האם מרחיבים את הגזירה הזו, או משאירים אותה כמעשה שהיה בדיוק.","\u0003בית שמאי אומרים:\u0004 אשה שהעידה שמת בעלה — \u0003תנשא, ותטול כתובתה. בית הלל אומרים: תנשא, ולא תטול כתובתה,\u0004 משום שלענין ממונות צריך עדות גמורה של שני עדים. \u0003אמרו להם בית שמאי:\u0004 אם \u0003התרתם ערוה,\u0004 שהיא \u0003חמורה,\u0004 על ידי עדות עצמה, \u0003ו\u0004כי \u0003לא נתיר\u0004 בשל אותה עדות עצמה את ה\u0003ממון הקל\u0004 שניתן להשבה, ואין בו עונשים חמורים כל כך?! \u0003אמרו להם בית הלל:\u0004 אין זו ראיה, שכן \u0003מצינו\u0004 \u0005[מוצאים אנו]\u0006"],["\u0003שאין האחין נכנסין לנחלה\u0004 של אותו אח שמת, ויורשים אותו \u0003על פיה\u0004 (על פי עדותה), משמע שאף שכוחה של עדות זו יפה לדיני עריות, אין היא מועילה לדיני ממונות!","\u0003אמרו להם בית שמאי: והלא מספר כתובה\u0004 שהוא כותב לה \u0003נלמוד\u0004 כדברינו, שנוטלת כתובתה! \u0003ש\u0004הרי \u0003הוא כותב לה: שאם תנשאי לאחר תטלי מה שכתוב ליכי\u0004 (לך) בכתובה זו. ונמצא שזה תנאי בכתובה שתהא תלויה בהיתר הנישואין, וכיון שנאמנת לומר שמת בעלה ויכולה להינשא שנית — יש לה גם כתובה. \u0003וחזרו בית הלל\u0004 מדבריהם וקבעו שיש \u0003להורות כדברי בית שמאי.\u0004","\u0003אמר רב חסדא:\u0004 אם \u0003נתייבמה\u0004 אותה אשה על פי עדות עצמה — \u0003יבמה נכנס לנחלה,\u0004 ויורש את רכוש אחיו המת \u0003על פיה.\u0004 וטעמו: \u0003הם,\u0004 בית שמאי, \u0003דרשו מדרש כתובה,\u0004 ומכאן הסיקו שנותנים לה כתובתה — \u0003אנו לא נדרוש מדרש תורה?!\u0004","שהרי \u0003\"יקום על שם אחיו\u0004 המת\u0003\"\u0004 (דברים כה, ו) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 ופירשוהו חכמים שהכוונה לירושת היבם, \u0003והרי קם\u0004 לענין אישות, שהרי מייבם על פי עדות האשה שבעלה מת, ואם כן גם לענין ירושה צריך לקום תחתיו.","\u0003אמר רב נחמן: באת\u0004 (באה) אשה \u0003לבית דין, ואמרה: \"מת בעלי, התירוני להנשא\"\u0004 — לאחר שחוקרים בדבר, \u0003מתירין אותה להנשא, ו\u0004גם \u0003נותנין לה כתובתה.\u0004 אבל אם באה ואמרה: \u0003\"תנו לי כתובתי\" — אף להנשא אין מתירין אותה. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003אדעתא\u0004 \u0005[על דעת]\u0006 ה\u0003כתובה אתאי\u0004 \u0005[\u0006היא \u0005באה]\u0006 ומעידה, ואנו חוששים שהיא משקרת, ואין סומכים על עדותה בדברים שבממון, ולכן גם לא לענין נישואין.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005],\u0006 בהמשך לדברים אלה, אם באה ואמרה: \u0003\"התירוני להנשא ותנו לי כתובתי\" מהו?\u0004 האם נאמר \u0003כיון\u0004 ש\u0003אמרה\u0004 והזכירה את \u0003כתובתה — אדעתא\u0004 \u0005[על דעת]\u0006 ה\u0003כתובה אתאי\u0004 \u0005[\u0006היא \u0005באה],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כל מילי דאית ליה לאיניש\u0004 \u0005[הדברים שיש לו לאדם]\u0006 לומר, \u0003אמר להו לבי דינא\u0004 \u0005[אומר להם לבית הדין],\u0006 גם אם הם דברים לא עיקריים ואין בתופסת דבריה כדי לפגום. \u0003ואם תמצי לומר\u0004 \u0005[ואם תמצא,\u0006 תרצה \u0005לומר]\u0006 ותסביר כי \u0003כל מילי דאית ליה לאיניש\u0004 \u0005[הדברים שיש לו לאדם]\u0006 לומר, \u0003אמר להו לבי דינא\u0004 \u0005[אומר להם לבית דין],\u0006 אם באה ואמרה: \u0003\"תנו לי כתובתי והתירוני להנשא\" מהו?\u0004","\u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ודאי אדעתא\u0004 \u0005[על דעת]\u0006 ה\u0003כתובה אתאי\u0004 \u0005[\u0006היא \u0005באה],\u0006 שהרי הקדימה דבר זה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 אמרה זאת \u0003הואיל דלא ידעה במאי משתריא\u0004 \u0005[שאינה יודעת במה\u0006 היא \u0005מותרת]\u0006 וחשבה שגם נטילת הכתובה היא חלק מהתרתה להינשא, אבל באמת אין דעתה על הממון?! שאלה זו לא נפתרה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003הכל נאמנין להעידה\u0004 שמת בעלה, \u0003חוץ מחמותה, ובת חמותה, וצרתה, ויבמתה\u0004 (גיסתה, אשת אחי בעלה), \u0003ובת בעלה\u0004 (בתה החורגת), שאנו חוששים שמא הן משקרות בכוונה כדי לקלקלה.","ומסבירים: \u0003מה בין גט למיתה,\u0004 שבגט כל אדם (ואף נשים אלה בכלל) נאמן להביא את הגט ולהעיד שהגט נכתב בכשרות? — \u0003ש\u0004בגט \u0003הכתב מוכיח,\u0004 שעיקר עדות זו נסמכת על הכתב, ובעדות מיתה אין ראיה מסייעת.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים, שאלה זו: \u0003בת חמיה\u0004 שאיננה בת חמותה \u0003מהו\u0004 שתעיד לה, האם גם היא חשודה או לא? וצדדי השאלה: \u0003טעמא\u0004 \u0005[הטעם]\u0006 ש\u0003בת חמותה\u0004 חשודה לשקר — \u0003משום דאיכא אימא דסניא לה\u0004 \u0005[שישנה אם ששונאת אותה,\u0006 את הכלה\u0005],\u0006 לכן \u0003היא,\u0004 הבת, \u0003נמי סניא לה\u0004 \u0005[גם כן שונאת אותה],\u0006 \u0003והכא ליכא אימא דסניא לה\u0004 \u0005[וכאן אין אם ששונאת אותה],\u0006 שהרי אין היא בת החמות, ותהיה נאמנת.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003טעמא\u0004 \u0005[הטעם]\u0006 ש\u0003בת חמותה\u0004 שונאת אותה, \u0003דאמרה\u0004 \u0005[שאומרת]:\u0006 \u0003\"קאכלה לגירסנא דאימא\u0004 \u0005[\u0006היא \u0005אוכלת את האוכל ש\u0006הכינה \u0005אמי]\u0006 \u0003\", הכא נמי קאמרה\u0004 \u0005[כאן,\u0006 בבת חמיה, \u0005גם כן\u0006 היא \u0005אומרת]:\u0006 \u0003\"אכלה לגירסנא דבי נשאי\u0004 \u0005[\u0006היא \u0005אוכלת את האוכל של בית אבי]\u0006","\u0003\".\u0004 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר, ממה ששנינו: \u0003הכל נאמנין להעידה חוץ מחמש נשים, ואם איתא\u0004 \u0005[ואם יש]\u0006 מקום לומר שגם בת חמיה פסולה, אם כן \u0003שית הויין\u0004 \u0005[שש הן]!\u0006 ודוחים: אין ראיה מכאן, \u0003דלמא טעמא\u0004 \u0005[שמא הטעם]\u0006 של \u0003בת חמותה\u0004 שפסולה בעדותה, הוא מפני \u0003דאמרה\u0004 \u0005[ש\u0006היא משקרת ו\u0005אומרת]:\u0006 \u0003\"קאכלה לגירסנא דבי נשאי\u0004 \u0005[\u0006זו \u0005אוכלת את האוכל של בית אבי]\u0006 \u0003\",\u0004 ולפי טעם זה \u0003לא שנא\u0004 \u0005[אינו שונה\u0006 המצב\u0005]\u0006 אצל \u0003בת חמותה ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אצל \u0003בת חמיה,\u0004 שמכיון שטעם אחד הוא לפסול את שתיהן לא חילקו ביניהם.","ושואלים על סתירה למשנה ממקום אחר: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו]\u0006 במקום אחר \u0003חוץ משבע נשים\u0004 שאין נאמנות, ולכאורה הוסיף אותו תנא ומנה גם בת חמיה לעצמה! ומשיבים: השיטה \u0003ההיא,\u0004 כדעת \u0003ר' יהודה היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ר' יהודה מוסיף\u0004 לאלה הפסולות מלהעיד לאשה על מות בעלה \u0003אף\u0004 את \u0003אשת אב\u0004 ששונאת את בתה החורגת, \u0003והכלה\u0004 ששונאת את חמותה.","\u0003אמרו לו: אשת אב הרי היא בכלל בת הבעל, כלה הרי\u0004 היא \u0003בכלל חמותה.\u0004 כלומר, כשם שחמות חשודה על הכלה, כן הכלה חשודה על חמותה, ואין צורך למנות אותן לחוד.","\u0003ור' יהודה\u0004 שמונה אותן לחוד סבור: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003חמותה סניא לה\u0004 \u0005[שונאת אותה]\u0006 את ה\u0003כלה\u0004 — \u0003דאמרה\u0004 \u0005[ש\u0006היא \u0005אומרת]:\u0006 \u0003קאכלה לגירסני\u0004 \u0005[\u0006היא \u0005אוכלת את מאכליי\u0006 שאני מכינה\u0005],\u0006 \u0003אלא כלה מאי טעמא סניא\u0004 \u0005[מה טעם שונאת]\u0006 את \u0003חמותה? בשלמא\u0004 \u0005[נניח]\u0006 \u0003בת הבעל דסניא\u0004 \u0005[ששונאת]\u0006 \u0003לאשת האב — דאמרה\u0004 \u0005[ש\u0006היא \u0005אומרת]:\u0006 \u0003קאכלה לגירסני דאם\u0004 \u0005[\u0006היא \u0005אוכלת את מאכלי אמי],\u0006 שמה שהכינה אמי — אוכלת אשה זו. \u0003אלא אשת האב מאי טעמא סניא\u0004 \u0005[מה טעם שונאת]\u0006 את \u0003בת הבעל?\u0004","ושואלים: אם כן הוא \u0003אלא מאי\u0004 \u0005[\u0006מפני \u0005מה]\u0006 \u0003מוסיף\u0004 ר' יהודה \u0003תרתי\u0004 \u0005[שתי\u0006 אלה\u0005]?\u0006 \u0003אלא\u0004 טעמו הוא: \u0003כלה מאי טעמא סניא\u0004 \u0005[מה טעם שונאת]\u0006 את \u0003חמותה\u0004 — משום שהיא אומרת שהיא \u0003מגלה לבנה כל\u0004 מה \u0003דעבדה\u0004 \u0005[ש\u0006היא \u0005עושה],\u0006 וכן \u0003אשת אב נמי סניא\u0004 \u0005[גם כן שונאת]\u0006 את \u0003בת הבעל\u0004 משום שהיא \u0003מגלה לאביה כל\u0004 מה \u0003דעבדה\u0004 \u0005[ש\u0006היא \u0005עושה],\u0006 ויש טעם אחר לשנאה זו ממה שבת הבעל שונאת אותה.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 האומרים שהדברים הם הדדיים, ומונים במשנה רק חמש נשים פסולות, סומכים על הכתוב \u0003\"כמים הפנים לפנים כן לב האדם לאדם\"\u0004 (משלי כז, יט), וכיון שכל אחת יש לה סיבה לשנוא את חברתה, ממילא השנאה נעשית הדדית. ושואלים: \u0003ור' יהודה\u0004 מדוע איננו סומך על כתוב זה? ומשיבים: לדעתו \u0003ההיא\u0004 \u0005[אותו\u0006 פסוק\u0005]\u0006 על \u0003דברי תורה כתיב\u0004 \u0005[נאמר],\u0006 כלומר, לפי אותם הפנים — באותו אופן שאדם משים לב לדברי תורה — כך מתגלה ונקנית לו התורה.","\u0003אמר רב אחא בר עויא: בעי במערבא\u0004 \u0005[שאלו בארץ ישראל]\u0006 שאלה זו: \u0003חמותה הבאה לאחר מיכן\u0004 (מכאן) \u0003מהו?\u0004 כגון שהיא אמו של אחי הבעל, ולא אם הבעל, שתהיה חמותה לאחר שתתייבם, האם היא נאמנת להעיד על אשת בנה לעתיד? וטעם הדברים, \u0003מי מסקה אדעתה דמית בעל ונפלה קמי יבם וסניא לה\u0004 \u0005[האם מעלה על דעתה שימות בעלה\u0006 של זו \u0005ותיפול\u0006 זו \u0005לפני\u0006 בנה ה\u0005יבם ו\u0006היא \u0005שונאה אותה]\u0006 כבר כעת \u0003או לא?\u0004"],["\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה ששנינו, \u0003אמרה\u0004 האשה: \u0003\"מת בעלי ואחר כך מת חמי\" — תנשא ותטול כתובה, וחמותה אסורה\u0004 להינשא, שהרי כפי שאמרנו אינה נאמנת להעיד עבורה. ונברר: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003חמותה אסורה? לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 שמא באמת \u0003לא בעלה מיית\u0004 \u0005[מת]\u0006 \u0003ולא חמיה מיית\u0004 \u0005[מת],\u0006 \u0003והא דקאמרה הכי\u0004 \u0005[וזה שהיא\u0006 \u0005אומרת כך] —\u0006 \u0003לקלקולא\u0004 \u0005[לקלקל]\u0006 \u0003לחמותה הוא דקמיכוונא\u0004 \u0005[שמתכוונת],\u0006 שכן","\u0003סברה\u0004 \u0005[סוברת\u0006 היא\u0005]:\u0006 \u0003לבתר שעתא\u0004 \u0005[לאחר זמן],\u0006 כאשר יגיע הבעל, \u0003לא תיתי תצטערן\u0004 \u0005[תבוא,\u0006 תחזור, ו\u0005תצער אותי],\u0006 שהרי אם תסמוך החמות על עדות זו ותינשא לא תוכל עוד לחזור לבעלה, ותשתחרר הכלה מחמותה. ואם כן רואים מכאן שאנו חושדים בכלה שמשקרת לא רק לגבי יחסים שבעבר, אלא גם בדברים שעשויים להיות בעתיד. ואף לענייננו נאמר שחשודה החמות על הכלה העתידה להיות לה לאחר זמן.","ודוחים: \u0003דלמא שאני התם דרגיש לה צערא\u0004 \u0005[שמא שונה שם ש\u0006כבר \u0005הרגישה\u0006 הכלה ב\u0005צער],\u0006 שכיון שהיתה מצערת אותה בעבר, הרי בשל אותו צער היא חשודה לשקר, מה שאין כן בחמותה הבאה לאחר מכן — שאין חוששים לכך, ואם כן אין פתרון לשאלה.","\u0003עד אומר: \"מת\u0004 האיש \u0003\", ונשאת\u0004 אשתו על פי עדות זאת, \u0003ובא\u0004 עד \u0003אחד ואמר: \"לא מת\" — הרי זו לא תצא\u0004 מבעלה החדש על פי עדות זו. \u0003עד\u0004 אחד \u0003אומר: \"מת\u0004 הבעל \u0003\"\u0004, \u0003ושנים אומרים: \"לא מת\"\u0004 — \u0003אף על פי שנשאת\u0004 על פי עדות הראשון, \u0003תצא. שנים אומרים: \"מת\", ועד\u0004 אחד \u0003אומר: \"לא מת\"\u0004 — הרי סומכים על השניים, ו\u0003אף על פי שלא נשאת, תנשא,\u0004 אם רצונה בכך.","ומדייקים: \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 משום \u0003דנשאת\u0004 \u0005[שנישאה\u0006 כבר\u0005],\u0006 \u0003הא\u0004 \u0005[הרי\u0006 אם\u0005]\u0006 עדיין \u0003לא נשאת\u0004 ובינתיים בא עד שני ומכחיש את דברי הראשון — \u0003לא תנשא.\u0004 ושואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003עולא: כל מקום שהאמינה תורה עד אחד — הרי\u0004 עדותו נחשבת כאילו היו \u0003כאן שנים\u0004 ועדותו מתקבלת כהוכחה מלאה. ואם כן העד שבא והעיד להיפך הוא רק אחד, \u0003ואין דבריו של אחד במקום שנים.\u0004 ותינשא גם לכתחילה?","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך צריך להבין את המשנה: \u0003עד אחד אומר: \"מת\", והתירוה להנשא\u0004 על פיו, \u0003ובא אחד ואמר: \"לא מת\" — לא תצא,\u0004 וכוונתו: לא תצא \u0003מהיתירה הראשון,\u0004 שעדיין היא בהיתרה הראשון ומותר לה להינשא לכתחילה.","שנינו במשנה: \u0003עד\u0004 אחד \u0003אומר: \"מת\"\u0004 ובאים שניים ואומרים \"לא מת\" — תצא. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי \u0003אין דבריו של\u0004 עד \u0003אחד\u0004 מועילים \u0003במקום\u0004 (כנגד) \u0003שנים!\u0004 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003בפסולי עדות,\u0004 כלומר, השניים לא היו עדים כשרים אלא פסולי עדות, ומקבלים את דבריהם בעדות אשה כדי להכחיש את העד הראשון. \u0003וכ\u0004דברי \u0003ר' נחמיה,\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' נחמיה אומר: כל מקום שהאמינה תורה\u0004 לדברי \u0003עד אחד — הלך\u0004 בענין זה \u0003אחר רוב דעות,\u0004 אפילו הם פסולים, \u0003ועשו\u0004 עדות \u0003שתי נשים באיש אחד\u0004 (כנגד איש אחד) \u0003כ\u0004מו עדות \u0003שני אנשים באיש אחד\u0004 ומבטלת עדות השניים את העדות הראשונה. ולכן היה צריך לומר לנו שאף שהיה בראשונה עד אחד כשר — עדותו מתבטלת על פי דברי שני העדים הפסולים שהכחישוהו.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כך: \u0003כל היכא דאתא\u0004 \u0005[מקום שבא]\u0006 \u0003עד אחד כשר מעיקרא\u0004 \u0005[מתחילה]\u0006 והעיד שמת — \u0003אפילו מאה נשים\u0004 המכחישות אותו \u0003כעד אחד דמיין\u0004 \u0005[\u0006הן \u0005נחשבות]\u0006 ואינן יכולות לבטל עדותו, \u0003אלא\u0004 כאן מדובר \u0003כגון דאתאי\u0004 \u0005[שבאה]\u0006 \u0003אשה מעיקרא\u0004 \u0005[מתחילה]\u0006 ועל עדותה סמכו להתיר, ואחר כך באו שתי נשים והכחישו אותה.","\u0003ותרצה\u0004 \u0005[ותקן,\u0006 ישב\u0005]\u0006 את דברי \u0003ר' נחמיה הכי\u0004 \u0005[כך],\u0006 \u0003ר' נחמיה אומר: כל מקום שהאמינה תורה עד אחד,\u0004 כגון בעדות אשה — \u0003הלך אחר רוב דעות, ועשו שתי נשים באשה אחת כשני אנשים באיש אחד. אבל שתי נשים באיש אחד — כפלגא ופלגא דמי\u0004 \u0005[כמחצה ומחצה נחשבים]\u0006 שאין יתרון לעדות שתי נשים על עדות איש אחד שנחשב כשניים בעדות אשה.","שנינו במשנה: \u0003שנים אומרים \"מת\"\u0004 ועד אחד אומר \"לא מת\", אף שלא נישאת עדיין — תינשא. ושואלים: \u0003מאי קמשמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך? אם תאמר שמדובר גם פה \u0003בפסולי עדות,\u0004 ששתי נשים אמרו שמת, \u0003וכ\u0004דברי \u0003ר' נחמיה דאזיל\u0004 \u0005[שהולך]\u0006 \u0003בתר\u0004 \u0005[אחרי]\u0006 \u0003רוב דעות,\u0004 אם כן \u0003היינו הך\u0004 \u0005[הוא הוא]\u0006 וכבר למדנו דבר זה בפיסקה הקודמת!","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 ותחלק כך: \u0003כי אזלינן בתר\u0004 \u0005[כאשר אנו הולכים אחר]\u0006 \u0003רוב דעות,\u0004 הרי זה דווקא \u0003לחומרא\u0004 \u0005[להחמיר],\u0006 \u0003אבל לקולא\u0004 \u0005[להקל]\u0006 להתיר לה להינשא על פיהם — \u0003לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין מחלקים בכך, והולכים אחר רוב דעות בין להחמיר ובין להקל.","באו שתי נשים שהיו נשואות לאיש אחד, \u0003אחת\u0004 מהן \u0003אומרת: \"מת\u0004 הבעל\u0003\"\u0004, \u0003ואחת אומרת \"לא מת\"\u0004 — \u0003זו שאומרת \"מת\", תנשא\u0004 על סמך עדות עצמה \u0003ותטול כתובתה, וזו שאומרת \"לא מת\" — לא תנשא ולא תטול כתובתה.\u0004","\u0003אחת אומרת \"מת\u0004 כדרכו \u0003\"\u0004\u0003ואחת אומרת \"נהרג\", ר' מאיר אומר: הואיל ומכחישות זו את זו — הרי אלו לא ינשאו, ר' יהודה ור' שמעון אומרים: הואיל וזו וזו מודות שאין\u0004 הבעל \u0003קיים,\u0004 אף שהן חלוקות בסיפור המעשה — \u0003ינשאו. עד\u0004 אחד \u0003אומר \"מת\" ועד\u0004 אחד \u0003אומר \"לא מת\",\u0004"],["\u0003אשה\u0004 אחת \u0003אומרת: \"מת\", ואשה\u0004 אחרת \u0003אומרת: \"לא מת\" — הרי זו לא תנשא.\u0004","לגבי ההלכה הראשונה שצרה אחת אומרת שמת הבעל והשניה אומרת שלא מת, שהדין הוא שזו שאמרה שלא מת לא תינשא, מדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005],\u0006 משום ש\u0003אמרה\u0004 הצרה השניה במפורש \u0003\"לא מת\", הא אישתיקא\u0004 \u0005[הרי\u0006 אם \u0005שתקה]\u0006 ולא אמרה כלום — \u0003תנשא\u0004 על פי עדותה של הראשונה? אולם תמוה הדבר, \u0003הא\u0004 \u0005[הרי]\u0006 אמרנו כי \u0003אין צרה מעידה לחברתה,\u0004 ואם כן אינה נאמנת להעיד עליה!","ומשיבים: \u0003\"לא מת\" איצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 לומר, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 שבאמת \u0003הא מיית\u0004 \u0005[זה,\u0006 אותו אדם, \u0005מת],\u0006 \u0003והא דקאמרה\u0004 \u0005[וזה שהיא\u0006 \u0005אומרת]\u0006 \u0003\"לא מת\" — לקלקולה\u0004 \u0005[לקלקל]\u0006 \u0003לצרה\u0004 שלה \u0003היא דקמיכוונא\u0004 \u0005[שמתכוונת],\u0006 \u0003ו\u0004לעצמה — \u0003\"תמות נפשה עם פלשתים\" קאמרה\u0004 \u0005[אומרת היא],\u0006 ומוכנה היא לקלקל לעצמה, ולהעיד בשקר שלא מת, ובלבד שתתקלקל בכך צרתה שלא תוכל להינשא, על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן, ואין מתירים אותה בעדות הצרה.","שנינו במשנה, \u0003אחת אומרת: \"מת\"\u0004 ואחת אומרת: \"נהרג\", אמר ר' מאיר כי הואיל ומכחישות זו את זו — לא יינשאו. ושואלים: \u0003וליפלוג\u0004 \u0005[ושיחלוק]\u0006 \u0003ר' מאיר\u0004 גם \u0003ברישא\u0004 \u0005[בתחילה]\u0006 במקרה כשאחת אומרת: \"מת\" ואחת אומרת: \"לא מת\"! \u0003אמר ר' אלעזר:\u0004 אכן, \u0003במחלוקת שנויה.\u0004 כלומר, ר' מאיר חולק גם על ההלכה הראשונה, \u0003ו\u0004מה שכתוב במשנה כסתם — דעת \u0003ר' יהודה ור' שמעון היא. ור' יוחנן אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהפיסקה הראשונה אף לדעת \u0003ר' מאיר\u0004 היא, אולם \u0003בהא\u0004 \u0005[בזו]\u0006 \u0003אפילו ר' מאיר מודה,\u0004 ש\u0003כל\u0004 עדות ש\u0003לא מת ב\u0004ענין \u0003עדות אשה — לאו\u0004 \u0005[לא]\u0006 \u0003הכחשה היא.\u0004","ושואלים על תירוץ זה ממשנתנו: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003עד אומר: \"מת\", ועד אומר: \"לא מת\", אשה\u0004 אחת \u0003אומרת: \"מת\" ואשה\u0004 אחרת \u0003אומרת: \"לא מת\" — הרי זו לא תנשא. בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' אלעזר\u0004 הדבר פשוט, כי \u0003סתמא\u0004 של משנה זו \u0003כ\u0004שיטת \u0003ר' מאיר\u0004 היא, שכאשר יש הכחשה בענין זה, אין סומכים על העדות שמת, \u0003אלא ל\u0004שיטת \u0003ר' יוחנן קשיא\u0004 \u0005[קשה]\u0006 הדבר! ומשיבים: אכן, \u0003קשיא\u0004 \u0005[קשה].\u0006","\u0003האשה שהלכה היא ובעלה למדינת הים, ובאה ואמרה: \"מת בעלי\" — תנשא, ותטול כתובתה\u0004 על פי עדות עצמה. \u0003וצרתה\u0004 שנשארה כאן \u0003אסורה,\u0004 משום שאין אשה נאמנת להעיד על צרתה. \u0003היתה\u0004 הצרה \u0003בת ישראל\u0004 הנשואה \u0003לכהן\u0004 — תמשיך ו\u0003תאכל בתרומה,\u0004 שכיון שאין מתירים לה להינשא, אנו מחזיקים לגביה שבעלה קיים, אלו \u0003דברי ר' טרפון.\u0004","\u0003ר' עקיבא אומר: אין זו דרך\u0004 ש\u0003מוציאתו מידי עבירה,\u0004 שאם נעשה כדברי ר' טרפון, יש חשש לעבירה (שאשה זו עכשיו אוכלת בתרומה), ואין תקנה אלא \u0003עד שתהא\u0004 הצרה גם \u0003אסורה לינשא,\u0004 שהרי אין האשה נאמנת להעיד על צרתה, \u0003ו\u0004גם \u0003אסורה מלאכול בתרומה\u0004 — שמא האשה אומרת אמת, ומחמירים עליה משני הצדדים.","וכיוצא בזה, \u0003אמרה\u0004 אשה: \u0003\"מת בעלי\u0004 תחילה \u0003ואחר כך מת חמי\"\u0004 — הרי זו \u0003תנשא ותטול כתובתה, וחמותה אסורה,\u0004 שאין כלה נאמנת להעיד על חמותה. ואם \u0003היתה\u0004 החמות \u0003בת ישראל\u0004 הנשואה \u0003לכהן — תאכל בתרומה,\u0004 אלו \u0003דברי ר' טרפון. ר' עקיבא אומר: אין זו דרך\u0004 ש\u0003מוציאה מידי עבירה, עד שתהא\u0004 אותה חמות \u0003אסורה לינשא, ואסורה\u0004 גם \u0003מלאכול בתרומה.\u0004","מחלוקת ר' טרפון ור' עקיבא נשנתה בשני מקרים הנראים לכאורה זהים. ומסבירים, \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שניהם. \u0003דאי איתמר הך קמייתא\u0004 \u0005[שאם היתה נאמרת\u0006 רק \u0005זו הראשונה],\u0006 הייתי אומר: \u0003בהא קאמר\u0004 \u0005[בזו,\u0006 בשתי צרות, \u0005אמר]\u0006 \u0003ר' טרפון\u0004 שאנו חוששים שהצרה משקרת \u0003משום דצערא\u0004 \u0005[שהצער]\u0006 של \u0003גופה\u0004 הוא, שיש פה קנאה עצמית, שהיא מקנאה בצרתה שמתחלקת עימה בבעלה, \u0003אבל\u0004 לגבי \u0003חמותה דצערא מילי דעלמא\u0004 \u0005[שהצער\u0006 הוא רק \u0005דברים בלבד],\u0006 כפי שכבר הוזכר למעלה ואין פה צער הגוף, \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לר' עקיבא\u0004 שאין לחשוש כל כך שהיא משקרת, ושמא אומרת אמת, ותיאסר חמותה לאכול בתרומה.","\u0003ו\u0004להיפך, \u0003אי איתמר בהא\u0004 \u0005[ואם היה נאמר\u0006 רק \u0005בזו],\u0006 בחמות, הייתי אומר כי \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003ר' עקיבא\u0004 שהחמות צריכה לחשוש \u0003אבל בהך\u0004 \u0005[באחרת,\u0006 בצרתה\u0005],\u0006 \u0003אימא מודה ליה\u0004 \u0005[אמור מודה לו]\u0006 \u0003לר' טרפון\u0004 שאוכלת בתרומה, על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 המחלוקת להיאמר בשני המקרים.","\u0003אמר רב יהודה אמר שמואל: הלכה כר' טרפון,\u0004 כלומר, שאין סומכים כלל על עדות אישה החשודה לקלקל, ואין חוששים. \u0003אמר אביי: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 ראיה לדבר: אם באה אשה ואמרה: \u0003\"ניתן לי\u0004 (כלומר, נולד לי) \u0003בן במדינת הים,\u0004 ו\u0003מת בני, ואחר כך\u0004 מת \u0003בעלי\",\u0004 ונמצא שלפי דבריה חייבת היא בייבום — הרי זו \u0003נאמנת\u0004 בכל מה שהעידה, ומותרת להתייבם. אם אמרה: \u0003\"\u0004מת \u0003בעלי, ואחר כך\u0004 מת \u0003בני\",\u0004 שנמצא שפוטרת בכך את עצמה מן הייבום — \u0003אינה נאמנת.\u0004","\u0003ו\u0004מכל מקום \u0003חוששין לדבריה, וחולצת ולא מתייבמת,\u0004 שחוששים שמא היה כדבריה, ואם אמנם מת בנה אחר בעלה, הריהי אסורה להתייבם. ונדייק מלשון המשנה: \u0003לדבריה\u0004 שלה עצמה \u0003הוא\u0004 ש\u0003חוששין, הא\u0004 \u0005[הרי]\u0006 \u0003לדברי צרה\u0004 המעידה עליה — \u0003אין חוששין\u0004 כלל. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006"],["כיון שהובאה קודם מחלוקת ר' טרפון ור' עקיבא, ושיטת ר' עקיבא היא שיש להוציא מחשש עבירה, מביאים כמה הלכות בנושאים אחרים שיש בהן אותה מחלוקת. \u0003קידש\u0004 אדם \u0003אחת מחמש נשים, ואין יודע אי זו\u0004 מהן \u0003קידש,\u0004 ו\u0003כל אחת\u0004 מהן \u0003אומרת: \"אותי קידש\"\u0004 — אם אינו רוצה בהן, \u0003נותן גט לכל אחת ואחת\u0004 כדי לפוטרה מן הספק, \u0003ומניח כתובה ביניהן, ומסתלק,\u0004 ויישאר סכום הכתובה שנוי במחלוקת ביניהן, עד שיתברר מי זכאית בכתובה, אלו \u0003דברי ר' טרפון.\u0004 \u0003ר' עקיבא אומר: אין זו דרך מוציא מידי עבירה,\u0004 שמא לא תקבל האשה שקידש באמת את הכתובה המגיעה לה, \u0003עד שיתן גט וכתובה לכל אחת ואחת\u0004 מהן. וכן אם \u0003גזל\u0004 אדם \u0003אחד מחמשה ואין יודע מאיזה\u0004 מהם \u0003גזל,\u0004 ו\u0003כל אחד\u0004 ואחד \u0003אומר: \"אותי גזל\" — מניח\u0004 את סכום ה\u0003גזילה ביניהן, ומסתלק\u0004 והם ידונו ביניהם מי יקבל את דמי הגזילה, אלו \u0003דברי ר' טרפון. ר' עקיבא אומר: אין זו דרך מוציא מידי עבירה, עד שישלם\u0004 את מלוא סכום הגזילה \u0003לכל אחד ואחד\u0004 מהם. תחילה מדייקים בלשון המשנה: \u0003\"קידש\u0004 אחת מחמש נשים \u0003\"\u0004— \u0003קתני\u0004 \u0005[שנה]\u0006 כאן, ואילו \u0003\"בעל\u0004 אחת מחמש נשים לשם קידושין \u0003\"\u0004— \u0003לא קתני\u0004 \u0005[שנה],\u0006 שבענין זה יש דין אחר. וכיוצא בו בסופה של המשנה: \u0003\"גזל\u0004 אחד מחמישה \u0003\"\u0004\u0003קתני\u0004 \u0005[שנה]\u0006 כאן, ואילו \u0003\"לקח\"\u0004 (קנה) \u0003לא קתני\u0004 \u0005[שנה].\u0006 ולפי דקדוק זה \u0003מני מתניתין\u0004 \u0005[\u0006כדעת \u0005מי משנתנו]:\u0006 \u0003לא\u0004 כדעת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003ולא\u0004 כדעת \u0003ר' שמעון בן אלעזר?\u0004","","","ומה עניינה של מחלוקת זו — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: לא נחלקו ר' טרפון ור' עקיבא על\u0004 מי \u0003שקידש אחת מחמש נשים, ואינו יודע איזו\u0004 מהן \u0003קידש,\u0004 שהכל מודים במקרה זה \u0003שמניח כתובה ביניהן ומסתלק. על מה נחלקו — על\u0004 זה \u0003שבעל\u0004 אחת מהן לשם קידושין, ש\u0003ר' טרפון אומר: מניח כתובה ביניהן ומסתלק,\u0004 ואילו \u0003ר' עקיבא אומר:\u0004 אין דרך להוציאו מידי עבירה \u0003עד שישלם לכל אחת ואחת,\u0004 שכיון שקידש אשה בצורה בלתי הגונה — הרי זה מן הראוי לקנסו ולפצות את האשה שקידש ולא להסתפק בהעמדת דברים על הדין בלבד. וכן \u0003לא נחלקו ר' טרפון ור' עקיבא על\u0004 מי \u0003שלקח\u0004 (קנה) \u0003מקח מחמשה בני אדם ואין יודע מאיזה מהן לקח\u0004 — שהכל מודים במקרה זה \u0003שמניח דמי מקח ביניהן ומסתלק. לא נחלקו אלא\u0004 במי \u0003שגזל מחמשה, שאמר ר' טרפון: מניח גזילה ביניהם ומסתלק, ור' עקיבא אומר:\u0004 אין דרך להוציאו מידי עבירה \u0003עד שישלם גזילה לכל אחד ואחד,\u0004 שאין לו תיקון עד שמובטח הוא שאמנם השיב את הגזילה לבעליה.","","ונדייק: \u0003מדקאמר\u0004 \u0005[מ\u0006מה \u0005שאמר]\u0006 \u0003ר' שמעון בן אלעזר\u0004 כי \u0003ב\"קידש\" ו\"לקח\" לא פליגי\u0004 \u0005[אינם חלוקים],\u0006 \u0003מכלל\u0004 הדברים אתה למד שה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שעליו הוא חולק \u0003סבר\u0004 ש\u0003פליגי\u0004 \u0005[נחלקו]\u0006 ב\"קידש\" ו\"לקח\", אבל ב\"בעל\" ו\"גזל\" מודה ר' טרפון. ומעתה, משנתנו \u0003מני\u0004 \u0005[\u0006כדעת \u0005מי היא]?\u0006","\u0003אי\u0004 \u0005[אם]\u0006 כדעת \u0003תנא קמא — ליתני\u0004 \u0005[שישנה]\u0006 \u0003\"קידש\" ו\u0004גם \u0003\"לקח\",\u0004 ולא \"גזל\", שהרי לפי דעתו ב\"גזל\" מודה ר' טרפון, \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 כדעת \u0003ר' שמעון בן אלעזר — ליתני\u0004 \u0005[שישנה]\u0006 \u0003\"בעל\" ו\"גזל\"?\u0004 שלדעתו רק בבעל נחלקו ר' טרפון ור' עקיבא ולא ב\"קידש\"!","ומשיבים: \u0003לעולם\u0004 יש לומר שמשנתנו כדעת \u0003ר' שמעון בן אלעזר\u0004 היא, \u0003ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"קידש\"\u0004 — כוונתו \u0003קידש בביאה.\u0004 ו\u0003תנא\u0004 \u0005[\u0006ו\u0005שנה]\u0006 בלשון \u0003\"קידש\", להודיעך כחו\u0004 של \u0003ר' עקיבא\u0004 עד כמה הוא מחמיר, \u0003דאף על גב דאיסורא דרבנן עבד\u0004 \u0005[שאף על פי ש\u0006רק \u0005איסור מדברי חכמים עשה\u0006 בכך\u0005],\u0006 שהרי לא בעל את האשה בזנות, אלא לשם קידושין, ועבר רק על דברי חכמים שאין מקדשים לכתחילה בביאה, בכל זאת \u0003קניס\u0004 \u0005[קונס]\u0006 אותו ר' עקיבא! מצד שני \u0003תנא\u0004 \u0005[שנה]\u0006 לשון \u0003\"גזל\", להודיעך כחו\u0004 של \u0003ר' טרפון\u0004 עד כמה הוא מיקל, \u0003דאף על גב דאיסורא דאורייתא עבד\u0004 \u0005[שאף על פי שאיסור מן התורה עשה],\u0006 מכל מקום \u0003לא קניס\u0004 \u0005[קנס]\u0006 אותו אפילו במקרה זה.","","\u0003האשה שהלכה היא ובעלה למדינת הים ו\u0004היה \u0003בנה עמהם, ו\u0004אחר זמן \u0003באת\u0004 (באה) האשה למקומה, \u0003ואמרה: \"מת בעלי ואחר כך מת בני\"\u0004 — הרי זו \u0003נאמנת\u0004 במה שהעידה, ומותרת להינשא ופטורה מן הייבום, שהרי כשיצאה למדינת הים היו לה בנים והיתה בחזקת מותרת לשוק. אבל אם אמרה: \u0003\"מת בני ואחר כך מת בעלי\" — אינה נאמנת\u0004 להתייבם, \u0003ו\u0004מכל מקום \u0003חוששין לדבריה\u0004 שמא היא אלמנה מבעל בלא בנים, \u0003ו\u0004לכן \u0003חולצת\u0004 כדי להיפטר מזיקת היבם, \u0003ולא מתייבמת\u0004.","אם יצאה עם בעלה בלא בנים וחזרה לבדה והעידה: \u0003\"ניתן לי\u0004 (נולד לי) \u0003בן במדינת הים\", ואמרה: \"מת בני ואחר כך מת בעלי\" — נאמנת\u0004 אפילו להתייבם, שבחזקת שאין לה בנים יצאה. אבל אם אמרה \u0003\"מת בעלי ואחר כך מת בני\" — אינה נאמנת\u0004 להיפטר בלא ייבום \u0003ו\u0004בכל אופן \u0003חוששין לדבריה, וחולצת ולא מתייבמת.\u0004 אמרה, \u0003\"ניתן לי\u0004 (נולד לי) \u0003יבם במדינת הים\",\u0004 שכשיצאה המשפחה למדינת הים לא היה לה יבם, והיא אומרת שנולד בינתיים אח לבעלה, והוסיפה ו\u0003אמרה: \"מת בעלי ואחר כך מת יבמי\",\u0004 או שאומרת: \u0003\"\u0004מת \u0003יבמי ואחר כך בעלי\"\u0004 — בכל מקרה \u0003נאמנת\u0004 לגמרי, שהרי כשיצאה לא היתה בחזקת זקוקה לייבום, ורק מפיה באה אלינו הידיעה שנולד יבם.","","אבל אם \u0003הלכה היא ובעלה ויבמה למדינת הים,\u0004 ו\u0003אמרה: \"מת בעלי ואחר כך יבמי\",\u0004 או שאמרה: \u0003\"\u0004מת \u0003יבמי ואחר כך בעלי\" — אינה נאמנת, ש\u0004כן \u0003אין האשה נאמנת לומר \"מת יבמי\" שתנשא\u0004 לחוץ על פי עדות זו, \u0003ולא\u0004 נאמנת לומר \u0003\"מתה אחותה\"\u0004 של עצמה, כדי \u0003שתכנס לביתו\u0004 (תינשא לבעל אחותה), \u0003ואין האיש נאמן לומר \"מת אחי\"\u0004 כדי \u0003שייבם\u0004 את \u0003אשתו\u0004 של האח, \u0003ולא\u0004 נאמן לומר \u0003\"מתה אשתו\"\u0004 שלו, כדי \u0003שישא\u0004 את \u0003אחותה\u0004 של אשתו בהיתר. שלא סמכו חכמים על עדות בלתי שלימה אלא במקום של חשש לעיגון אשה.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן\u0004 שאלה זו: \u0003המזכה גט לאשתו,\u0004 שמינה אדם לקבל גט בשביל אשתו, ואמר זאת בלשון זיכוי, שמזכה לה גט, \u0003במקום\u0004 שיש \u0003יבם, מהו?\u0004 האם לומר: \u0003כיון דסניא ליה\u0004 \u0005[ש\u0006היא \u0005שונאת אותו]\u0006 את היבם, אם כן \u0003זכות הוא לה\u0004 בקבלת הגט, שעל ידי כן נאסרת ליבם, \u0003ו\u0004כלל הוא כי \u0003זכין לאדם שלא בפניו,\u0004 ואין צורך בנוכחותו שימסור לה הגט, ואף כאן לא היה צריך להמתין, אלא מיד כשזיכה את הגט לשליח כבר נחשב הגט כבעל תוקף. \u0003או דלמא\u0004 \u0005[שמא],\u0006 \u0003כיון דזימנין דרחמא ליה\u0004 \u0005[שפעמים\u0006 היא \u0005אוהבת אותו\u0006 את היבם\u0005],\u0006 הרי גט זה \u0003חוב הוא לה,\u0004 שעל ידי הגט היא נאסרת על היבם באיסור גרושת אחיו \u0003ו\u0004כלל הוא ש\u0003אין חבין לאדם שלא בפניו,\u0004 וכל עוד לא קיבלה הגט לידה, אין לו תוקף.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003תנינא\u0004 \u0005[שנינו]\u0006 תשובה לדבר במשנתנו: \u0003וחוששין לדבריה, וחולצת ולא מתייבמת.\u0004 שכן במשנתנו נאמר שחוששים בכל מקרה, גם כשעדותה באה לפוטרה מן היבם וגם כשעדותה באה כדי להתייבם, משמע שאין אנו מחליטים אם הייבום נחשב לה כזכות או כחובה, אלא שזה נשאר בגדר ספק. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרבא: המזכה גט לאשתו במקום\u0004 שהיתה \u0003קטטה\u0004 ביניהם, \u0003מהו?\u0004 וצדדי השאלה: \u0003כיון דאית\u0004 \u0005[שיש]\u0006 \u0003לה קטטה בהדיה\u0004 \u0005[איתו] —\u0006 \u0003זכות הוא לה\u0004 בגט. \u0003או דלמא\u0004 \u0005[שמא],\u0006 \u0003ניחא דגופא עדיף\u0004 \u0005[נוחיות של גופה עדיפה]\u0006 \u0003לה,\u0004 שהיא מעדיפה להיות נשואה, למרות הקטטה שבינה לבין בעלה? ואומרים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר, ממה ש\u0003אמר ריש לקיש,\u0004 פתגם הוא שאומרות נשים: \u0003טב למיתב טן דו מלמיתב ארמלו\u0004 \u0005[טוב לשבת בצוותא מלשבת אלמנה,\u0006 בודדה\u0005],\u0006 משמע שאשה מעדיפה חברת בעל כלשהו על הבדידות.","","\u0003אביי אמר:\u0004 יש פתגם עממי אחר, שהיו אומרים: \u0003דשומשמנא גברא, כורסיה בי חרתא רמו לה\u0004 \u0005[\u0006זו \u0005שבעלה\u0006 קטן \u0005כנמלה, שמים לה כיסא בין השרות],\u0006 כלומר, היא מרוצה ומתגאה בזה שיש לה בעל כלשהו. \u0003רב פפא אמר\u0004 פתגם אחר: \u0003דנפצא גברא תיקרי בסיפי בבא ותיתיב\u0004 \u0005[\u0006זו \u0005שבעלה\u0006 הוא \u0005מנפץ\u0006 צמר, שמלאכתו נחשבת לבזויה, \u0005תזמין\u0006 עצמה \u0005לסף הפתח ותשב\u0006 שם\u0005]\u0006 להראות לכל שהיא אשה נשואה.","\u0003רב אשי אומר\u0004 פתגם זה: \u0003דקולסא גברא, לא בעיא טלפחי לקידרא\u0004 \u0005[\u0006זו \u0005שבעלה\u0006 הוא \u0005מוכר קלחי כרוב,\u0006 שמלאכתו בלתי חשובה, \u0005אינה רוצה\u0006 אפילו \u0005עדשים לקדרה],\u0006 שהיא שמחה כל כך שיש לה בעל עד שמוכנה לוותר מלקבל ממנו גם מזונות בסיסיים. על כל אלה מעירים, \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003וכולן,\u0004 כל הנשים הללו — \u0003מזנות ותולות בבעליהן.\u0004",""],["\u0003האשה שהלך בעלה וצרתה למדינת הים, ובאו\u0004 עדים \u0003ואמרו לה: \"מת בעליך\" — לא תנשא\u0004 לשוק, שמא היא זקוקה לייבום. \u0003ו\u0004גם \u0003לא תתייבם — עד שתדע שמא מעוברת היא צרתה\u0004 ושמא יוולד לה וולד, ונמצא שהיא אסורה ליבם כאשת אח שיש לו בנים.","\u0003היתה לה חמות\u0004 במדינת הים, אבל לא היו אחים לבעלה — \u0003אינה חוששת\u0004 שמא נולד אח. ואם \u0003יצתה\u0004 (יצאה) החמות כשהיא \u0003מליאה\u0004 (מעוברת) — יש לאשה להיות \u0003חוששת\u0004 שמא ילדה החמות בן ויש לבעלה אח, וחייבת בייבום. \u0003ר' יהושע אומר:\u0004 אף במקרה זה \u0003אינה חוששת,\u0004 ויכולה להינשא למי שתרצה.","ביחס לקטע הראשון שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 דיוק הביטוי \u0003\"\u0004מעוברת \u0003היא צרתה\"?\u0004 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 \u0003להא\u0004 \u0005[לזו]\u0006 ה\u0003צרה\u0004 שיצאה עם בעלה \u0003הוא דחיישינן\u0004 \u0005[שחוששים אנו]\u0006 שמא היא מעוברת, \u0003אבל לצרה אחריתי\u0004 \u0005[אחרת],\u0006 כלומר, שמא נשא אשה אחרת וילדה לו בן \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006","שנינו במשנה ש\u0003לא תנשא ולא תתייבם\u0004 עד שתדע שמא מעוברת צרתה. ושואלים: \u0003בשלמא יבומי\u0004 \u0005[נניח\u0006 ש\u0005להתייבם]\u0006 \u0003לא\u0004 תוכל, \u0003דדלמא מיעברא, וקפגעה\u0004 \u0005[שמא מעוברת\u0006 צרתה, \u0005ו\u0006נמצא ש\u0005היא פוגעת]\u0006 \u0003ב\u0004איסור \u0003אשת אח דאורייתא\u0004 \u0005[ש\u0006הוא \u0005מן התורה]\u0006 שהרי יש לבעלה בנים ואסורה היא על אחי בעלה משום אשת אח, ויש בכך חיוב כרת. \u0003אלא לא תנשא, אמאי\u0004 \u0005[מדוע]?\u0006 \u0003הלך אחר רוב נשים, ורוב נשים מתעברות ויולדות,\u0004 ומן הסתם ילדה צרתה, והיא פטורה מן הייבום!","\u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 שמשנתנו כשיטת \u0003ר' מאיר היא דחייש למיעוטא\u0004 \u0005[שחושש למיעוט],\u0006 ולכן, כיון שיש מיעוט נשים שאינן יולדות, הרי הוא חושש למיעוט זה וצריכה להמתין לייבום?","ודוחים: \u0003אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שהוא כשיטת \u0005חכמים]\u0006 — \u0003כי אזלי רבנן בתר רובא\u0004 \u0005[כאשר הולכים חכמים אחר הרוב]\u0006 הרי זה דווקא ב\u0003רובא דאיתיה קמן\u0004 \u0005[רוב שישנו לפנינו],\u0006 כלומר, שרוב זה מצוי וניתן להיבדק. \u0003כגון תשע חנויות,\u0004 שאם יש תשע חנויות שמוכרות בשר כשר וחנות אחת שמוכרת בשר טריפה, ונמצאה חתיכת בשר ואין יודעים מאיזו חנות היא נלקחה, מניחים שהבשר שנמצא הוא מן הרוב, ולא מן המיעוט. \u0003ו\u0004כן הדין ביחס ל\u0003סנהדרי\u0004 שקובעים המשתתפים בה את החלטתם על פי הצבעת הרוב. \u0003אבל רובא דליתיה קמן\u0004 \u0005[הרוב שאינו לפנינו],\u0006 כגון הקביעה שרוב נשים מתעברות ויולדות — אין זה רוב מנוי וספור לפנינו, ולכן \u0003לא אזלי רבנן בתר רובא\u0004 \u0005[אין הולכים\u0006 בו \u0005חכמים אחר הרוב]\u0006 במקרה כזה.","ומקשים: \u0003והרי\u0004 דין \u0003קטן וקטנה\u0004 בייבום, \u0003דרובא דליתא קמן היא\u0004 \u0005[שרוב שאיננו לפנינו הוא],\u0006 \u0003ואזלי רבנן בתר רובא\u0004 \u0005[והולכים\u0006 בו \u0005חכמים אחר הרוב]!\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003קטן וקטנה — לא חולצין ולא מייבמין,\u0004 אלו \u0003דברי ר' מאיר. אמרו לו\u0004 חכמים \u0003לר' מאיר: יפה אמרת שאין חולצין,\u0004 כי \u0003\"איש\" כתיב\u0004 \u0005[נאמר]\u0006 \u0003בפרשה\u0004 של חליצה, ומשמע מבוגר דווקא. \u0003ו\u0004אף שביבמה אין הדבר מפורש \u0003מקשינן\u0004 \u0005[מקישים,\u0006 משווים, \u0005אנו],\u0006 \u0003אשה לאיש,\u0004 שצריך שגם היא תהיה בוגרת. \u0003אלא מה טעם אין מייבמין,\u0004 הלא לענין ייבום נאמר \"יבמה יבוא עליה\" ולא נאמר שצריך שהם יהיו גדולים!","\u0003אמר להם:\u0004 חושש אני ב\u0003קטן שמא\u0004 יגדל ו\u0003ימצא\u0004 שהוא \u0003סריס, קטנה שמא\u0004 תגדל ו\u0003תמצא אילונית,\u0004 ובשניהם אין מצות ייבום, \u0003ונמצאו פוגעים בערוה,\u0004 שבאו על אשה אסורה להם שלא במקום מצוה. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003זיל בתר רובא\u0004 \u0005[לך אחר\u0006 ה\u0005רוב]\u0006 של ה\u0003קטנים, ורוב\u0004 ה\u0003קטנים לאו סריסי נינהו\u0004 \u0005[לא סריסים הם].\u0006 וכן \u0003זיל בתר\u0004 \u0005[לך אחר]\u0006 \u0003רוב\u0004 ה\u0003קטנות, ורוב\u0004 ה\u0003קטנות לאו\u0004 \u0005[לא]\u0006 \u0003אילונית נינהו\u0004 \u0005[הן].\u0006 משמע שחכמים חולקים על ר' מאיר אף ברוב כזה, שאינו מצוי לפנינו. \u0003אלא, מחוורתא מתניתין\u0004 \u0005[מחוור,\u0006 ברור ש\u0005משנתנו]\u0006 כשיטת \u0003ר' מאיר\u0004 החושש למיעוט, \u0003היא.\u0004","ושואלים: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת,\u0006 הסברת\u0005]\u0006 את המשנה — \u0003כ\u0004שיטת \u0003ר' מאיר, אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]:\u0006 \u0003היתה לה\u0004 לאשה שבעלה הלך למדינת הים והעידו עליו שמת, \u0003חמות\u0004 שלא ילדה — \u0003אינה חוששת. אמאי\u0004 \u0005[\u0006ו\u0005מדוע]\u0006 לא נחשוש? \u0003הלך אחר רוב נשים, ו\u0004הלא \u0003רוב נשים מתעברות ויולדות,\u0004 ואף אם \u0003מיעוט\u0004 מהן \u0003מפילות, ו\u0004אולם, מכיון ש\u0003כל היולדות\u0004 יולדות \u0003מחצה זכרים ומחצה נקבות,\u0004 אם כן, היו צריכים לומר \u0003סמוך,\u0004 צרף, \u0003מיעוטא\u0004 \u0005[\u0006את ה\u0005מיעוט]\u0006 ש\u0003מפילות למחצה נקבות והוו ליה\u0004 \u0005[והרי הם]\u0006 ה\u0003זכרים\u0004 שיכולים להיוולד רק \u0003מיעוטא\u0004 \u0005[מיעוט].\u0006 אולם אם שיטת ר' מאיר היא, החושש למיעוט — \u0003וליחוש\u0004 \u0005[ושיחשוש]\u0006 שמא ילדה החמות אח לבעלה, וצריכה להמתין לו להתייבם!","ודוחים: \u0003דלמא\u0004 \u0005[שמא],\u0006 \u0003כיון דאיחזקה\u0004 \u0005[שהוחזקה]\u0006 \u0003לשוק,\u0004 שהיתה בחזקת היתר להינשא לכל מי שתרצה, שהרי לא היו לו אחים לבעלה כשיצא, \u0003לא חייש\u0004 \u0005[אין\u0006 ר' מאיר \u0005חושש]\u0006 למיעוט. ומקשים: אם כן, נאמר נימוק זה גם מקרה המובא ב\u0003רישא\u0004 \u0005[\u0006ב\u0005ראש\u0006 המשנה\u0005]\u0006 באשה \u0003דאיחזק\u0004 \u0005[שהוחזקה]\u0006 \u0003לייבום,\u0004 שהרי לא היו בנים לבעלה — \u0003תייבם\u0004 \u0005[תתייבם]\u0006 ונלך אחרי החזקה ולא נחשוש שמא ילדה צרתה בן!","\u0003אמר רב נחמן אמר רבה בר אבוה:\u0004 יש להבדיל, שכן \u0003רישא\u0004 \u0005[\u0006ב\u0005ראש\u0006 המשנה\u0005]\u0006 שיש חשש \u0003איסור כרת,\u0004 שהרי אשת אח שלא במקום מצוה אסורה באיסור כרת, לכן \u0003חששו,\u0004 ואילו \u0003סיפא\u0004 \u0005[\u0006ב\u0005סופה]\u0006 שהוא \u0003איסור לאו\u0004 \u0005[לא\u0006 תעשה\u0005],\u0006 שאם נישאת לשוק בלא חליצה יש בכך רק איסור לאו, \u0003לא חששו\u0004 למיעוט וסמכו על החזקה.","\u0003אמר רבא\u0004 כנגד נימוק זה: \u0003מכדי, הא דאורייתא והא דאורייתא\u0004 \u0005[הרי זה מן התורה וזה מן התורה] —\u0006 \u0003מה לי איסור כרת מה לי איסור לאו,\u0004 שאם הדבר אסור מן התורה, אין מקום להבדיל בין איסור חמור ואיסור קל?! \u0003אלא אמר רבא:\u0004 יש לדחות מה שאמרנו, ולומר:"],["\u0003רישא\u0004 \u0005[\u0006ב\u0005ראש\u0006 המשנה\u0005]\u0006 במקרה הראשון, ה\u0003חזקה\u0004 של אותה אשה שהיא זקוקה \u0003לייבום, ו\u0004אם הולכים אחר \u0003רובא\u0004 \u0005[הרוב],\u0006 הרי רוב הנשים מתעברות ויולדות, ומן הסתם ילדה הצרה, והיבמה מותרת \u0003לשוק,\u0004 להינשא לכל אדם. \u0003ו\u0004בדרך כלל \u0003חזקה לא עדיף כי רובא\u0004 \u0005[אינה עדיפה\u0006 ותקפה \u0005כמו הרוב]\u0006 וגדול כח הרוב מכח החזקה, והיתה צריכה להיות מותרת מיד, \u0003ו\u0004אולם \u0003אייתי מיעוטא\u0004 \u0005[הבא\u0006 את \u0005המיעוט]\u0006 של הנשים ש\u0003מפילות, סמוך\u0004 (צרף), \u0003לחזקה, והוה ליה פלגא ופלגא\u0004 \u0005[והרי הוא\u0006 כ\u0005מחצה על מחצה]\u0006 שגורע מכוח הרוב וכעת הוא שווה לחזקה, ולכן, \u0003לא תנשא ולא תתייבם.\u0004","ואילו \u0003סיפא\u0004 \u0005[\u0006ב\u0005סוף],\u0006 במקרה השני, על פי ה\u0003חזקה\u0004 היא מותרת \u0003לשוק,\u0004 שהרי לא היו לבעלה אחים מתחילה, \u0003ו\u0004גם \u0003רובא\u0004 \u0005[הרוב]\u0006 לגבי הסיכוי שתלד החמות בן, גם הוא נוטה להתירה \u0003לשוק,\u0004 שהרי ייתכן שתפיל או שתלד בת, \u0003ו\u0004אם כן \u0003הוי ליה\u0004 \u0005[הרי הם]\u0006 ה\u0003זכרים מיעוטא דמיעוטא\u0004 \u0005[מיעוט ש\u0006ב\u0005מיעוט],\u0006 כלומר, רק מיעוט כנגד שיקול של רוב וחזקה, \u0003ומיעוטא דמיעוטא\u0004 \u0005[ו\u0006ל\u0005מיעוט ש\u0006ב\u0005מיעוט]\u0006 \u0003לא חייש\u0004 \u0005[חשש]\u0006 גם \u0003ר' מאיר\u0004 ומותרת להינשא.","שנינו במשנה שהאשה שהלכו בעלה וצרתה למדינת הים — \u0003לא תנשא ולא תתייבם\u0004 עד שתדע אם מעוברת היא צרתה. ושואלים: \u0003ולעולם\u0004 לא תינשא ולא תתייבם, כלומר, והרי יכולה היא לחלוץ מפני הספק ולהינשא!","\u0003אמר זעירי: לעצמה,\u0004 כדי שהיא כשלעצמה תהיה מותרת להינשא — צריכה להמתין \u0003שלשה חדשים\u0004 גם אחרי שחלצה, כדין כל אשה שצריכה להמתין שלושה חודשים אחר מות בעלה לפני שנישאת לאחר, ו\u0003לחברתה,\u0004 מפני החשש שמא צרתה מעוברת — תמתין \u0003תשעה\u0004 חודשים מפני שאם צרתה היתה מעוברת ודאי ילדה כבר, \u0003וחולצת\u0004 אז \u0003ממה נפשך\u0004 (לפי כל שיקול שתרצה): שאם בינתיים ילדה הצרה — הרי אינה צריכה כלל חליצה, ורשאית היא להינשא לכל מי שתרצה, ואף אם לא ילדה הצרה, ואשה זו זקוקה לייבום — הרי היא נפטרת בחליצה. ואינה יכולה לחלוץ קודם, כי חליצה כשהיבמה מעוברת — אינה פוטרת.","\u0003ר' חנינא אמר: לעצמה,\u0004 כלומר, בגלל איסור של עצמה — צריכה להמתין \u0003שלשה\u0004 חודשים, ואילו \u0003לחברתה\u0004 צריכה להמתין \u0003לעולם,\u0004 כלומר, עד שיוודע הדבר אם היה לה וולד. ושואלים: \u0003ותחלוץ ממה נפשך.\u0004 כלומר, שהרי בכל מקרה שיהיה, אחרי תשעה חודשים יכולה לחלוץ!","ומסבירים: \u0003אביי בר אבין ור' חנינא בר אבין אמרי תרוייהו\u0004 \u0005[אמרו שניהם]:\u0006 \u0003גזירה שמא יהא ולד\u0004 שנולד \u0003בן קיימא,\u0004 ויתברר שהחליצה שחלצה לא היתה חליצה כלל, שהרי היתה פטורה מייבום, \u0003ונמצא\u0004 ש\u0003אתה מצריכה כרוז\u0004 להודיע שאשה זו כשרה \u0003לכהונה,\u0004 שכן אנשים לא יידעו שחליצתה אינה חליצה, ויאסרו אותה לכהונה.","ושואלים: \u0003וליצרכה\u0004 \u0005[ושנצריך אותה]\u0006 כרוז כזה כשיתברר שהולד בן קיימא? ומשיבים: יש לחשוש \u0003דלמא איכא דהוי\u0004 \u0005[שמא יש\u0006 בין האנשים כזה \u0005שהיה]\u0006 \u0003ב\u0004זמן ה\u0003חליצה ולא הוי\u0004 \u0005[היה]\u0006 \u0003ב\u0004זמן ה\u0003הכרזה, ו\u0004כשנישאת אותה אשה לכהן \u0003אמרי\u0004 \u0005[אומרים]\u0006 כמסקנה מוטעית ממה שידוע להם: \u0003קשרו\u0004 \u0005[מתירים]\u0006 \u0003חלוצה לכהן.\u0004","ודנים עוד בנושא זה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 אמרה אשה: \u0003\"ניתן\u0004 (נולד) \u0003לי בן במדינת הים\",\u0004 והוסיפה \u0003ואמרה: \"מת בני ואחר כך בעלי\" — נאמנת\u0004. ואם אמרה: \u0003\"מת בעלי ואחר כך\u0004 מת \u0003בני\" — אינה נאמנת\u0004 על סדר אירוע הדברים, \u0003וחוששין\u0004 מכל מקום \u0003לדבריה\u0004 שמת בעלה בלא ולד, \u0003וחולצת ולא מתייבמת. ו\u0004אומרים: אם כן, מחמת טעם זה שאמרנו לגבי כרוז לכהונה,","\u0003ליחוש דלמא אתו\u0004 \u0005[שנחשוש שמא יבואו]\u0006 לבסוף \u0003עדים ואמרי כדקאמרה\u0004 \u0005[ויאמרו כמו ש\u0006היא \u0005אמרה]\u0006 שכך היה סדר אירוע הדברים, ואם כן לא היתה זקוקה כלל לחליצה, \u0003ונמצא אתה מצריכה כרוז לכהונה\u0004 כדי להתירה, הואיל וחליצתה לא היה בה ממש, ובכל זאת נאמר במשנה שחולצת! \u0003אמר רב פפא:\u0004 מדובר שם \u0003בגרושה\u0004 שלפני שנשאה בעלה זה, נתגרשה פעם מנישואין קודמים, שבין כך ובין כך היא פסולה לכהונה. \u0003רב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא אמר, באמרה\u0004 \u0005[ב\u0006שהיא \u0005אומרת]:\u0006 \u0003\"אני והוא נחבאנו\u0004 לבדנו \u0003במערה\"\u0004 ולא היו שם עדים אחרים, וכיון שאין להניח שמא יבואו עדים לאחר מכן, חולצת.","היו \u0003שתי יבמות,\u0004 נשים הנשואות לשני אחים, ובאו והעידו, \u0003זו אומרת: \"מת בעלי\", וזו אומרת: \"מת בעלי\"\u0004 — אף על פי שכל אחת מהן נאמנת לגבי עצמה, וסומכים עליה שמת בעלה, מכל מקום \u0003זו אסורה\u0004 להינשא \u0003מפני בעלה של זו\u0004 האחרת שמא חי הוא, והיא זקוקה לו לייבום, \u0003וזו אסורה מפני בעלה של זו\u0004 מאותו טעם. ואף שכל אחת מהן נאמנת לגבי מות בעלה־שלה — אין היא נאמנת להתיר את השניה, שהרי אין אשה נאמנת להעיד על גיסתה.","אם \u0003לזו\u0004 (לאחת מהן) יש \u0003עדים\u0004 שמת בעלה, \u0003ולזו אין עדים,\u0004 במצב כזה, \u0003את שיש לה עדים\u0004 — \u0003אסורה\u0004 להינשא, שהרי אין עדים על מותו של יבמה, וצריכה להמתין שמא יבוא, \u0003ואת שאין לה עדים\u0004 — \u0003מותרת,\u0004 שכן היא מותרת על פי עדות עצמה שמת בעלה, ואינה צריכה להמתין ליבם — שהרי כבר העידו העדים על יבמה שמת. היו \u0003לזו בנים ולזו אין בנים, את שיש לה בנים — מותרת,\u0004 שהרי היא עצמה נאמנת להעיד על בעלה, וכיון שיש לה בנים אינה זקוקה ליבם, \u0003ואת שאין לה בנים — אסורה,\u0004 שהרי עליה להמתין ליבם.","ולענין המקרה הראשון בשתי יבמות שהעידו כל אחת על מות בעלה, אם היו שם אחים נוספים ו\u0003נתייבמו\u0004 שתי אלה לאותם האחים, \u0003ומתו היבמין\u0004 הללו — הרי הן שוב \u0003אסורות להנשא,\u0004 שהרי החשש הראשון שמא חי יבמה של כל אחת מהן לא נסתלק עדיין. \u0003ר' אלעזר אומר: הואיל והותרו\u0004 נשים אלה להינשא \u0003ליבמין,\u0004 שהרי קיבלנו את דברי כל אחת מהן שמת בעלה — \u0003הותרו\u0004 מאז \u0003לכל אדם,\u0004 שהרי לפי צירוף דברי שתיהן מותרות הן לכל אדם.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 אם \u0003לזו,\u0004 לאחת משתי היבמות הללו, יש \u0003עדים\u0004 שמת בעלה \u0003ו\u0004גם יש לה \u0003בנים, ולזו,\u0004 השניה, \u0003לא עדים ולא בנים — שתיהן מותרות.\u0004 שזו שיש לה בנים הלא אינה זקוקה לייבום, וזו, שאין לה בנים — יכולה לסמוך על עדי היבמה האחרת שהיבם מת.","שנינו במשנה: \u0003נתייבמו\u0004 שתיהן, \u0003ומתו היבמין — אסורין\u0004 (אסורות) \u0003להנשא\u0004 מחמת החשש הראשון שמא עדיין הראשון חי. \u0003ר' אלעזר אומר: הואיל והותרו ליבמין — הותרו\u0004 כבר \u0003לכל אדם.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אלעזר?\u0004 האם \u0003משום דקסבר\u0004 \u0005[שהוא\u0006 \u0005סבור]\u0006 בכלל ש\u0003צרה מעידה\u0004 (נאמנת להעיד) \u0003לחברתה\u0004 שמת בעלה, וכן כל חמש הנשים יכולות להעיד זו לזו, \u0003או דלמא\u0004 \u0005[שמא]\u0006 הטעם הוא \u0003משום\u0004 ש\u0003היא לא מקלקלא נפשה\u0004 \u0005[מקלקלת\u0006 ל\u0005עצמה],\u0006 שאמנם היא חשודה לשקר ולומר שמת הבעל כדי לקלקל לחברתה, אבל כאשר היא בעצמה נישאת, הרי זה מוכיח שדבריה היו דברי אמת, ויש לסמוך על כך גם לגבי צרתה.","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]\u0006 על ידי בירור הטעם הזה?"],["\u0003לאנסובי\u0004 \u0005[להשיא]\u0006 את ה\u0003צרה מקמי דידה\u0004 \u0005[לפניה],\u0006 אם באה אשה ומעידה שמת בעלה ויש לה צרה, האם אפשר לסמוך על עדות זו ולהשיא את הצרה לפני שהיא עצמה נישאת. וצדדי השאלה: \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003צרה מעידה לחברתה,\u0004 אם כן \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא אינסיב\u0004 \u0005[נישאה]\u0006 בעצמה — \u0003מנסבינן לה לצרה\u0004 \u0005[משיאים אנו את צרתה],\u0006 שכיון שמאמינים לה לגבי עצמה — מאמינים גם לענין צרתה. אבל \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהטעם הוא \u0003משום\u0004 ש\u0003היא לא מקלקלא נפשה\u0004 \u0005[מקלקלת\u0006 ל\u0005עצמה],\u0006 הרי אם \u0003אינסיב\u0004 \u0005[נישאה\u0006 היא\u0005] —\u0006 \u0003מנסבינן לה\u0004 \u0005[משיאים אותה]\u0006 את ה\u0003צרה, אי\u0004 \u0005[אם]\u0006 \u0003לא אינסיב\u0004 \u0005[נישאה] —\u0006 \u0003לא מנסבינן לה\u0004 \u0005[אין משיאים אותה],\u0006 שמא התכוונה רק לשקר ולקלקל לצרתה.","ואם כן, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו, ממה ששנינו ש\u0003ר' אלעזר אומר: הואיל והותרו ליבמין — הותרו לכל אדם.\u0004 ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שהטעם הוא ש\u0003היא לא מקלקלא נפשה\u0004 \u0005[מקלקלת\u0006 ל\u0005עצמה] —\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 הטעם \u0003דכי אינסיב\u0004 \u0005[שכאשר\u0006 היא \u0005נישאת],\u0006 \u0003מנסבינן לה\u0004 \u0005[משיאים אותה\u0006 את הצרה\u0005],\u0006","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהטעם הוא \u0003משום\u0004 ש\u0003צרה מעידה לחברתה — אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא אינסיב\u0004 \u0005[נישאה]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 היו צריכים להתיר את הגיסה, ומדוע מוזכר כאן שהתייבמו! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' אלעזר משום דאינסיב\u0004 \u0005[ש\u0006כבר \u0005נישאה]\u0006 \u0003הוא ו\u0004היא \u0003לא מקלקלא נפשה\u0004 \u0005[מקלקלת\u0006 ל\u0005עצמה].\u0006","ודוחים: אפשר לומר כי \u0003ר' אלעזר לדבריהם\u0004 לפי שיטתם של חכמים \u0003קאמר להו\u0004 \u0005[אמר להם],\u0006 וכך יש להבין: \u0003לדידי\u0004 \u0005[לשיטתי,\u0006 לדעתי\u0005],\u0006 \u0003צרה מעידה לחברתה, ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא אינסיב\u0004 \u0005[נישאה] —\u0006 \u0003מנסבינן לה\u0004 \u0005[משיאים אותה\u0006 את הצרה\u0005],\u0006 \u0003אלא\u0004 אף אתם \u0003לדידכו אודו\u0004 \u0005[לשיטתכם הודו]\u0006 \u0003לי מיהת\u0004 \u0005[לפחות]\u0006 \u0003דהיכא דאינסיב, מנסבינן לה\u0004 \u0005[שבמקום שנישאה, משיאים אותה\u0006 את הצרה\u0005]\u0006 \u0003משום\u0004 ש\u0003היא לא מקלקלא נפשה\u0004 \u0005[מקלקלת\u0006 ל\u0005עצמה].\u0006 \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שאינם מקבלים טענה זו, אומרים כי \u0003\"תמות נפשי עם פלשתים\"\u0004 (שופטים טז, ל) \u0003הוא דקעבדה\u0004 \u0005[שעושה],\u0006 שנוח לה לקלקל לעצמה, ובלבד שתקלקל בכך את צרתה.","ומציעים שוב, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 פתרון ממה ששנינו: \u0003האשה שהלכה היא ובעלה למדינת הים ובאה ואמרה: \"מת בעלי\" — תנשא ותטול כתובתה וצרתה אסורה. ר' אלעזר אומר: הואיל והותרה היא — הותרה נמי\u0004 \u0005[גם כן]\u0006 \u0003צרתה.\u0004 ומכאן שר' אלעזר סבור שצרה מעידה לחברתה אפילו אם היא עדיין לא נישאה! ודוחים: אין זו ראיה גמורה, \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן את הלשון כך: \u0003הואיל והותרה ו\u0004כבר \u0003נשאת.\u0004","ושואלים לגוף הענין: אם טעמו של ר' אלעזר הוא משום שאינה מקלקלת לעצמה, מדוע סומכים על נישואיה של זו שהעידה כדי להתיר את צרתה, \u0003וליחוש דלמא בגיטא אתאי\u0004 \u0005[ונחשוש שמא\u0006 אותה אשה שהעידה, \u0005בגט באה]\u0006 שגרש אותה בעלה, ולכן מה שנישאה לאחר הוא משום הגט הזה, \u0003והאי דקאמרה הכי\u0004 \u0005[וזה ש\u0006היא \u0005אומרת כך]\u0006 שמת הבעל — \u0003לקלקלא\u0004 \u0005[לקלקל]\u0006 \u0003לצרה היא מיכוונה\u0004 \u0005[מתכוונת].\u0006 שכן, היא עצמה יכולה להינשא ואיננה חוששת כלל, שהרי גרושה היא, וגם אם יבוא הבעל — לא יפגע בה הדבר, ואילו צרתה לא תהא לה תקנה!","ומשיבים: אכן, \u0003אי דאינסיב\u0004 \u0005[אם\u0006 מדובר \u0005שנישאה]\u0006 \u0003לישראל\u0004 שגם גרושה מותרת לו — \u0003הכי נמי\u0004 \u0005[כך\u0006 הוא \u0005גם כן],\u0006 ויש חשש שמשקרת ולא תותר הצרה. אלא \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים],\u0006 \u0003דאינסיב\u0004 \u0005[שנישאה]\u0006 \u0003לכהן\u0004 האסור בגרושה, ולכן ודאי אמת אמרה שאלמנה היא, שלא תקלקל לעצמה בנישואי איסור.","\u0003אין מעידין\u0004 על איש שמת \u0003אלא\u0004 אם כן יכולים להעיד \u0003על פרצוף פנים עם החוטם,\u0004 שרק אם ראו את פניו בשלימות, יכולים לזהותו בוודאות. ו\u0003אף על פי שיש סימנין בגופו ובכליו\u0004 — אין סומכים עליהם לשם זיהוי. ועוד: \u0003אין מעידין\u0004 על אדם שמת \u0003אלא עד שתצא נפשו\u0004 ממש. \u0003ואפילו ראוהו\u0004 שהוא \u0003מגוייד\u0004 (חתוך ופצוע), או \u0003צלוב\u0004 (תלוי על הצלב), \u0003ו\u0004כן אם \u0003החיה אוכלת בו\u0004 — אין מעידים עליו שמת. ועוד: \u0003אין מעידין אלא\u0004 אם ראו אותו \u0003עד שלשה ימים\u0004 לאחר המוות ולא יותר, שאז מתחיל הריקבון, ושמא השתנתה צורתו.","\u0003ר' יהודה בן בבא אומר:\u0004 אין לקבוע כלל בדבר כיון ש\u0003לא כל האדם ולא כל המקום ולא כל השעות שוין,\u0004 שתהליך שינוי הצורה אינו אחיד, ולא בכל מקרה הוא מתרחש באותו פרק זמן.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 ראו העדים \u0003פדחת\u0004 (מצח) \u0003ולא פרצוף פנים,\u0004 או \u0003פרצוף פנים ולא פדחת — אין מעידין\u0004 שהכירו אותו, \u0003עד שיהו\u0004 רואים את \u0003שניהם, עם החוטם. אמר אביי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב כהנא: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המלמד על כך — שנאמר: \u0003\"הכרת פניהם ענתה בם\"\u0004 (ישעיה ג, ט) ומכאן שרק על פי קלסתר הפנים אפשר להכיר אדם בוודאות.","וכעין ראיה לדבר מספרים: \u0003אבא בר מרתא\u0004 ש\u0003הוא\u0004 קרוי גם \u0003אבא בר מניומי\u0004 על שם אביו, \u0003הוה מסקי ביה דבי ריש גלותא זוזי\u0004 \u0005[היו נושים בו\u0006 בני \u0005בית ראש הגולה כסף],\u0006 וכיון שהם היו אנשים אלימים, חשש להיראות בפניהם. מה עשה — \u0003אייתי קירא, דבק בבלייתא, דבק באפותיה\u0004 \u0005[הביא שעווה, הדביק\u0006 אותה \u0005על בלאות\u0006 בד, \u0005הדביק על מצחו\u0006 את הכל\u0005]\u0006 כדי לשנות את מראהו. \u0003חלף קמייהו\u0004 \u0005[עבר לפניהם]\u0006 \u0003ולא בשקרוהו\u0004 \u0005[הכירוהו],\u0006 ומכאן ראיה עד כמה משתנים פניו של אדם על ידי שינוי במצחו.","שנינו במשנה שאין מעידים על אדם \u0003אף על פי שיש סימנין\u0004 בגופו ובכליו. ושואלים: \u0003למימרא\u0004 \u0005[\u0006האם יש \u0005לומר]\u0006 להסיק מכאן ש\u0003סימנין לאו דאורייתא\u0004 \u0005[אינם מן התורה],\u0006 כלומר, ההסתמכות על סימנים אינה משום שהתורה קבעה שזוהי דרך של זיהוי אמיתי, אלא שבכמה עניינים אמרו חכמים מפני תקנת הבריות שאפשר לסמוך על כך, ולעומת זאת הם החמירו בעדות אשה שלא לסמוך על סימנים.","\u0003ורמינהי\u0004 \u0005[ומטילים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: שליח שהביא גט לאשה, ואיבד את הגט, אם \u0003מצאו קשור בכיס ו\u0004כן \u0003בארנקי\u0004 (ארנק) \u0003ו\u0004כן \u0003בטבעת או שנמצא\u0004 מאוחר יותר \u0003בין כליו\u0004 (בגדיו), \u0003אפילו\u0004 מצאו \u0003ל\u0004אחר \u0003זמן מרובה — כשר.\u0004 וסומכים על הסימנים של הכיס או הארנק ומתירים את קשר האישות שמן התורה על ידי גט זה. משמע איפוא שסומכים על סימנים דבר תורה!","\u0003אמר אביי: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 דעת \u0003ר' אליעזר בן מהבאי, הא רבנן\u0004 \u0005[זו\u0006 דעת \u0005חכמים].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מעידין\u0004 על זהות אדם \u0003על\u0004 פי \u0003השומא\u0004 (יבלת) שהיתה בו במקום מסויים. \u0003ר' אליעזר בן מהבאי אומר: מעידין. מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה\u0006 הם \u0005חלוקים],\u0006 \u0003דמר\u0004 \u0005[שחכם זה,\u0006 ר' אליעזר בן מהבאי\u0005]\u0006 \u0003סבר\u0004 כי \u0003סימנין דאורייתא\u0004 \u0005[מן התורה]\u0006 הם, ולכן אפשר לסמוך על הסימן של השומא, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים\u0005]\u0006 כי \u0003סימנין\u0004 כאמצעי זיהוי הם רק \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 ולכן אין סומכים על סימן זה כדי להתיר איסור מן התורה.","\u0003אמר רבא:\u0004 יש לדחות, \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003סימנין\u0004 הם \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 המחלוקת היא בבעיה אחרת, ו\u0003ב\u0004שאלה האם \u0003שומא מצויה בבן גילו\u0004 (באדם הדומה לו מאוד) \u0003קמיפלגי\u0004 \u0005[חלוקים הם].\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 חכמים\u0005]\u0006 \u0003סבר: שומא מצויה\u0004 גם \u0003בבן גילו,\u0004 ולכן אין זה נחשב כסימן מובהק, \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' אליעזר בן מהבאי\u0005]\u0006 \u0003סבר: אינה מצויה בבן גילו\u0004 ולכן הוא סימן מובהק.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 באופן אחר: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004שאלה אם \u0003שומא העשויה להשתנות\u0004 במראיתה ובגודלה \u0003לאחר מיתה קמיפלגי\u0004 \u0005[חלוקים הם].\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 חכמים\u0005]\u0006 \u0003סבר: עשויה להשתנות לאחר מיתה,\u0004 ולכן יש לחשוש ששומא זו שראו היתה שונה בחיי האיש ואין זה האיש שהכירו. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' אליעזר\u0005]\u0006 \u0003סבר: אינה עשויה להשתנות לאחר מיתה.\u0004 עד כאן גירסה אחת של הדיון בבעיה זו.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 ש\u0003אמר רבא: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003סימנין\u0004 שיש לסמוך עליהם הם \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 אלא שסימנים אלה הם סימנים רגילים, שאינם מובהקים ומיוחדים ביותר, ולכן יש לפקפק אם הם הוכחה גמורה, אבל בסימן מובהק ומיוחד סומכים להתיר אף איסור מן התורה. \u0003והכא\u0004 \u0005[וכאן],\u0006 חכמים ור' אליעזר בן מהבאי, \u0003ב\u0004שאלה האם \u0003שומא\u0004"],["\u0003סימן מובהק\u0004 הוא \u0003קא מיפלגי\u0004 \u0005[חלוקים\u0006 \u0005הם].\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' אליעזר\u0005]\u0006 \u0003סבר\u0004 כי שומא \u0003סימן מובהק\u0004 היא, ולכן אפשר לסמוך עליה אפילו מן התורה. \u0003ומר\u0004 \u0005[וחכם\u0006 זה, חכמים\u0005]\u0006 \u0003סבר לאו\u0004 \u0005[\u0006ש\u0005לא]\u0006 \u0003סימן מובהק\u0004 היא.","ושואלים: \u0003ולהך לישנא\u0004 \u0005[ול\u0006פי \u0005לשון זו]\u0006 הראשונה ש\u0003אמר רבא\u0004 כי \u0003סימנין דאורייתא\u0004 \u0005[מן התורה]\u0006 הם, \u0003הא קתני\u0004 \u0005[הרי שנה]\u0006 במשנה \u0003אף על פי שיש סימנין בגופו ובכליו\u0004 — אין סומכים עליהם, משמע שסימנים אינם ראיה מן התורה!","ומשיבים: הכוונה שם היא לסימנים רגילים, שאינם אלא ראיה קלושה. ואותם סימנים שאמרו לגבי \u0003גופו\u0004 המדובר בסימן כללי, כגון שהיה גופו \u0003ארוך\u0004 או \u0003גוץ.\u0004 ולגבי \u0003כליו\u0004 אין סומכים על סימניהם — \u0003דחיישינן\u0004 \u0005[שאנו חוששים]\u0006 \u0003לשאלה\u0004 (להשאלה) שמא השאיל את בגדיו לאחר, ואותו שואל הוא שמת. ושואלים: \u0003ואי חיישינן\u0004 \u0005[ואם אנו חוששים]\u0006 \u0003לשאלה\u0004 (להשאלה), אם כן בדיני השבת אבידה, \u0003חמור\u0004 על פי \u0003סימני אוכף, היכי מהדרינן\u0004 \u0005[איך אנו מחזירים]\u0006 אם אין סימנים בחמור עצמו, ומדוע לא נחשוש שמא שאל בעל החמור את האוכף מאחר?","ומשיבים: \u0003לא שיילי אינשי אוכפא, דמסקיב ליה לחמרא\u0004 \u0005[אין אנשים שואלים אוכף\u0006 מפני \u0005ש\u0006זה \u0005פוצע את החמור],\u0006 שהאוכף צריך להיות עשוי בדיוק כמידת החמור, ולכן אין משתמשים באוכף של חמור אחר, ואין לחשוש כאן לשאילה. ועוד מקשים: שנינו שאם \u0003מצאו\u0004 את הגט שאבד \u0003קשור בכיס\u0004 או \u0003בארנקי\u0004 (ארנק) או \u0003בטבעת,\u0004 סומכים על סימניהם ונותנים את הגט לאשה, ואם כן \u0003היכי מהדרינן\u0004 \u0005[איך אנו מחזירים]\u0006 ואין חוששים שמא השאיל את כליו אלה לאחר?","ומשיבים: אין פה מקום לחשש, כי \u0003טבעת\u0004 אין אדם משאיל כיון ש\u0003חייש לזיופי\u0004 \u0005[\u0006שהוא \u0005חושש לזיוף],\u0006 שכן בטבעת מצויה כרגיל החותמת שלו ואין אדם משאילה לאחר, שמא יזייף ויחתום דברים בשמו. \u0003כיס וארנקי — מנחשי אינשי ולא מושלי\u0004 \u0005[מנחשים\u0006 בהם \u0005אנשים,\u0006 שיש בכך כעין סימן רע, \u0005ואינם משאילים\u0006 אותם\u0005],\u0006 ולכן אין לחשוש לשאלה בכלים אלה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הטעם שאמרו שאין מתירים אדם על פי סימנים של \u0003כליו,\u0004 אין הכוונה לסימנים מובהקים, אלא בדברים כלליים, כגון שהעידו \u0003בחיורי וסומקי\u0004 \u0005[ב\u0006בגדיו שצבעיהם \u0005לבנים ואדומים],\u0006 שזה אינו סימן.","שנינו במשנה: \u0003ואפילו ראוהו מגוייד\u0004 (חתוך ופצוע) — אין מעידים עליו שמת. ושואלים: \u0003למימרא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 מכאן שה\u0003מגוייד חיי\u0004 \u0005[חי]\u0006 אחר כך? \u0003ורמינהי\u0004 \u0005[ומטילים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003אדם אינו מטמא\u0004 בטומאת מת \u0003עד שתצא נפשו\u0004 ממש, \u0003אפילו\u0004 היה \u0003מגוייד, ואפילו גוסס.\u0004 ומכאן נדייק: \u0003טמויי\u0004 \u0005[לטמא]\u0006 עדיין הוא \u0003לא מטמא,\u0004 לפי שיש בו עוד חיים, \u0003הא מיחייא\u0004 \u0005[הרי לחיות] —\u0006 \u0003לא חיי\u0004 \u0005[איננו חי\u0006 עוד\u0005]!\u0006","\u0003אמר אביי: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003ר' שמעון בן אלעזר, הא\u0004 \u0005[זו]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעידין על המגוייד\u0004 שהוא כמת, \u0003ואין מעידין על הצלוב\u0004 (התלוי על צלב). \u0003ר' שמעון בן אלעזר אומר: אף על המגוייד אין מעידין, מפני שיכול לכוות,\u0004 שעל ידי כוויה פעמים אפשר לגרום שתיפסק שתיתת הדם, \u0003ו\u0004יוכל \u0003לחיות.\u0004","ומקשים: \u0003ומי מצית לאוקומי\u0004 \u0005[והאם יכול אתה להעמיד\u0006 לפרש את משנתנו\u0005]\u0006 \u0003כר' שמעון בן אלעזר? והא קתני סיפא\u0004 \u0005[והרי שנה\u0006 ב\u0005סופה],\u0006 בהמשכה של המשנה: \u0003מעשה בעסיא באחד ששילשלוהו לים\u0004 על ידי חבל לצלול בו, \u0003ו\u0004אחר כך כאשר משכו את החבל חזרה \u0003לא עלתה בידם אלא רגלו,\u0004 ולא ידעו אם טבע ומת, או נמלט, \u0003ואמרו חכמים:\u0004 אם הרגל היתה חתוכה \u0003מן הארכובה\u0004 (הברך) \u0003ולמעלה — תנשא,\u0004 שכן אחרי פציעה כזו ודאי אין אפשרות שימשיך לחיות, ואם הרגל שהועלתה היתה חתוכה רק \u0003מן הארכובה ולמטה — לא תנשא.\u0004 משמע שאפילו במגוייד באופן כזה, יש להניח שמת, ואם דעת ר' שמעון בן אלעזר היא — מדוע אין הוא אומר שחוששים שהוא חי אפילו אם הרגל היתה חתוכה מן הארכובה ולמעלה?","ומשיבים: \u0003שאני מיא דמרזו\u0004 \u0005[שונים\u0006 הם \u0005מים ש\u0006הם \u0005מגבירים את]\u0006 ה\u0003מכה,\u0004 הפצע, ואת הכאב, ומאחר שהיה במים, יש להניח אף בפציעה כזו שמת כבר.","ושואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה: לדידי חזי לי ההוא טייעא\u0004 \u0005[אני\u0006 עצמי \u0005ראיתי ערבי אחד]\u0006 \u0003דשקיל ספסירא וגיידיה לגמליה\u0004 \u0005[שלקח סייף וחתך את גמלו]\u0006 \u0003ולא אפסיקתיה לנערותיה\u0004 \u0005[הפסיק\u0006 הגמל \u0005לנעור]\u0006 ומת מיד. משמע שהגיוד הורג לחלוטין ואין לו תקנה! \u0003אמר אביי: ההיא כחישא הויא\u0004 \u0005[אותו\u0006 גמל \u0005כחוש היה]\u0006 וחלש, ולכן מת מיד.","\u0003רבא אמר:\u0004 במשנה מדובר כשהיה מגוייד \u0003בסכין מלובנת, ודברי הכל\u0004 אין מעידים עליו שמת בגלל הפציעה, שהרי בגלל ליבון הסכין נסגר הפצע.","נאמר במשנה שאפילו ראוהו... \u0003והחיה אוכלת\u0004 בו — אין מעידים עליו שמת. \u0003אמר רב יהודה אמר שמואל: לא שנו אלא\u0004 שראו שאוכלת \u0003ממקום שאין נפשו יוצאה\u0004 על ידי פציעה שם, כגון שאוכלת את ידו או את רגלו, \u0003אבל\u0004 אם אוכלת \u0003ממקום שנפשו יוצאה,\u0004 כגון מוחו או לבו — \u0003מעידין\u0004 עליו.","\u0003ואמר רב יהודה אמר שמואל: שחט בו\u0004 באדם אחד \u0003שנים\u0004 מן ה\"סימנים\", קנה וושט, \u0003או רוב שנים, וברח\u0004 הנשחט ולא ראוהו עוד — \u0003מעידין\u0004 עליו שמת.","ומקשים: \u0003איני\u0004 \u0005[ו\u0006כי \u0005כך הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר שמואל: שחט בו שנים או רוב שנים ורמז\u0004 הנשחט \u0003ואמר: \"כתבו גט לאשתי\" — הרי אלו יכתבו ויתנו.\u0004 וכיון שרק אדם חי יכול לתת גט, משמע שהנשחט נחשב כחי! ומשיבים: ודאי \u0003חי הוא\u0004 עדיין באותה שעה, \u0003ו\u0004אולם \u0003סופו למות\u0004 בוודאי, ולכן אפשר לפי שעה לכתוב גט בשבילו כחי, אבל אפשר גם להעיד עליו שהוא מת כעבור זמן מה.","ושואלים: \u0003אלא מעתה,\u0004 אם רואים אנו זאת כהריגה, \u0003יהא גולה על ידו\u0004 אם שחט אדם בשגגה. \u0003אלמה תניא\u0004 \u0005[מדוע שנויה\u0006 ברייתא\u0005]:\u0006 \u0003שחט שנים או רוב שנים\u0004 בשגגה — \u0003הרי זה אינו גולה,\u0004 לפי שאין זו נחשבת להריגה! ומשיבים: \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 נאמר \u0005על כך]\u0006 \u0003אמר רב הושעיא: חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא הרוח בלבלתו\u0004 ומחמת הרוח מת לבסוף, ולא מחמת הפציעה, לכן אינו חייב גלות. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003שמא איהו\u0004 \u0005[הוא],\u0006 הנשחט עצמו,"],["\u0003קירב מיתתו\u0004 כגון שהתנועע בחוזקה, וגרם על ידי כך נזק לעצמו. ולכן אין השוחטו גולה. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם],\u0006 בין הטעמים של רוח, או שהוא קירב מיתתו?","ומסבירים: כגון \u0003דשחטיה בביתא דשישא ופרכיס\u0004 \u0005[ששחטו בבית של שיש\u0006 הסגור מכל צד ואין בו רוח \u0005ופירכס]\u0006 הרבה מעצמו, שאם הרוח היא הגורמת — הרי לא היתה שם רוח, אבל אם הפירכוס גורם — הרי פירכס. \u0003אי נמי\u0004 \u0005[או גם כן]:\u0006 \u0003דשחטיה בברא\u0004 \u0005[ששחטו בחוץ]\u0006 \u0003ולא פרכיס\u0004 \u0005[פירכס]\u0006 כלל, שאז חוששים לרוח, ולא למעשה עצמו.","קבעו חכמים במשנה כלל, שאין מעידים אלא בתוך שלושה ימים למוות, ו\u0003ר' יהודה\u0004 בן בבא \u0003אומר: לא כל\u0004 המקרים שוים, לענין הזמן. \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005],\u0006 שאלה זו: \u0003ר' יהודה בן בבא לקולא פליג\u0004 \u0005[להקל חלק],\u0006 לומר שיש מקרים שגם אחר שלושה ימים אפשר להעיד, \u0003או לחומרא פליג\u0004 \u0005[להחמיר חלק],\u0006 שפעמים אף בפחות משלושה ימים אי אפשר להעיד.","ומציעים פתרון, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה: \u0003דההוא גברא\u0004 \u0005[שאדם אחד]\u0006 ש\u0003טבע ב\u0004מקום שנקרא \u0003כרמי, ואסקוהו\u0004 \u0005[והוציאו אותו]\u0006 ליד המקום הקרוי \u0003בי הדיא לבתר תלתא יומין\u0004 \u0005[לאחר שלושה ימים],\u0006 \u0003ואנסבה\u0004 \u0005[והשיאה]\u0006 \u0003רב דימי מנהרדעא לדביתהו\u0004 \u0005[את אשתו]\u0006 שסמך על זיהויו לאחר שלושה ימים. \u0003ותו\u0004 \u0005[ועוד]:\u0006 \u0003ההוא גברא דאטבע בדגלת ואסקוהו אגישרא\u0004 \u0005[אדם אחד שטבע בחידקל והעלו אותו על הגשר]\u0006 של \u0003שביסתנא, ואנסבה\u0004 \u0005[והשיאה]\u0006 \u0003רבא לדביתהו\u0004 \u0005[את\u0006 \u0005אשתו]\u0006 \u0003אפומא דשושביני לבתר\u0004 \u0005[על פי שושביניו\u0006 שהכירו אותו \u0005לאחר]\u0006 \u0003חמשה יומי\u0004 \u0005[ימים].\u0006","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי \u0003לקולא פליג\u0004 \u0005[להקל חלק]\u0006 ר' יהודה בן בבא, אם כן \u0003אינהו דעביד\u0004 \u0005[הם שעשו],\u0006 מה שעשו היה זה \u0003כר' יהודה בן בבא. אלא אי אמרת לחומרא פליג\u0004 \u0005[אם אומר אתה\u0006 ש\u0005להחמיר חלק],\u0006 \u0003אינהו דעביד כמאן\u0004 \u0005[הם שעשו, כמי\u0006 עשו\u0005]?\u0006 שהרי לפי זה אין מי שמתיר ביותר משלושה ימים! ומשיבים: \u0003שאני מיא, דצמתי\u0004 \u0005[שונים\u0006 הם \u0005מים, שמשמרים]\u0006 את הדברים, וצורת הפנים אינה משתנה גם לאחר שלושה ימים.","ותוהים: \u0003והאמרת מיא מרזו\u0004 \u0005[והרי אמרת\u0006 תחילה שה\u0005מים מזיקים]\u0006 ל\u0003מכה!\u0004 ומשיבים: \u0003הני מילי היכא דאיכא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005במקום שיש]\u0006 \u0003מכה,\u0004 פצע, \u0003אבל היכא דליכא\u0004 \u0005[במקום שאין]\u0006 \u0003מכה — מיצמת צמית\u0004 \u0005[\u0006המים \u0005משמרים\u0006 אותו\u0005]\u0006 שלא תתקלקל צורתו. ומעירים: \u0003והני מילי דכי אסקיה חזייה בשעתיה\u0004 \u0005[ודברים אלה\u0006 אמורים \u0005שכאשר הוציאוהו\u0006 מהמים \u0005ראה אותו\u0006 הרואה \u0005באותה שעה],\u0006 \u0003אבל\u0004 אם \u0003אישתהי\u0004 \u0005[השתהה]\u0006 זמן מסויים לאחר הוצאתו מן המים, ודאי \u0003מיתפח תפח\u0004 \u0005[תפח\u0006 ביותר\u0005]\u0006 ואי אפשר להכירו.","\u0003נפל\u0004 אדם \u0003למים\u0004 ולא יצא מהם, \u0003בין שיש להן\u0004 למים \u0003סוף\u0004 הנראה לעין \u0003בין שאין להן סוף — אשתו אסורה\u0004 להינשא, כי אין כאן עדות מוחלטת שמת, ושמא יצא מן המים. \u0003אמר ר' מאיר: מעשה באחד שנפל לבור הגדול, ועלה לאחר שלשה ימים.\u0004 והרי זו הוכחה, שפעמים ניצל אדם, אף שהכל סברו שטבע ומת.","\u0003אמר ר' יוסי: מעשה בסומא\u0004 (בעיוור) \u0003שירד לטבול במערה\u0004 להיטהר, \u0003וירד מושכו\u0004 (האיש שהיה מוביל אותו) גם הוא \u0003אחריו,\u0004 וטבעו במים, \u0003ושהו\u0004 שם \u0003כדי\u0004 הזמן \u0003שתצא נפשם — והשיאו את נשותיהם\u0004 על סמך העובדה שראו שנעלמו במים ולא יצאו. \u0003ושוב מעשה בעסיא, באחד ששלשלוהו לים\u0004 בחבל, \u0003ו\u0004כשמשכו בחבל \u0003לא עלתה בידם אלא רגלו,\u0004 ו\u0003אמרו חכמים:\u0004 אם נחתכה הרגל \u0003מן הארכובה\u0004 (הברך) \u0003ולמעלה — תנשא,\u0004 שודאי מת בעלה, כי הפציעה הזו חמורה ביותר ומי שנפגע כך הרי הוא בגדר טריפה, ובוודאי מת במים. ואם נחתכה \u0003מן הארכובה ולמטה — לא תנשא.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נפל למים, בין\u0004 מים \u0003שיש להם סוף, בין שאין להם סוף — אשתו אסורה,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים:\u0004 אם נפל ל\u0003מים שיש להם סוף — אשתו מותרת, ושאין להם סוף — אשתו אסורה.\u0004","ושואלים, \u0003היכי דמי\u0004 \u0005[כיצד\u0006 הם \u0005בדיוק]\u0006 \u0003מים שיש להם סוף? אמר אביי: כל שעומד\u0004 במקום אחד \u0003ורואה מארבע רוחותיו,\u0004 אלה הם מים שיש להם סוף, וכגון מערה וכדומה. שכן במקום כזה אם יצא אותו אדם ודאי יראוהו כשיצא. אבל אם מקוה המים גדול מזה, ואי אפשר לראות את קצהו מכל צד, חוששים שמא יצא מצד אחר ולא ראוהו.","מסופר: \u0003ההוא גברא\u0004 \u0005[אדם אחד]\u0006 ש\u0003טבע באגמא\u0004 \u0005[באגם]\u0006 של \u0003סמקי,\u0004 מקום בשם זה, \u0003אנסבה\u0004 \u0005[השיאה]\u0006 \u0003רב שילא לדביתהו\u0004 \u0005[את אשתו]\u0006 וזאת על סמך העדים שראו אותו נכנס לאגם, ולא ראו אותו שיצא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לשמואל, תא נשמתיה\u0004 \u0005[בוא\u0006 ו\u0005נחרימנו]\u0006 את רב שילא, על שהורה שלא כדין. \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל לרב: \u0003נשלח ליה ברישא\u0004 \u0005[לו בתחילה]\u0006 ונברר מה היה טעמו, לפני שאנו עושים מעשה.","\u0003שלחו ליה\u0004 \u0005[לו]\u0006 שאלה זו: ראוהו שנפל ל\u0003מים שאין להם סוף,\u0004 האם \u0003אשתו אסורה או מותרת? שלח להו\u0004 \u0005[להם]:\u0006 \u0003אשתו אסורה.\u0004 ושאלו אותו עוד: \u0003ואגמא\u0004 \u0005[והאגם]\u0006 של \u0003סמקי\u0004 מהו — \u0003מים שיש להם סוף או מים שאין להם סוף? שלח להו\u0004 \u0005[להם]\u0006 בתשובה: \u0003מים שאין להם סוף הוא,\u0004 שאין רואים את קצה האגם מכל צד. חזרו ושלחו לו: \u0003ומר, מאי טעמא עבד הכי\u0004 \u0005[ואדוני, מה טעם עשה כך],\u0006 שהשיא את האשה?","ענה להם: \u0003מיטעא טעינא\u0004 \u0005[טעיתי]\u0006 בסברה, \u0003אנא סברי\u0004 \u0005[אני סברתי]:\u0006 מ\u0003כיון דקוו וקיימי\u0004 \u0005[ש\u0006המים \u0005קוויים,\u0006 אגורים, \u0005ועומדים]\u0006 ואינם זורמים, הרי \u0003כמים שיש להם סוף דמי\u0004 \u0005[\u0006הם \u0005נחשבים].\u0006 \u0003ו\u0004אולם, \u0003לא היא\u0004 \u0005[אין\u0006 הדבר \u0005כן],\u0006 \u0003כיון דאיכא גלי\u0004 \u0005[שיש גלים]\u0006 באגם זה — \u0003אימור גלי אשפלו\u0004 \u0005[אמור\u0006 שה\u0005גלים טלטלוהו]\u0006 ושמא לא ראו אותו כשיצא.","וסיכומו של אותו מעשה, \u0003קרי\u0004 \u0005[קרא]\u0006 \u0003שמואל עליה\u0004 \u0005[על]\u0006 \u0003רב\u0004 את הכתוב: \u0003\"לא יאנה לצדיק כל און\"\u0004 (משלי יב, כא), מאחר שלא באה תקלה על ידו, לפי שהמתין רב ולא נידה את רב שילא ולא גרם לו עוול. שהרי רב שילא טעה ולא עבר בזדון על דברי חכמים. \u0003קרי\u0004 \u0005[קרא]\u0006 \u0003רב עליה\u0004 \u0005[על]\u0006 \u0003שמואל\u0004 כתוב זה — \u0003\"ותשועה ברב יועץ\"\u0004 (שם יא, יד), שהרי עצתו של שמואל היא שגרמה לרב להמתין.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר רבי: מעשה בשני בני אדם\u0004 שהיו \u0003מכמרין מכמורין\u0004 (צדים דגים במכמורות) \u0003בירדן, ונכנס אחד מהם למחילה של דגים\u0004 שליד החוף, \u0003ושקעה\u0004 ה\u0003חמה ולא ראה\u0004 את \u0003פתחה של\u0004 ה\u0003מחילה\u0004 ונעלם, \u0003ושהה חברו\u0004 והמתין לו \u0003כדי\u0004 הזמן \u0003שתצא נפשו, ובא\u0004 החבר \u0003והודיע בתוך ביתו\u0004 של האחר שטבע. \u0003למחר,\u0004 ביום, \u0003זרחה\u0004 ה\u0003חמה והכיר\u0004 האיש שהיה במחילה את \u0003פתחה של\u0004 ה\u0003מחילה,\u0004 ויצא החוצה, \u0003ובא ומצא\u0004 שעורכים עליו \u0003הספד גדול בתוך ביתו. אמר רבי\u0004 על כך: \u0003כמה גדולים דברי חכמים, שאמרו\u0004 שמי שנפל ל\u0003מים שיש להם סוף — אשתו מותרת,\u0004 ואם נפל למים \u0003שאין להם סוף — אשתו אסורה.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שעל מקרה כגון זה אתה סומך, אם כן, אף \u0003מים שיש להם סוף נמי ליחוש\u0004 \u0005[גם כן נחשוש]\u0006 שמא \u0003למחילה של דגים\u0004 נכנס אותו אדם ולבסוף יצא! ומשיבים: \u0003במים שיש להם סוף מחילה של דגים לא שכיחא\u0004 \u0005[אינה מצויה].\u0006","\u0003אמר רב אשי: הא דאמרו רבנן\u0004 \u0005[זה שאמרו חכמים]\u0006 ש\u0003מים שאין להם סוף אשתו אסורה — הני מילי באיניש דעלמא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005באדם סתם]\u0006 שאינו ידוע, \u0003אבל צורבא מרבנן\u0004 \u0005[תלמיד חכם] —\u0006 \u0003לא,\u0004 כי \u0003אי דסליק\u0004 \u0005[אם\u0006 היה \u0005עולה\u0006 מן המים\u0005] —\u0006 \u0003קלא אית ליה\u0004 \u0005[קול יש לו]\u0006 והשמועה על הצלתו היתה מתפשטת. ודוחים: \u0003ולא היא\u0004 \u0005[ואינו כן],\u0006 \u0003לא שנא איניש דעלמא ולא שנא צורבא מרבנן\u0004 \u0005[אינו שונה אדם סתם ואינו שונה תלמיד חכם],\u0006 אם ב\u0003דיעבד\u0004 נישאה אשתו — \u0003אין\u0004 \u0005[כן]\u0006 לא תצא, \u0003לכתחלה — לא\u0004 תינשא.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר רבן גמליאל: פעם אחת הייתי מהלך בספינה, וראיתי\u0004 מרחוק \u0003ספינה אחת שנשברה\u0004 וטבעה. \u0003והייתי מצטער על תלמיד חכם שבה, ומנו\u0004 \u0005[ומי\u0006 היה זה\u0005] —\u0006 \u0003ר' עקיבא. וכשעליתי ביבשה\u0004 ראיתי ש\u0003בא, וישב ודן לפני בהלכה. אמרתי לו: בני, מי העלך\u0004 מן המים? \u0003אמר לי: דף\u0004 (קרש) \u0003של\u0004 ה\u0003ספינה נזדמן לי, וכל גל וגל שבא עלי נענעתי לו ראשי,\u0004 הרכנתי את ראשי בפני הגל, ולא שמטוני הגלים מן הקורה, וכך הגעתי לחוף.","\u0003מכאן אמרו חכמים: אם יבואו רשעים על אדם — ינענע לו ראשו,\u0004 כלומר, יכניע עצמו לפי שעה, ולא ילחם בהם, שעל ידי כך יינצל. ואחר מאמר מוסגר זה ממשיכים בדברי רבן גמליאל, \u0003אמרתי באותה שעה: כמה גדולים דברי חכמים, שאמרו: מים שיש להם סוף — מותרת, מים שאין להם סוף — אסורה.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' עקיבא: פעם אחת הייתי מהלך בספינה, וראיתי ספינה אחת שמטרפת\u0004 (שטובעת) \u0003בים, והייתי מצטער על תלמיד חכם שבה, ומנו\u0004 \u0005[ומי\u0006 היה זה\u0005] —\u0006 \u0003ר' מאיר. כשעליתי למדינת קפוטקיא בא וישב ודן לפני בהלכה. אמרתי לו: בני, מי העלך? אמר לי: גל טרדני\u0004 (זרקני) \u0003לחברו, וחברו לחברו, עד שהקיאני ליבשה. אמרתי באותה שעה: כמה גדולים דברי חכמים, שאמרו:\u0004 ש\u0003מים שיש להם סוף — אשתו מותרת, מים שאין להם סוף — אשתו אסורה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נפל\u0004 אדם \u0003ל\u0004תוך \u0003גוב אריות — אין מעידין עליו\u0004 שמת, שמא לא הרגוהו האריות. נפל \u0003לחפורה\u0004 (בור) \u0003מלאה נחשים ועקרבים — מעידין עליו,\u0004 שלא ייתכן שלא נשכוהו ועקצוהו למוות. \u0003ר' יהודה בן בתירא אומר: אף לחפורה מלאה נחשים ועקרבים אין מעידין עליו,\u0004 כי \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006"],["\u0003שמא חבר הוא,\u0004 שיודע קסם או תחבולה לגרום שלא יזיקוהו השרצים. \u0003ו\u0004ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 סבור שאין חוששים לכך, כי \u0003אגב איצצא\u0004 \u0005[הדוחק]\u0006 שהוא נופל עליהם \u0003מזקי ליה\u0004 \u0005[יזיקו לו]\u0006 גם אם כרגיל יכול להשתלט עליהם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נפל לתוך כבשן האש — מעידין עליו\u0004 מיד שמת. נפל \u0003ליורה\u0004 רותחת \u0003מלאה יין ושמן — מעידין עליו. משום ר' אחא אמרו:\u0004 אם נפל ל\u0003של שמן — מעידין עליו, מפני שהוא מבעיר,\u0004 שהרי אגב הנפילה נשפך השמן מתוך היורה על האש, ובכך הוא מבעיר את האש יותר ומגדיל את רתיחת השמן. אבל אם נפל ליורה \u0003של יין — אין מעידין עליו, מפני שהוא מכבה. אמרו לו:\u0004 גם יין, \u0003תחלתו מכבה וסופו מבעיר\u0004 יותר. ואין להניח שהאש כבתה ויצא בשלום.","שנינו במשנה ש\u0003אמר ר' מאיר: מעשה באחד שנפל לבור הגדול\u0004 ויצא לאחר שלושה ימים. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמרו לו לר' מאיר: אין מזכירין מעשה נסים.\u0004 כלומר, מעשה זה נס היה, ואין להביא ממנו ראיה למה שקורה כרגיל בעולם. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003מעשה נסים\u0004 היה בכך? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003לא אכיל\u0004 \u0005[אכל]\u0006 \u0003ולא אישתי\u0004 \u0005[שתה]\u0006 שלושה ימים — \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"וצומו עלי ואל תאכלו ואל תשתו\u0004 שלושת ימים לילה ויום\u0003\"\u0004 (אסתר ד, טז), משמע שהדבר אפשרי!","ומשיבים: \u0003אלא\u0004 היה זה משום ש\u0003לא ניים\u0004 \u0005[ישן]\u0006 במשך שלושה ימים אלה. ש\u0003אמר ר' יוחנן:\u0004 אדם שאמר \u0003\"שבועה שלא אישן שלשה ימים\"\u0004 הרי זה כנשבע על דבר שאי אפשר לקיים — ו\u0003מלקין אותו\u0004 על שנשבע שבועת שוא, \u0003ויישן לאלתר\u0004 \u0005[מיד]\u0006 אם ירצה.","ושואלים: \u0003ו\u0004ל\u0003ר' מאיר מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 מדוע הוא סבור שלא היה זה מעשה נס. \u0003אמר רב כהנא: כיפין על גב כיפין הוו\u0004 \u0005[כיפות על גבי כיפות היו\u0006 בבור\u0005]\u0006 ונשען עליהן וישן. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים — אף על פי כן, \u0003דשישא הוו\u0004 \u0005[של שיש היו]\u0006 ואי אפשר היה להיאחז בהם ולישון. \u0003ור' מאיר\u0004 סבור: \u0003אי אפשר\u0004 ש\u0003לא מסריך וניים פורתא\u0004 \u0005[ייאחז ויישן מעט\u0006 עליהם\u0005],\u0006 ולכן לא היה נס בכך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בבתו של נחוניא חופר־שיחין,\u0004 שהיה חופר בורות מים לצורך הציבור, \u0003שנפלה לבור הגדול, ובאו והודיעו\u0004 על כך \u0003לר' חנינא בן דוסא,\u0004 וביקשו שיתפלל עליה. \u0003שעה ראשונה\u0004 לאחר שהודיעו \u0003אמר להם: שלום\u0004 לה. \u0003שניה, אמר להם: שלום. שלישית, אמר להם: עלתה\u0004 כבר מן הבור.","בסופו של דבר, כשבאה, \u0003אמר לה: בתי, מי העלך\u0004 מן הבור? \u0003אמרה לו: זכר\u0004 (איל) \u0003של רחלים נזדמן לי, וזקן\u0004 אחד היה \u0003מנהיגו\u0004 (מובילו), וזקן זה הוא שהוציא אותי. \u0003אמרו לו\u0004 לר' חנינא בן דוסא: וכי \u0003נביא אתה,\u0004 שיודע אתה לנבא מה קרה? \u0003אמר להם:\u0004 במליצה בלשון הכתוב: \u0003\"לא נביא אנכי ולא בן נביא אנכי\"\u0004 (עמוס ז, יד), \u0003אלא\u0004 מסברה אמרתי: \u0003דבר שהצדיק מתעסק בו\u0004 לחפור בורות לרבים — \u0003יכשל בו זרעו?\u0004 ובוודאי יקרה לה נס ותינצל.","\u0003אמר ר' אבא: אף על פי כן מת בנו\u0004 של ר' נחוניא חופר־שיחין \u0003בצמא\u0004 ולא הגנה עליו זכות אביו שדאג לספק מים לצמאים. \u0003שנאמר: \"וסביביו נשערה מאד\"\u0004 (תהלים נ, ג), הרי זה \u0003מלמד שהקדוש ברוך הוא מדקדק עם סביביו,\u0004 כלומר, הקרובים לו, \u0003כחוט השערה\u0004 (\"נשערה\") ומענישם עונש חמור על כל חטא קטן. \u0003ר' חנינא אמר: מהכא\u0004 \u0005[מכאן,\u0006 מפסוק זה\u0005]\u0006 הראיה לאותו רעיון — שנאמר: \u0003\"אל נערץ בסוד קדשים רבה ונורא על כל סביביו\"\u0004 (שם פט, ח) כלומר, הקדוש ברוך הוא נורא יותר דווקא בסובבים אותו, הקרובים אליו.","\u0003אפילו שמע\u0004 אדם \u0003מן הנשים\u0004 שהיו \u0003אומרות \"מת איש פלוני\" — דיו\u0004 כדי להעיד על מותו. \u0003ר' יהודה אומר: אפילו שמע מן התינוקות\u0004 שהיו \u0003אומרים \"הרי אנו הולכין לספוד ולקבור את איש פלוני\",\u0004 אפשר לסמוך על כך. ועוד, סומכים על המספר שמת אדם \u0003בין שהוא מתכוין\u0004 להעיד ולהתיר את אשת המת, \u0003ובין שאינו מתכוין\u0004 אלא עושה זאת בדרך סיפור בלבד.","\u0003ר' יהודה בן בבא אומר: בישראל\u0004 סומכים על עדות זו \u0003אף על פי שהוא מתכוין\u0004 להתיר, \u0003ובגוי אם היה מתכוין\u0004 להעיד — \u0003אין עדותו עדות,\u0004 שאין סומכים על עדות הגוי. ואין מקבלים דבריו אלא כאשר אינו מתכוון לשם עדות.","שנינו במשנה שאפשר לסמוך על מה שהתינוקות אומרים: \"הרי אנו הולכים לספוד ולקבור את איש פלוני\". ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003לא אזלי\u0004 \u0005[הלכו]\u0006 כלומר, שחושבים שימות אותו אדם והולכים לספוד לו, ובסופו של דבר לא מת? \u0003אמר רב יהודה אמר שמואל: דקאמרי\u0004 \u0005[שאומרים]\u0006 התינוקות: \u0003\"הרינו באין מלספוד ומלקבור את איש פלוני\".\u0004","ושואלים: כיון שתינוקות הם, \u0003ודלמא קמצא בעלמא שכיב ליה ואסיקו ליה על שמיה\u0004 \u0005[ושמא חגב בלבד\u0006 ששיחקו בו \u0005מת לו והעלו אותו,\u0006 וקראו לו, \u0005על שמו\u0006 של אותו אדם\u0005]\u0006 ועשו התינוקות משחק לויה של הספד, ואין מכאן ראיה! ומשיבים: \u0003דקאמרי\u0004 \u0005[שאומרים]\u0006 התינוקות: \u0003\"כן וכן רבנן הוו התם. כן וכן ספדני הוו התם\u0004 \u0005[כך וכך חכמים היו שם, כך וכך ספדנים היו שם]\u0006 \u0003\",\u0004 שוודאי הם מספרים על מאורע שהיה.","שנינו במשנה: \u0003ובגוי, אם היה מתכוין\u0004 להעיד — אין עדותו עדות, \u0003אמר רב יהודה אמר שמואל: לא שנו אלא שנתכוין להתיר\u0004 בעדותו את האשה, \u0003אבל\u0004 אם \u0003נתכוין להעיד\u0004 סתם על מות אדם — \u0003עדותו עדות\u0004 אף להתיר את אשתו. ושואלים: \u0003היכי ידעינן\u0004 \u0005[איך אנו יודעים]\u0006 מה היתה כוונתו של הגוי שהעיד? \u0003אמר רב יוסף:\u0004 אם \u0003בא לבית דין ואמר: \"איש פלוני מת, השיאו את אשתו\" — זהו נתכוין להתיר.\u0004 אם סיפר: \u0003\"מת\" סתם — זהו נתכוין לעדות.\u0004","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 בשם אמוראים אחרים, \u0003אמר ריש לקיש: לא שנו\u0004 שאין מקבלים את עדות הגוי \u0003אלא\u0004 כ\u0003שנתכוין\u0004 בדבריו \u0003להתיר\u0004 את האשה, \u0003אבל\u0004 אם \u0003נתכוין להעיד — עדותו עדות. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן: לא כך היה מעשה באושעיא ברבי\u0004 כלומר, ר' אושעיא גדול הדור \u0003שהתירם\u0004 להינשא על פי עדות גויים \u0003עם שמנים וחמשה זקנים. אמר להם\u0004 לזקנים: \u0003לא שנו\u0004 שאין סומכים על גוי \u0003אלא שנתכוין להתיר, אבל נתכוין להעיד — עדותו עדות. ולא הודו לו חכמים\u0004 לר' אושעיא בחלוקה זו, אלא אין סומכים כלל על עדות גוי.","ושואלים: \u0003אלא מתניתין דקתני\u0004 \u0005[משנתנו ששנה\u0006 בה\u0005]\u0006 \u0003ובגוי, אם היה מתכוין — אין עדותו עדות,\u0004 משמע שאם לא התכוון יסמכו על דבריו, \u0003היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה\u0006 אפשרות\u0005]\u0006 לקבל בכל זאת את דבריו? ומשיבים: \u0003במסיח לפי תומו,\u0004 כלומר, שהגוי סיפר לתומו מעשה שהיה, ולא בא כלל לשם עדות. \u0003כי ההוא דהוה קאמר ואזיל\u0004 \u0005[כמו אותו\u0006 גוי \u0005שהיה אומר והולך]:\u0006 \u0003\"מאן איכא בי\u0004 \u0005[מי נמצא\u0006 ב\u0005ביתו]\u0006 של \u0003חיואי, מאן איכא בי\u0004 \u0005[מי נמצא\u0006 ב\u0005ביתו]\u0006 של \u0003חיואי,\u0004 רצוני לספר על כי \u0003שכיב\u0004 \u0005[מת]\u0006 \u0003חיואי\", ואנסבה\u0004 \u0005[והשיאה]\u0006 \u0003רב יוסף לדביתהו\u0004 \u0005[את אשתו]\u0006 של חיואי על סמך דברי הגוי. וכיוצא בו \u0003ההוא דהוה קאמר ואזיל\u0004 \u0005[\u0006גוי \u0005אחד שהיה אומר והולך]:\u0006 \u0003\"ווי ליה לפרשא זריזא דהוה\u0004 \u0005[אוי לו לפרש הזריז שהיה]\u0006 \u0003בפומבדיתא דשכיב\u0004 \u0005[שמת]\u0006 \u0003\"\u0004\u0003ואנסבה\u0004 \u0005[והשיאה]\u0006 \u0003רב יוסף, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רבא, לדביתהו\u0004 \u0005[את אשתו].\u0006","מסופר: \u0003ההוא דהוה קאמר ואזיל\u0004 \u0005[\u0006גוי \u0005אחד שהיה אומר והולך]:\u0006 \u0003\"מאן איכא בי\u0004 \u0005[מי נמצא\u0006 ב\u0005ביתו]\u0006 של \u0003חסא, טבע חסא!\" אמר רב נחמן\u0004 בלשון שבועה: \u0003האלקים! אכלו\u0004 כבר \u0003כוורי\u0004 \u0005[הדגים]\u0006 את \u0003חסא.\u0004 ומספרים: \u0003מדיבוריה\u0004 \u0005[מתוך דבריו]\u0006 אלה של \u0003רב נחמן,\u0004 אף על פי שלא התיר בבית דין, \u0003אזלא דביתהו\u0004 \u0005[הלכה אשתו]\u0006 של \u0003חסא ואינסבא\u0004 \u0005[ונישאה],\u0006 \u0003ולא אמרו לה ולא מידי\u0004 \u0005[כלום],\u0006 שלא מיחו בה. \u0003אמר רב אשי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 ממעשה זה, \u0003הא דאמור רבנן\u0004 \u0005[זה שאמרו חכמים]\u0006 שאם טבע ב\u0003מים שאין להם סוף אשתו אסורה — הני מילי\u0004 \u0005[דברים אלה]\u0006 שאסורה להינשא אמורים \u0003לכתחלה, אבל אי נסיב\u0004 \u0005[אם נשא אותה]\u0006 אדם — \u0003לא מפקינן לה מיניה\u0004 \u0005[אין מוציאים אותה ממנו].\u0006","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שלא כך היה המעשה, אלא \u0003אנסבה\u0004 \u0005[השיאה]\u0006 \u0003רב נחמן לדביתהו\u0004 \u0005[את אשתו\u0006 של חסא\u0005],\u0006 וכך \u0003אמר: חסא גברא רבה איתיה\u0004 \u0005[אדם גדול הוא],\u0006 \u0003אם איתא דסליק\u0004 \u0005[אם אמנם עלה]\u0006 מן המים — \u0003קלא אית ליה למילתא\u0004 \u0005[קול יש לו לדבר]\u0006 וכיון שלא נשמע זמן רב דבר בענין חסא — מן הסתם מת. ומעירים: \u0003ולא היא\u0004 (אין הדבר כך), \u0003לא שנא גברא רבה לא שנא לאו גברא רבה\u0004 \u0005[אינו שונה אדם גדול\u0006 ו\u0005אינו שונה שאינו אדם גדול],\u0006 אם נישאה על פי עדות שטבע בעלה במים שאין להם סוף, \u0003דיעבד — אין\u0004 \u0005[כן]\u0006 לא תצא, \u0003לכתחלה — לא\u0004 תינשא.","מסופר: \u0003ההוא\u0004 \u0005[אותו]\u0006 \u0003גוי דהוה קאמר ליה\u0004 \u0005[שהיה אומר לו]\u0006 \u0003ל\u0004אדם מ\u0003ישראל: קטול אספסתא ושדי לחיואי בשבתא\u0004 \u0005[קצור\u0006 את ה\u0005אספסת והטל לבהמות בשבת]\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 תעשה כן — \u0003קטילנא לך כדקטילנא\u0004 \u0005[אהרוג אותך כפי שהרגתי]\u0006 את \u0003פלוני בר\u0004 \u0005[בן]\u0006 \u0003ישראל,\u0004 היהודי, \u0003דאמרי ליה\u0004 \u0005[שאמרתי לו]:\u0006 \u0003בשיל\u0004 \u0005[בשל]\u0006 \u0003לי קדירה בשבת, ולא בשיל\u0004 \u0005[בישל]\u0006 \u0003לי, וקטילתיה\u0004 \u0005[והרגתיו].\u0006 \u0003שמעה דביתהו\u0004 \u0005[אשתו]\u0006 של אותו אדם שנעלם, את מה שאמר הגוי, \u0003ואתאי לקמיה\u0004 \u0005[ובאה לפני]\u0006 \u0003אביי\u0004 שיתיר אותה להינשא, על סמך דבריו של הגוי שאמר שהרג אותו. \u0003שהיתא\u0004 \u0005[השהה אותה]\u0006"]]};
